itiveList(\\"ids\\", \\"number\\", ids);\\n        return this.call(model, \\"web_read\\", [ids], kwargs);\\n    }\\n\\n    /**\\n     * @param {string} model\\n     * @param {number[]} ids\\n     * @param {object} [kwargs={}]\\n     * @param {object} [kwargs.context]\\n     * @param {string} [kwargs.field_name]\\n     * @param {number} [kwargs.offset]\\n     * @param {object} [kwargs.specification]\\n     * @returns {Promise<any[]>}\\n     */\\n    webResequence(model, ids, kwargs = {}) {\\n        validatePrimitiveList(\\"ids\\", \\"number\\", ids);\\n        return this.call(model, \\"web_resequence\\", [ids], {\\n            ...kwargs,\\n            specification: kwargs.specification || {},\\n        });\\n    }\\n\\n    /**\\n     * @param {string} model\\n     * @param {import(\\"@web/core/domain\\").DomainListRepr} domain\\n     * @param {any} [kwargs={}]\\n     * @returns {Promise<any[]>}\\n     */\\n    webSearchRead(model, domain, kwargs = {}) {\\n        validateArray(\\"domain\\", domain);\\n        return this.call(model, \\"web_search_read\\", [], { ...kwargs, domain });\\n    }\\n\\n    /**\\n     * @param {string} model\\n     * @param {number[]} ids\\n     * @param {any} data\\n     * @param {any} [kwargs={}]\\n     * @returns {Promise<boolean>}\\n     */\\n    write(model, ids, data, kwargs = {}) {\\n        validatePrimitiveList(\\"ids\\", \\"number\\", ids);\\n        validateObject(\\"data\\", data);\\n        return this.call(model, \\"write\\", [ids, data], kwargs);\\n    }\\n\\n    /**\\n     * @param {string} model\\n     * @param {number[]} ids\\n     * @param {any} data\\n     * @param {any} [kwargs={}]\\n     * @param {Object} [kwargs.specification]\\n     * @param {Object} [kwargs.context]\\n     * @returns {Promise<any[]>}\\n     */\\n    webSave(model, ids, data, kwargs = {}) {\\n        validatePrimitiveList(\\"ids\\", \\"number\\", ids);\\n        validateObject(\\"data\\", data);\\n        return this.call(model, \\"web_save\\", [ids, data], kwargs);\\n    }\\n\\n    /**\\n     * @param {string} model\\n     * @param {number[]} ids\\n     * @param {Object[]} data\\n     * @param {Object} [kwargs={}]\\n     * @param {Object} [kwargs.specification]\\n     * @param {Object} [kwargs.context]\\n     * @returns {Promise<any[]>}\\n     */\\n    async webSaveMulti(model, ids, data, kwargs = {}) {\\n        validatePrimitiveList(\\"ids\\", \\"number\\", ids);\\n        validateArray(\\"data\\", data);\\n        data.forEach((d) => {\\n            validateObject(\\"data item\\", d);\\n        });\\n        return this.call(model, \\"web_save_multi\\", [ids, data], kwargs);\\n    }\\n}\\n\\n/**\\n * Note:\\n *\\n * To hide RPC errors, use the following API:\\n *\\n * this.orm = useService('orm');\\n * ...\\n * const result = await this.orm.silent.read('res.partner', [id]);\\n */\\nexport const ormService = {\\n    async: [\\n        \\"call\\",\\n        \\"create\\",\\n        \\"nameGet\\",\\n        \\"read\\",\\n        \\"formattedReadGroup\\",\\n        \\"webReadGroup\\",\\n        \\"search\\",\\n        \\"searchRead\\",\\n        \\"unlink\\",\\n        \\"webResequence\\",\\n        \\"webSearchRead\\",\\n        \\"write\\",\\n    ],\\n    start() {\\n        return new ORM();\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"orm\\", ormService);\\n", "import { Component, onWillDestroy, useChildSubEnv, useEffect, useRef, useState } from \\"@odoo/owl\\";\\nimport { sortBy } from \\"@web/core/utils/arrays\\";\\nimport { ErrorHandler } from \\"@web/core/utils/components\\";\\n\\nconst OVERLAY_ITEMS = [];\\nexport const OVERLAY_SYMBOL = Symbol(\\"Overlay\\");\\n\\nclass OverlayItem extends Component {\\n    static template = \\"web.OverlayContainer.Item\\";\\n    static components = {};\\n    static props = {\\n        component: { type: Function },\\n        props: { type: Object },\\n        env: { type: Object, optional: true },\\n    };\\n\\n    setup() {\\n        this.rootRef = u