xtractProps: ({ value, update }) => ({ value, update }),\\n        message: _t(\\"Value not supported\\"),\\n        stringify: (val, disambiguate = true) => {\\n            if (disambiguate) {\\n                return formatValue(val);\\n            }\\n            return String(val);\\n        },\\n        ...info,\\n    };\\n}\\n\\nexport function getDefaultValue(fieldDef, operator, value = null) {\\n    const { isSupported, shouldResetValue, defaultValue } = getValueEditorInfo(fieldDef, operator);\\n    if (value === null || !isSupported(value) || shouldResetValue?.(value)) {\\n        return defaultValue(operator);\\n    }\\n    return value;\\n}\\n", "import { constructTreeFromDomain } from \\"./construct_tree_from_domain\\";\\nimport { introduceVirtualOperators } from \\"./virtual_operators\\";\\n\\nexport function treeFromDomain(domain, options = {}) {\\n    const tree = constructTreeFromDomain(domain, options.distributeNot);\\n    return introduceVirtualOperators(tree, options);\\n}\\n", "import { constructTreeFromExpression } from \\"./construct_tree_from_expression\\";\\nimport { introduceVirtualOperators } from \\"./virtual_operators\\";\\n\\nexport function treeFromExpression(expression, options = {}) {\\n    const tree = constructTreeFromExpression(expression, options);\\n    return introduceVirtualOperators(tree, options);\\n}\\n", "import {\\n    deserializeDate,\\n    deserializeDateTime,\\n    formatDate,\\n    formatDateTime,\\n} from \\"@web/core/l10n/dates\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { getOperatorLabel } from \\"@web/core/tree_editor/tree_editor_operator_editor\\";\\nimport { unique, zip } from \\"@web/core/utils/arrays\\";\\nimport { condition, Expression, isTree, normalizeValue } from \\"./condition_tree\\";\\nimport { constructTreeFromDomain } from \\"./construct_tree_from_domain\\";\\nimport { disambiguate, getResModel, isId } from \\"./utils\\";\\ni