lection.\\n *\\n * @param {Object} [options={}]\\n * @param {[string, string][]} [options.selection]\\n * @param {Object} [options.field]\\n * @returns {string}\\n */\\nexport function formatSelection(value, options = {}) {\\n    const selection = options.selection || (options.field && options.field.selection) || [];\\n    const option = selection.find((option) => option[0] === value);\\n    return option ? option[1] : \\"\\";\\n}\\n\\n/**\\n * Returns the value or an empty string if it's falsy.\\n *\\n * @param {string | false} value\\n * @returns {string}\\n */\\nexport function formatText(value) {\\n    return value ? value.toString() : \\"\\";\\n}\\n\\n/**\\n * Returns the value.\\n * Note that, this function is added to be coherent with the rest of the formatters.\\n *\\n * @param {html} value\\n * @returns {html}\\n */\\nexport function formatHtml(value) {\\n    return value || \\"\\";\\n}\\n\\nexport function formatJson(value) {\\n    return (value && JSON.stringify(value)) || \\"\\";\\n}\\n\\nregistry\\n    .category(\\"formatters\\")\\n    .add(\\"binary\\", formatBinary)\\n    .add(\\"boolean\\", formatBoolean)\\n    .add(\\"char\\", formatChar)\\n    .add(\\"date\\", formatDate)\\n    .add(\\"datetime\\", formatDateTime)\\n    .add(\\"float\\", formatFloat)\\n    .add(\\"float_factor\\", formatFloatFactor)\\n    .add(\\"float_time\\", formatFloatTime)\\n    .add(\\"html\\", formatHtml)\\n    .add(\\"integer\\", formatInteger)\\n    .add(\\"json\\", formatJson)\\n    .add(\\"many2one\\", formatMany2one)\\n    .add(\\"many2one_reference\\", formatMany2oneReference)\\n    .add(\\"one2many\\", formatX2many)\\n    .add(\\"many2many\\", formatX2many)\\n    .add(\\"monetary\\", formatMonetary)\\n    .add(\\"percentage\\", formatPercentage)\\n    .add(\\"properties\\", formatProperties)\\n    .add(\\"properties_definition\\", formatProperties)\\n    .add(\\"reference\\", formatReference)\\n    .add(\\"selection\\", formatSelection)\\n    .add(\\"text\\", formatText);\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { loadBundle } from \\"@web/core/assets\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { formatFloat } from \\"@web/views/fields/formatters\\";\\nimport { standardFieldProps } from \\"@web/views/fields/standard_field_props\\";\\n\\nimport { Component, onWillStart, useEffect, useRef } from \\"@odoo/owl\\";\\n\\nexport class GaugeField extends Component {\\n    static template = \\"web.GaugeField\\";\\n    static props = {\\n        ...standardFieldProps,\\n        maxValueField: { type: String, optional: true },\\n        maxValue: { type: Number, optional: true },\\n        title: { type: String, optional: true },\\n    };\\n    static defaultProps = {\\n        maxValue: 100,\\n    };\\n\\n    setup() {\\n        this.chart = null;\\n        this.canvasRef = useRef(\\"canvas\\");\\n\\n        onWillStart(async () => await loadBundle(\\"web.chartjs_lib\\"));\\n\\n        useEffect(() => {\\n            this.renderChart();\\n            return () => {\\n                if (this.chart) {\\n                    this.chart.destroy();\\n                }\\n            };\\n        });\\n    }\\n\\n    get title() {\\n        return this.props.title || this.props.record.fields[this.props.name].string || \\"\\";\\n    }\\n\\n    get formattedValue() {\\n        return formatFloat(this.props.record.data[this.props.name], {\\n            humanReadable: true,\\n            decimals: 1,\\n        });\\n    }\\n\\n    renderChart() {\\n        const gaugeValue = this.props.record.data[this.props.name];\\n        let maxValue = this.props.maxValueField ? this.props.record.data[this.props.maxValueField] : this.props.maxValue;\\n        maxValue = Math.max(gaugeValue, maxValue);\\n        let maxLabel = maxValue;\\n        if (gaugeValue === 0 && maxValue === 0) {\\n            maxValue = 1;\\n            maxLabel = 0;\\n        }\\n        const config = {\\n            type: \\"doughnut\\"