                     caretSize: 0,\\n                    },\\n                },\\n                scales: {\\n                    y: {\\n                        display: false,\\n                    },\\n                    x: {\\n                        grid: {\\n                            color: GRAPH_GRID_COLOR,\\n                        },\\n                        ticks: {\\n                            color: GRAPH_LABEL_COLOR,\\n                        },\\n                        border: {\\n                            color: GRAPH_GRID_COLOR,\\n                        },\\n                    },\\n                },\\n                maintainAspectRatio: false,\\n                elements: {\\n                    line: {\\n                        tension: 0.000001,\\n                    },\\n                },\\n            },\\n        };\\n    }\\n}\\n\\nexport const journalDashboardGraphField = {\\n    component: JournalDashboardGraphField,\\n    supportedTypes: [\\"text\\"],\\n    extractProps: ({ attrs }) => ({\\n        graphType: attrs.graph_type,\\n    }),\\n};\\n\\nregistry.category(\\"fields\\").add(\\"dashboard_graph\\", journalDashboardGraphField);\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\nimport { formatJson } from \\"@web/views/fields/formatters\\";\\n\\nimport { Component } from \\"@odoo/owl\\";\\n\\nexport class JsonField extends Component {\\n    static template = \\"web.JsonField\\";\\n    static props = {\\n        ...standardFieldProps,\\n    };\\n    get formattedValue() {\\n        return formatJson(this.props.record.data[this.props.name]);\\n    }\\n}\\n\\nexport const jsonField = {\\n    component: JsonField,\\n    displayName: _t(\\"Json\\"),\\n    supportedTypes: [\\"json\\"],\\n};\\n\\nregistry.category(\\"fields\\").add(\\"json\\", jsonField);\\n", "import { _t } from \\"@web/core/l10n/transl