   let deleteRecord;\\n        let deleteButtonLabel = undefined;\\n        const isDuplicate = !!record;\\n\\n        const params = { activeFields, fields };\\n        if (isMany2Many) {\\n            params.mode = activeActions.write ? \\"edit\\" : \\"readonly\\";\\n        } else {\\n            params.mode = readonly || !activeActions.write ? \\"readonly\\" : \\"edit\\";\\n        }\\n        if (record) {\\n            const { delete: canDelete, onDelete } = activeActions;\\n            deleteRecord = viewMode === \\"kanban\\" && canDelete ? () => onDelete(record) : null;\\n            deleteButtonLabel = activeActions.type === \\"one2many\\" ? _t(\\"Delete\\") : _t(\\"Remove\\");\\n        } else {\\n            params.context = makeContext([list.context, context]);\\n            params.withoutParent = isMany2Many;\\n        }\\n        record = await list.extendRecord(params, record);\\n\\n        const _onClose = () => {\\n            list.editedRecord?.switchMode(\\"readonly\\");\\n            onClose?.();\\n        };\\n\\n        addDialog(\\n            X2ManyFieldDialog,\\n            {\\n                config: env.config,\\n                archInfo,\\n                record,\\n                controls,\\n                addNew: () => getList().extendRecord(params),\\n                save: (rec) => {\\n                    if (isDuplicate && rec.id === record.id) {\\n                        return updateRecord(rec);\\n                    } else {\\n                        return saveRecord(rec);\\n                    }\\n                },\\n                title,\\n                delete: deleteRecord,\\n                deleteButtonLabel: deleteButtonLabel,\\n            },\\n            { onClose: _onClose }\\n        );\\n    }\\n\\n    let recordIsOpen = false;\\n    return (params) => {\\n        if (recordIsOpen) {\\n            return;\\n        }\\n        recordIsOpen = true;\\n\\n        const onClose = params.onClose;\\n        params = {\\n            ...params,\\n            onClose: (...args) => {\\n                recordIsOpen = false;\\n                if (onClose) {\\n                    return onClose(...args);\\n                }\\n            },\\n        };\\n\\n        try {\\n            return openRecord(params);\\n        } catch (e) {\\n            recordIsOpen = false;\\n            throw e;\\n        }\\n    };\\n}\\n\\nexport function useX2ManyCrud(getList, isMany2Many) {\\n    let saveRecord; // FIXME: isn't this \\"createRecord\\" instead?\\n    if (isMany2Many) {\\n        saveRecord = async (object) => {\\n            const list = getList();\\n            if (Array.isArray(object)) {\\n                return list.addAndRemove({ add: object });\\n            } else {\\n                // object instanceof Record\\n                await object.save({ reload: false });\\n                return list.linkTo(object.resId);\\n            }\\n        };\\n    } else {\\n        saveRecord = async (record) => getList().validateExtendedRecord(record);\\n    }\\n\\n    const updateRecord = async (record) => {\\n        if (isMany2Many) {\\n            await record.save();\\n        }\\n        return getList().validateExtendedRecord(record);\\n    };\\n\\n    const removeRecord = (record) => {\\n        const list = getList();\\n        if (isMany2Many) {\\n            return list.forget(record);\\n        }\\n        return list.delete(record);\\n    };\\n\\n    return {\\n        saveRecord,\\n        updateRecord,\\n        removeRecord,\\n    };\\n}\\n", "import { Component } from \\"@odoo/owl\\";\\nimport { evaluateExpr } from \\"@web/core/py_js/py\\";\\nimport { getClassNameFromDecoration } from \\"@web/views/utils\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { DateTimeField } from \\"../datetime/datetime_field\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\nimport { capitalize } from \\"@web/core/utils/strings\\";\\nimport { formatDate } from \\"../formatters\\";\\n\\nconst { DateTime } = luxon;\\n\\nexport class RemainingDaysField extends Component {\\n    static components = { DateTimeField };\\n\\n    static props = {\\n        ...standardFieldProps,\\n        classes: { type: Object, optional: true },\\n    };\\n\\n    static defaultProps = {\\n        classes: {\\n            bf: \\"days <= 0\\",\\n            danger: \\"days < 0\\",\\n            warning: \\"days == 0\\",\\n        },\\n    };\\n\\n    static template = \\"web.RemainingDaysField\\";\\n\\n    get diffDays() {\\n        const { record, name } = this.props;\\n        const value = record.data[name];\\n        if (!value) {\\n            return null;\\n        }\\n        const today = DateTime.local().startOf(\\"day\\");\\n        const diff = value.startOf(\\"day\\").diff(today, \\"days\\");\\n        return Math.floor(diff.days);\\n    }\\n\\n    get diffString() {\\n        if (this.diffDays === null) {\\n            return \\"\\";\\n        }\\n        if (Math.abs(this.diffDays) > 99) {\\n            return this.formattedValue;\\n        }\\n        const { record, name } = this.props;\\n        const value = record.data[name];\\n        return capitalize(value.toRelativeCalendar());\\n    }\\n\\n    get formattedValue() {\\n        const { record, name } = this.props;\\n        return formatDate(record.data[name]);\\n    }\\n\\n    get numericValue() {\\n        const { record, name } = this.props;\\n        return formatDate(record.data[name], { numeric: true });\\n    }\\n\\n    get classNames() {\\n        if (this.diffDays === null) {\\n            return null;\\n        }\\n        if (!this.props.record.isActive) {\\n            return null;\\n        }\\n        const classNames = {};\\n        const evalContext = { days: this.diffDays, record: this.props.record.evalContext };\\n        for (const decoration in this.props.classes) {\\n            const value = evaluateExpr(this.props.classes[decoration], evalContext);\\n            classNames[getClassNameFromDecoration(decoration)] = value;\\n        }\\n        return classNames;\\n    }\\n\\n    get dateTimeFieldProps() {\\n        return Object.fromEntries(\\n            Object.entries(this.props).filter(([key]) => standardFieldProps[key])\\n        );\\n    }\\n}\\n\\nexport const remainingDaysField = {\\n    component: RemainingDaysField,\\n    displayName: _t(\\"Remaining Days\\"),\\n    supportedTypes: [\\"date\\", \\"datetime\\"],\\n    extractProps: ({ options }) => ({\\n        classes: options.classes,\\n    }),\\n};\\n\\nregistry.category(\\"fields\\").add(\\"remaining_days\\", remainingDaysField);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { SelectionField, selectionField } from \\"@web/views/fields/selection/selection_field\\";\\n\\n/**\\n * The purpose of this field is to be able to define some values which should not be\\n * displayed on our selection field, this way we can have multiple views for the same model\\n * that uses different possible sets of values on the same selection field.\\n */\\nexport class FilterableSelectionField extends SelectionField {\\n    static props = {\\n        ...SelectionField.props,\\n        whitelist_fname: { type: String, optional: true },\\n        whitelisted_values: { type: Array, optional: true },\\n        blacklisted_values: { type: Array, optional: true },\\n    };\\n\\n    /**\\n     * @override\\n     */\\n    get options() {\\n        let options = super.options;\\n        if (this.props.whitelist_fname) {\\n            options = options.filter((option) => {\\n                return (\\n                    option[0] === this.props.record.data[this.props.name] ||\\n                    this.props.record.data[this.props.whitelist_fname].includes(option[0])\\n                );\\n            });\\n        } else if (this.props.whitelisted_values) {\\n            options = options.filter((option) => {\\n                return (\\n                    option[0] === this.props.record.data[this.props.name] ||\\n                    this.props.whitelisted_values.includes(option[0])\\n                );\\n            });\\n        } else if (this.props.blacklisted_values) {\\n            options = options.filter((option) => {\\n                return (\\n                    option[0] === this.props.record.data[this.props.name] ||\\n                    !this.props.blacklisted_values.includes(option[0])\\n                );\\n            });\\n        }\\n        return options;\\n    }\\n}\\n\\nexport const filterableSelectionField = {\\n    ...selectionField,\\n    component: FilterableSelectionField,\\n    supportedOptions: [\\n        {\\n            label: \\"Whitelisted Values\\",\\n            name: \\"whitelisted_values\\",\\n            type: \\"string\\",\\n        },\\n        {\\n            label: \\"Blacklisted Values\\",\\n            name: \\"blacklisted_values\\",\\n            type: \\"string\\",\\n        },\\n        {\\n            label: \\"Whitelisted field name\\",\\n            name: \\"whitelist_fname\\",\\n            type: \\"string\\",\\n        },\\n    ],\\n    extractProps({ options }) {\\n        const props = selectionField.extractProps(...arguments);\\n        props.whitelist_fname = options.whitelist_fname;\\n        props.whitelisted_values = options.whitelisted_values;\\n        props.blacklisted_values = options.blacklisted_values;\\n        return props;\\n    },\\n};\\n\\nregistry.category(\\"fields\\").add(\\"filterable_selection\\", filterableSelectionField);\\n", "import { Component } from \\"@odoo/owl\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { SelectMenu } from \\"@web/core/select_menu/select_menu\\";\\nimport { getFieldDomain } from \\"@web/model/relational_model/utils\\";\\nimport { useSpecialData } from \\"@web/views/fields/relational_utils\\";\\nimport { hasTouch } from \\"@web/core/browser/feature_detection\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\n\\nexport class SelectionField extends Component {\\n    static components = {\\n        SelectMenu,\\n    };\\n    static template = \\"web.SelectionField\\";\\n    static props = {\\n        ...standardFieldProps,\\n        placeholder: { type: String, optional: true },\\n        required: { type: Boolean, optional: true },\\n        domain: { type: [Array, Function], optional: true },\\n        autosave: { type: Boolean, optional: true },\\n    };\\n    static defaultProps = {\\n        autosave: false,\\n    };\\n\\n    setup() {\\n        this.type = this.props.record.fields[this.props.name].type;\\n        if (this.type === \\"many2one\\") {\\n            this.specialData = useSpecialData((orm, props) => {\\n                const { relation } = props.record.fields[props.name];\\n                const domain = getFieldDomain(props.record, props.name, props.domain);\\n                return orm.call(relation, \\"name_search\\", [\\"\\", domain]);\\n            });\\n        }\\n    }\\n\\n    get choices() {\\n        return this.options.map(([value, label]) => ({ value, label }));\\n    }\\n    get isBottomSheet() {\\n        return this.env.isSmall && hasTouch();\\n    }\\n    get options() {\\n        switch (this.type) {\\n            case \\"many2one\\":\\n                return [...this.specialData.data];\\n            case \\"selection\\":\\n                return this.props.record.fields[this.props.name].selection.filter(\\n                    (option) => option[0] !== false && option[1] !== \\"\\"\\n                );\\n            default:\\n                return [];\\n        }\\n    }\\n    get string() {\\n        switch (this.type) {\\n            case \\"many2one\\":\\n                return this.props.record.data[this.props.name]\\n                    ? this.props.record.data[this.props.name].display_name\\n                    : \\"\\";\\n            case \\"selection\\":\\n                return this.props.record.data[this.props.name] !== false\\n                    ? this.options.find((o) => o[0] === this.props.record.data[this.props.name])[1]\\n                    : \\"\\";\\n            default:\\n                return \\"\\";\\n        }\\n    }\\n    get value() {\\n        const rawValue = this.props.record.data[this.props.name];\\n        return this.type === \\"many2one\\" && rawValue ? rawValue.id : rawValue;\\n    }\\n\\n    stringify(value) {\\n        return JSON.stringify(value);\\n    }\\n\\n    onChange(value) {\\n        switch (this.type) {\\n            case \\"many2one\\":\\n                if (value === null) {\\n                    this.props.record.update(\\n                        { [this.props.name]: false },\\n                        { save: this.props.autosave }\\n                    );\\n                } else {\\n                    const option = this.options.find((option) => option[0] === value);\\n                    this.props.record.update(\\n                        {\\n                            [this.props.name]: { id: option[0], display_name: option[1] },\\n                        },\\n                        { save: this.props.autosave }\\n                    );\\n                }\\n                break;\\n            case \\"selection\\":\\n                this.props.record.update(\\n                    { [this.props.name]: value },\\n                    { save: this.props.autosave }\\n                );\\n                break;\\n        }\\n    }\\n}\\n\\nexport const selectionField = {\\n    component: SelectionField,\\n    displayName: _t(\\"Selection\\"),\\n    supportedOptions: [\\n        {\\n            label: _t(\\"Dynamic Placeholder\\"),\\n            name: \\"placeholder_field\\",\\n            type: \\"field\\",\\n            availableTypes: [\\"char\\"],\\n        },\\n    ],\\n    supportedTypes: [\\"many2one\\", \\"selection\\"],\\n    isEmpty: (record, fieldName) => record.data[fieldName] === false,\\n    extractProps({ viewType, placeholder }, dynamicInfo) {\\n        const props = {\\n            autosave: viewType === \\"kanban\\",\\n            placeholder,\\n            required: dynamicInfo.required,\\n            domain: dynamicInfo.domain,\\n        };\\n        if (viewType === \\"kanban\\") {\\n            props.readonly = dynamicInfo.readonly;\\n        }\\n        return props;\\n    },\\n};\\n\\nregistry.category(\\"fields\\").add(\\"selection\\", selectionField);\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { SignatureDialog } from \\"@web/core/signature/signature_dialog\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { imageUrl } from \\"@web/core/utils/urls\\";\\nimport { isBinarySize } from \\"@web/core/utils/binary\\";\\nimport { fileTypeMagicWordMap } from \\"@web/views/fields/image/image_field\\";\\nimport { standardFieldProps } from \\"@web/views/fields/standard_field_props\\";\\n\\nimport { Component, useState } from \\"@odoo/owl\\";\\n\\nconst placeholder = \\"/web/static/img/placeholder.png\\";\\n\\nexport class SignatureField extends Component {\\n    static template = \\"web.SignatureField\\";\\n    static props = {\\n        ...standardFieldProps,\\n        defaultFont: { type: String },\\n        fullName: { type: String, optional: true },\\n        height: { type: Number, optional: true },\\n        previewImage: { type: String, optional: true },\\n        width: { type: Number, optional: true },\\n        type: { validate: (t) => [\\"initial\\", \\"signature\\"].includes(t), optional: true },\\n    };\\n    static defaultProps = {\\n        type: \\"signature\\",\\n    };\\n\\n    setup() {\\n        this.displaySignatureRatio = 3;\\n\\n        this.dialogService = useService(\\"dialog\\");\\n        this.state = useState({\\n            isValid: true,\\n        });\\n    }\\n\\n    get rawCacheKey() {\\n        return this.props.record.data.write_date;\\n    }\\n\\n    get getUrl() {\\n        const { name, previewImage, record } = this.props;\\n        if (this.state.isValid && this.value) {\\n            if (isBinarySize(this.value)) {\\n                return imageUrl(record.resModel, record.resId, previewImage || name, {\\n                    unique: this.rawCacheKey,\\n                });\\n            } else {\\n                // Use magic-word technique for detecting image type\\n                const magic = fileTypeMagicWordMap[this.value[0]] || \\"png\\";\\n                return `data:image/${magic};base64,${this.props.record.data[this.props.name]}`;\\n            }\\n        }\\n        return placeholder;\\n    }\\n\\n    get sizeStyle() {\\n        let { width, height } = this.props;\\n\\n        if (!this.value) {\\n            if (width && height) {\\n                width = Math.min(width, this.displaySignatureRatio * height);\\n                height = width / this.displaySignatureRatio;\\n            } else if (width) {\\n                height = width / this.displaySignatureRatio;\\n            } else if (height) {\\n                width = height * this.displaySignatureRatio;\\n            }\\n        }\\n\\n        let style = \\"\\";\\n        if (width) {\\n            style += `width:${width}px; max-width:${width}px;`;\\n        }\\n        if (height) {\\n            style += `height:${height}px; max-height:${height}px;`;\\n        }\\n        return style;\\n    }\\n\\n    get value() {\\n        return this.props.record.data[this.props.name];\\n    }\\n\\n    onClickSignature() {\\n        if (!this.props.readonly) {\\n            const nameAndSignatureProps = {\\n                displaySignatureRatio: 3,\\n                signatureType: this.props.type,\\n                noInputName: true,\\n            };\\n            const { fullName, record } = this.props;\\n            let defaultName = \\"\\";\\n            if (fullName) {\\n                let signName;\\n                const fullNameData = record.data[fullName];\\n                if (record.fields[fullName].type === \\"many2one\\") {\\n                    // If m2o is empty, it will have falsy value in recordData\\n                    signName = fullNameData && fullNameData.display_name;\\n                } else {\\n                    signName = fullNameData;\\n                }\\n                defaultName = signName === \\"\\" ? undefined : signName;\\n            }\\n\\n            nameAndSignatureProps.defaultFont = this.props.defaultFont;\\n\\n            const dialogProps = {\\n                defaultName,\\n                nameAndSignatureProps,\\n                uploadSignature: (signature) => this.uploadSignature(signature),\\n            };\\n            this.dialogService.add(SignatureDialog, dialogProps);\\n        }\\n    }\\n\\n    onLoadFailed() {\\n        this.state.isValid = false;\\n        this.notification.add(_t(\\"Could not display the selected image\\"), {\\n            type: \\"danger\\",\\n        });\\n    }\\n\\n    /**\\n     * Upload the signature image if valid and close the dialog.\\n     *\\n     * @private\\n     */\\n    uploadSignature({ signatureImage }) {\\n        return this.props.record.update({\\n            [this.props.name]: signatureImage.split(\\",\\")[1] || false,\\n        });\\n    }\\n}\\n\\nexport const signatureField = {\\n    component: SignatureField,\\n    fieldDependencies: [{ name: \\"write_date\\", type: \\"datetime\\" }],\\n    supportedOptions: [\\n        {\\n            label: _t(\\"Prefill with\\"),\\n            name: \\"full_name\\",\\n            type: \\"field\\",\\n            availableTypes: [\\"char\\", \\"many2one\\"],\\n            help: _t(\\"The selected field will be used to pre-fill the signature\\"),\\n        },\\n        {\\n            label: _t(\\"Default font\\"),\\n            name: \\"default_font\\",\\n            type: \\"string\\",\\n        },\\n        {\\n            label: _t(\\"Size\\"),\\n            name: \\"size\\",\\n            type: \\"selection\\",\\n            choices: [\\n                { label: _t(\\"Small\\"), value: \\"[0,90]\\" },\\n                { label: _t(\\"Medium\\"), value: \\"[0,180]\\" },\\n                { label: _t(\\"Large\\"), value: \\"[0,270]\\" },\\n            ],\\n        },\\n        {\\n            label: _t(\\"Preview image field\\"),\\n            name: \\"preview_image\\",\\n            type: \\"field\\",\\n            availableTypes: [\\"binary\\"],\\n        },\\n    ],\\n    extractProps: ({ attrs, options }) => ({\\n        defaultFont: options.default_font || \\"\\",\\n        fullName: options.full_name,\\n        height: options.size ? options.size[1] || undefined : attrs.height,\\n        previewImage: options.preview_image,\\n        type: options.type,\\n        width: options.size ? options.size[0] || undefined : attrs.width,\\n    }),\\n};\\n\\nregistry.category(\\"fields\\").add(\\"signature\\", signatureField);\\n", "/**\\n * @typedef StandardFieldProps\\n * @property {string} [id]\\n * @property {string} name\\n * @property {boolean} [readonly]\\n * @property {import(\\"@web/model/relational_model/record\\").Record} record\\n */\\n\\nexport const standardFieldProps = {\\n    id: { type: String, optional: true },\\n    name: { type: String },\\n    readonly: { type: Boolean, optional: true },\\n    record: { type: Object },\\n};\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { exprToBoolean } from \\"@web/core/utils/strings\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\n\\nimport { Component } from \\"@odoo/owl\\";\\nconst formatters = registry.category(\\"formatters\\");\\n\\nexport class StatInfoField extends Component {\\n    static template = \\"web.StatInfoField\\";\\n    static props = {\\n        ...standardFieldProps,\\n        labelField: { type: String, optional: true },\\n        noLabel: { type: Boolean, optional: true },\\n        digits: { type: Array, optional: true },\\n        string: { type: String, optional: true },\\n    };\\n\\n    get formattedValue() {\\n        const field = this.props.record.fields[this.props.name];\\n        const formatter = formatters.get(field.type);\\n        return formatter(this.props.record.data[this.props.name], {\\n            digits: this.props.digits,\\n            field,\\n        });\\n    }\\n    get label() {\\n        return this.props.labelField\\n            ? this.props.record.data[this.props.labelField]\\n            : this.props.string;\\n    }\\n}\\n\\nexport const statInfoField = {\\n    component: StatInfoField,\\n    displayName: _t(\\"Stat Info\\"),\\n    supportedOptions: [\\n        {\\n            label: _t(\\"Label field\\"),\\n            name: \\"label_field\\",\\n            type: \\"field\\",\\n            availableTypes: [\\"char\\"],\\n        },\\n    ],\\n    supportedTypes: [\\"float\\", \\"integer\\", \\"monetary\\", \\"char\\", \\"one2many\\", \\"many2one\\"],\\n    isEmpty: () => false,\\n    extractProps: ({ attrs, options, string }) => {\\n        // Sadly, digits param was available as an option and an attr.\\n        // The option version could be removed with some xml refactoring.\\n        let digits;\\n        if (attrs.digits) {\\n            digits = JSON.parse(attrs.digits);\\n        } else if (options.digits) {\\n            digits = options.digits;\\n        }\\n\\n        return {\\n            digits,\\n            labelField: options.label_field,\\n            noLabel: exprToBoolean(attrs.nolabel),\\n            string,\\n        };\\n    },\\n};\\n\\nregistry.category(\\"fields\\").add(\\"statinfo\\", statInfoField);\\n", "import { Component } from \\"@odoo/owl\\";\\nimport { useCommand } from \\"@web/core/commands/command_hook\\";\\nimport { Dropdown } from \\"@web/core/dropdown/dropdown\\";\\nimport { CheckboxItem } from \\"@web/core/dropdown/checkbox_item\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { formatSelection } from \\"../formatters\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\n\\nexport class StateSelectionField extends Component {\\n    static template = \\"web.StateSelectionField\\";\\n    static components = {\\n        Dropdown,\\n        CheckboxItem,\\n    };\\n    static props = {\\n        ...standardFieldProps,\\n        showLabel: { type: Boolean, optional: true },\\n        withCommand: { type: Boolean, optional: true },\\n        autosave: { type: Boolean, optional: true },\\n    };\\n    static defaultProps = {\\n        showLabel: true,\\n    };\\n\\n    setup() {\\n        this.colorPrefix = \\"o_status_\\";\\n        this.colors = {\\n            blocked: \\"red\\",\\n            done: \\"green\\",\\n        };\\n        if (this.props.withCommand) {\\n            const hotkeys = [\\"D\\", \\"F\\", \\"G\\"];\\n            for (const [index, [value, label]] of this.options.entries()) {\\n                useCommand(\\n                    _t(\\"Set kanban state as %s\\", label),\\n                    () => {\\n                        this.updateRecord(value);\\n                    },\\n                    {\\n                        category: \\"smart_action\\",\\n                        hotkey: hotkeys[index] && \\"alt+\\" + hotkeys[index],\\n                        isAvailable: () => this.props.record.data[this.props.name] !== value,\\n                    }\\n                );\\n            }\\n        }\\n    }\\n    get options() {\\n        return this.props.record.fields[this.props.name].selection.map(([state, label]) => {\\n            return [state, this.props.record.data[`legend_${state}`] || label];\\n        });\\n    }\\n    get currentValue() {\\n        return this.props.record.data[this.props.name] || this.options[0][0];\\n    }\\n    get label() {\\n        if (\\n            this.props.record.data[this.props.name] &&\\n            this.props.record.data[`legend_${this.props.record.data[this.props.name][0]}`]\\n        ) {\\n            return this.props.record.data[`legend_${this.props.record.data[this.props.name][0]}`];\\n        }\\n        return formatSelection(this.currentValue, { selection: this.options });\\n    }\\n\\n    statusColor(value) {\\n        return this.colors[value] ? this.colorPrefix + this.colors[value] : \\"\\";\\n    }\\n\\n    async updateRecord(value) {\\n        await this.props.record.update({ [this.props.name]: value }, { save: this.props.autosave });\\n    }\\n}\\n\\nexport const stateSelectionField = {\\n    component: StateSelectionField,\\n    displayName: _t(\\"Label Selection\\"),\\n    supportedOptions: [\\n        {\\n            label: _t(\\"Autosave\\"),\\n            name: \\"autosave\\",\\n            type: \\"boolean\\",\\n            default: true,\\n            help: _t(\\n                \\"If checked, the record will be saved immediately when the field is modified.\\"\\n            ),\\n        },\\n        {\\n            label: _t(\\"Hide label\\"),\\n            name: \\"hide_label\\",\\n            type: \\"boolean\\",\\n        },\\n    ],\\n    supportedTypes: [\\"selection\\"],\\n    extractProps({ options, viewType }, dynamicInfo) {\\n        return {\\n            showLabel: 'hide_label' in options ? !options.hide_label : false,\\n            withCommand: viewType === \\"form\\",\\n            readonly: dynamicInfo.readonly,\\n            autosave: \\"autosave\\" in options ? !!options.autosave : true,\\n        };\\n    },\\n};\\n\\nregistry.category(\\"fields\\").add(\\"state_selection\\", stateSelectionField);\\n", "import { Component, onWillRender, useEffect, useExternalListener, useRef } from \\"@odoo/owl\\";\\nimport { useCommand } from \\"@web/core/commands/command_hook\\";\\nimport { Domain } from \\"@web/core/domain\\";\\nimport { Dropdown } from \\"@web/core/dropdown/dropdown\\";\\nimport { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { groupBy } from \\"@web/core/utils/arrays\\";\\nimport { throttleForAnimation } from \\"@web/core/utils/timing\\";\\nimport { getFieldDomain } from \\"@web/model/relational_model/utils\\";\\nimport { useSpecialData } from \\"@web/views/fields/relational_utils\\";\\nimport { standardFieldProps } from \\"../standard_field_props\\";\\n\\n/**\\n * @typedef {import(\\"../standard_field_props\\").StandardFieldProps & {\\n *  domain?: [Array, Function];\\n *  foldField?: string;\\n *  isDisabled?: boolean;\\n *  visibleSelection?: string[];\\n *  withCommand?: boolean;\\n * }} StatusBarFieldProps\\n *\\n * @typedef StatusBarItem\\n * @property {number} value\\n * @property {string} label\\n * @property {boolean} isFolded\\n * @property {boolean} isSelected\\n *\\n * @typedef StatusBarList\\n * @property {string} label\\n * @property {StatusBarItem[]} items\\n */\\n\\n/**\\n * @param {...HTMLElement} els\\n */\\nconst hide = (...els) => els.forEach((el) => el.classList.add(\\"d-none\\"));\\n\\n/**\\n * @param {...HTMLElement} els\\n */\\nconst show = (...els) => els.forEach((el) => el.classList.remove(\\"d-none\\"));\\n\\n/** @extends {Component<StatusBarFieldProps>} */\\nexport class StatusBarField extends Component {\\n    static template = \\"web.StatusBarField\\";\\n    static components = {\\n        Dropdown,\\n        DropdownItem,\\n    };\\n    static props = {\\n        ...standardFieldProps,\\n        domain: { type: [Array, Function], optional: true },\\n        foldField: { type: String, optional: true },\\n        isDisabled: { type: Boolean, optional: true },\\n        visibleSelection: { type: Array, element: String, optional: true },\\n        withCommand: { type: Boolean, optional: true },\\n    };\\n\\n    setup() {\\n        // Properties\\n        this.items = {};\\n        this.beforeRef = useRef(\\"before\\");\\n        this.rootRef = useRef(\\"root\\");\\n        this.afterRef = useRef(\\"after\\");\\n        this.dropdownRef = useRef(\\"dropdown\\");\\n\\n        // Resize listeners\\n        let status = \\"idle\\";\\n        const adjust = () => {\\n            status = \\"adjusting\\";\\n            this.adjustVisibleItems();\\n            this.render();\\n        };\\n\\n        useEffect(\\n            () => status === \\"shouldAdjust\\" && adjust(),\\n            () => [status]\\n        );\\n\\n        let forceRecomputeItems = false;\\n        onWillRender(() => {\\n            if (status !== \\"adjusting\\" || forceRecomputeItems) {\\n                Object.assign(this.items, this.getSortedItems());\\n                status = \\"shouldAdjust\\";\\n            } else {\\n                status = \\"idle\\";\\n            }\\n            forceRecomputeItems = false;\\n        });\\n\\n        useExternalListener(window, \\"resize\\", throttleForAnimation(adjust));\\n\\n        // Special data\\n        if (this.field.type === \\"many2one\\") {\\n            this.specialData = useSpecialData(async (orm, props) => {\\n                const { foldField, name: fieldName, record } = props;\\n                const { relation } = record.fields[fieldName];\\n                const fieldNames = [\\"display_name\\"];\\n                if (foldField) {\\n                    fieldNames.push(foldField);\\n                }\\n                const value = record.data[fieldName];\\n                let domain = getFieldDomain(record, fieldName, props.domain);\\n                domain = Domain.and([this.getDomain(), domain]).toList();\\n                if (domain.length && value) {\\n                    domain = Domain.or([[[\\"id\\", \\"=\\", value.id]], domain]).toList(\\n                        record.evalContext\\n                    );\\n                }\\n                const res = orm.searchRead(relation, domain, fieldNames);\\n                forceRecomputeItems = true;\\n                return res;\\n            });\\n        }\\n\\n        // Command palette\\n        if (this.props.withCommand) {\\n            const moveToCommandName = _t(\\"Move to %s...\\", this.field.string);\\n            useCommand(\\n                moveToCommandName,\\n                () => ({\\n                    placeholder: moveToCommandName,\\n                    providers: [\\n                        {\\n                            provide: () =>\\n                                this.getAllItems().map((item) => ({\\n                                    name: item.label,\\n                                    action: () => this.selectItem(item),\\n                                })),\\n                        },\\n                    ],\\n                }),\\n                {\\n                    category: \\"smart_action\\",\\n                    hotkey: \\"alt+shift+x\\",\\n                    isAvailable: () => !this.props.isDisabled,\\n                }\\n            );\\n            useCommand(\\n                _t(\\"Move to next %s\\", this.field.string),\\n                () => {\\n                    const items = this.getAllItems();\\n                    const nextIndex = items.findIndex((item) => item.isSelected) + 1;\\n                    this.selectItem(items[nextIndex]);\\n                },\\n                {\\n                    category: \\"smart_action\\",\\n                    hotkey: \\"alt+x\\",\\n                    isAvailable: () => {\\n                        if (this.props.isDisabled) {\\n                            return false;\\n                        }\\n                        const items = this.getAllItems();\\n                        return items.length && !items.at(-1).isSelected;\\n                    },\\n                }\\n            );\\n        }\\n    }\\n\\n    /**\\n     * @returns {{ selection?: [string, string][], string: string, type: \\"many2one\\" | \\"selection\\" }}\\n     */\\n    get field() {\\n        return this.props.record.fields[this.props.name];\\n    }\\n\\n    /**\\n     * Override this to force a dynamic domain on the records\\n     */\\n    getDomain() {\\n        return [];\\n    }\\n\\n    /**\\n     * Determines what items must be visible and how they must be displayed.\\n     * There are 4 main scenarios:\\n     *\\n     * 1. All items can be displayed inline, no modification in the UI;\\n     *\\n     * The following scenarios imply that the viewport is too small to display\\n     * all items in one line. Adjustments are made incrementally:\\n     *\\n     * 2. Items up to 1 before the currently selected item are combined in a dropdown;\\n     *\\n     * 3. Items up to 1 after the currently selected item are combined in a dropdown,\\n     * along with the initially folded items;\\n     *\\n     * 4. If that still doesn't suffice: all items are combined in a single dropdown.\\n     */\\n    adjustVisibleItems() {\\n        // Get all visible buttons\\n        const itemEls = [\\n            ...this.rootRef.el.querySelectorAll(\\".o_arrow_button:not(.dropdown-toggle)\\"),\\n        ];\\n        const selectedIndex = itemEls.findIndex((el) =>\\n            el.classList.contains(\\"o_arrow_button_current\\")\\n        );\\n        const itemsBefore = itemEls.slice(selectedIndex + 2).reverse();\\n        const itemsAfter = itemEls.slice(0, Math.max(selectedIndex - 1, 0)).reverse();\\n\\n        // Reset hidden elements\\n        show(...itemEls);\\n        hide(this.dropdownRef.el, this.beforeRef.el);\\n        if (this.items.folded.length) {\\n            show(this.afterRef.el);\\n            itemEls.forEach((el) => el.classList.remove(\\"o_first\\"));\\n        } else {\\n            hide(this.afterRef.el);\\n            itemEls[0]?.classList.add(\\"o_first\\");\\n        }\\n\\n        // Reset items variables\\n        this.items.before = [];\\n        this.items.after = [...this.items.folded];\\n        const itemsToAssign = this.getAllItems().filter((item) => !item.isFolded);\\n\\n        if (this.env.isSmall && this.items.inline.length) {\\n            // Small screen case: only a single dropdown\\n            show(this.dropdownRef.el);\\n            hide(this.beforeRef.el, this.afterRef.el, ...itemEls);\\n            return;\\n        }\\n\\n        while (this.areItemsWrapping()) {\\n            if (itemsBefore.length) {\\n                // Case 1: elements before can be hidden\\n                show(this.beforeRef.el);\\n                hide(itemsBefore.shift());\\n                this.items.before.push(itemsToAssign.shift());\\n            } else if (itemsAfter.length) {\\n                // Case 2: elements before are hidden, elements after can be hidden\\n                show(this.afterRef.el);\\n                hide(itemsAfter.pop());\\n                this.items.after.unshift(itemsToAssign.pop());\\n            } else {\\n                // Last resort: no elements can be hidden => fallback to single dropdown\\n                show(this.dropdownRef.el);\\n                hide(this.beforeRef.el, this.afterRef.el, ...itemEls);\\n                break;\\n            }\\n        }\\n    }\\n\\n    areItemsWrapping() {\\n        const root = this.rootRef.el;\\n        const firstItem = root.querySelector(\\":scope > :not(.d-none)\\");\\n        if (!firstItem) {\\n            return false;\\n        }\\n        const { height: currentHeight } = root.getBoundingClientRect();\\n        const { height: targetHeight } = firstItem.getBoundingClientRect();\\n        return currentHeight > targetHeight;\\n    }\\n\\n    /**\\n     * @returns {StatusBarItem[]}\\n     */\\n    getAllItems() {\\n        const { foldField, name, record } = this.props;\\n        const currentValue = record.data[name];\\n        if (this.field.type === \\"man