e === \\"button\\") {\\n                        controls.push({\\n                            type: \\"button\\",\\n                            ...processButton(childNode),\\n                        });\\n                    } else if (childNode.tagName === \\"create\\") {\\n                        controls.push({\\n                            type: \\"create\\",\\n                            context: childNode.getAttribute(\\"context\\"),\\n                            string: childNode.getAttribute(\\"string\\"),\\n                            invisible: childNode.getAttribute(\\"invisible\\"),\\n                            class: childNode.getAttribute(\\"class\\"),\\n                        });\\n                    } else if (childNode.tagName === \\"delete\\") {\\n                        controls.push({\\n                            type: \\"delete\\",\\n                            invisible: childNode.getAttribute(\\"invisible\\"),\\n                        });\\n                    }\\n                }\\n                return false;\\n            }\\n            // Case: field node\\n            if (node.tagName === \\"field\\") {\\n                // In kanban, we display many2many fields as tags by default\\n                const widget = node.getAttribute(\\"widget\\");\\n                if (\\n                    !widget &&\\n                    models[modelName].fields[node.getAttribute(\\"name\\")].type === \\"many2many\\"\\n                ) {\\n                    node.setAttribute(\\"widget\\", \\"many2many_tags\\");\\n                }\\n                const fieldInfo = Field.parseFieldNode(node, models, modelName, \\"kanban\\", jsClass);\\n                const name = fieldInfo.name;\\n                if (!(fieldInfo.name in fieldNextIds)) {\\n                    fieldNextIds[fieldInfo.name] = 0;\\n                }\\n                const fieldId = `${fieldInfo.name}_${fieldNextIds[fieldInfo.name]++}`;\\n                fieldNodes[fieldId] = fieldInfo;\\n                node.setAttribute(\\"field_id\\", fieldId);\\n                if (fieldInfo.options.group_by_tooltip) {\\n                    tooltipInfo[name] = fieldInfo.options.group_by_tooltip;\\n                }\\n                if (fieldInfo.isHandle) {\\n                    handleField = name;\\n                }\\n            }\\n            if (node.tagName === \\"widget\\") {\\n                const widgetInfo = Widget.parseWidgetNode(node);\\n                const widgetId = `widget_${++widgetNextId}`;\\n                widgetNodes[widgetId] = widgetInfo;\\n                node.setAttribute(\\"widget_id\\", widgetId);\\n            }\\n\\n            // Keep track of last update so images can be reloaded when they may have changed.\\n            if (node.tagName === \\"img\\") {\\n                const attSrc = node.getAttribute(\\"t-att-src\\");\\n                if (\\n                    attSrc &&\\n                    /\\\\bkanban_image\\\\b/.test(attSrc) &&\\n                    !Object.values(fieldNodes).some((f) => f.name === \\"write_date\\")\\n                ) {\\n                    fieldNodes.write_date_0 = { name: \\"write_date\\", type: \\"datetime\\" };\\n                }\\n            }\\n        });\\n\\n        // Progressbar\\n        let progressAttributes = false;\\n        const progressBar = xmlDoc.querySelector(\\"progressbar\\");\\n        if (progressBar) {\\n            progressAttributes = this.parseProgressBar(progressBar, fields);\\n        }\\n\\n        // Concrete kanban box elements in the template\\n        const cardDoc = templateDocs[KANBAN_CARD_ATTRIBUTE];\\n        if (!cardDoc) {\\n            throw new Error(`Missing '${KANBAN_CARD_ATTRIBUTE}' template.`);\\n        }\\n        const cardClassName = cardDoc.getAttribute(\\"class\\") || \\"\\";\\n\\n        if (!defaultOrder.length && handleField) {\\n            const handleFieldSort = `${handleField}, id`;\\n            defaultOrder = stringToOrderBy(handleFieldSort);\\n        }\\n\\n        return {\\n            activeActions,\\n            canOpenRecords,\\n            cardClassName,\\n            cardColorField: xmlDoc.getAttribute(\\"highlight_color\\"),\\n            className,\\n            controls,\\n            defaultGroupBy,\\n            fieldNodes,\\n            widgetNodes,\\n            handleField,\\n            headerButtons,\\n            defaultOrder,\\n            onCreate,\\n            openAction,\\n            quickCreateView,\\n            recordsDraggable,\\n            groupsDraggable,\\n            limit: limit && parseInt(limit, 10),\\n            countLimit: countLimit && parseInt(countLimit, 10),\\n            progressAttributes,\\n            templateDocs,\\n            tooltipInfo,\\n            examples: xmlDoc.getAttribute(\\"examples\\"),\\n            xmlDoc,\\n        };\\n    }\\n\\n    parseProgressBar(progressBar, fields) {\\n        const attrs = extractAttributes(progressBar, [\\"field\\", \\"colors\\", \\"sum_field\\", \\"help\\"]);\\n        return {\\n            fieldName: attrs.field,\\n            colors: JSON.parse(attrs.colors),\\n            sumField: fields[attrs.sum_field] || false,\\n            help: attrs.help,\\n        };\\n    }\\n\\n    processButton(node) {\\n        return processButton(node);\\n    }\\n}\\n", "import { CogMenu } from \\"../../search/cog_menu/cog_menu\\";\\n\\nexport class KanbanCogMenu extends CogMenu {\\n    static template = \\"web.KanbanCogMenu\\";\\n    static props = {\\n        ...CogMenu.props,\\n        hasSelectedRecords: { type: Number, optional: true },\\n    };\\n    _registryItems() {\\n        return this.props.hasSelectedRecords ? [] : super._registryItems();\\n    }\\n}\\n", "import { Dialog } from \\"@web/core/dialog/dialog\\";\\nimport { Notebook } from \\"@web/core/notebook/notebook\\";\\n\\nimport { Component, useRef } from \\"@odoo/owl\\";\\n\\nconst random = (min, max) => Math.floor(Math.random() * (max - min) + min);\\n\\nclass KanbanExamplesNotebookTemplate extends Component {\\n    static template = \\"web.KanbanExamplesNotebookTemplate\\";\\n    static props = [\\"*\\"];\\n    static defaultProps = {\\n        columns: [],\\n        foldedColumns: [],\\n    };\\n    setup() {\\n        this.columns = [];\\n        const hasBullet = this.props.bullets && this.props.bullets.length;\\n        const allColumns = [...this.props.columns, ...this.props.foldedColumns];\\n        for (const title of allColumns) {\\n            const col = { title, records: [] };\\n            this.columns.push(col);\\n            for (let i = 0; i < random(1, 5); i++) {\\n                const rec = { id: i };\\n                if (hasBullet && Math.random() > 0.3) {\\n                    const sampleId = Math.floor(Math.random() * this.props.bullets.length);\\n                    rec.bullet = this.props.bullets[sampleId];\\n                }\\n                col.records.push(rec);\\n            }\\n        }\\n    }\\n}\\n\\nexport class KanbanColumnExamplesDialog extends Component {\\n    static template = \\"web.KanbanColumnExamplesDialog\\";\\n    static components = { Dialog, Notebook };\\n    static props = [\\"*\\"];\\n\\n    setup() {\\n        this.navList = useRef(\\"navList\\");\\n        this.pages = [];\\n        this.activePage = null;\\n        this.props.examples.forEach((eg) => {\\n            this.pages.push({\\n                Component: KanbanExamplesNotebookTemplate,\\n                title: eg.name,\\n                props: eg,\\n                id: eg.name,\\n            });\\n        });\\n    }\\n\\n    onPageUpdate(page) {\\n        this.activePage = page;\\n    }\\n\\n    applyExamples() {\\n        const index = this.props.examples.findIndex((e) => e.name === this.activePage);\\n        this.props.applyExamples(index);\\n        this.props.close();\\n    }\\n}\\n", "import { useHotkey } from \\"@web/core/hotkeys/hotkey_hook\\";\\nimport { useAutofocus, useService } from \\"@web/core/utils/hooks\\";\\n\\nimport { Component, useExternalListener, useState, useRef, onPatched } from \\"@odoo/owl\\";\\n\\nexport class KanbanColumnQuickCreate extends Component {\\n    static template = \\"web.KanbanColumnQuickCreate\\";\\n    static props = {\\n        onFoldChange: Function,\\n        onValidate: Function,\\n        folded: Boolean,\\n        groupByField: Object,\\n    };\\n\\n    setup() {\\n        this.dialog = useService(\\"dialog\\");\\n        this.root = useRef(\\"root\\");\\n        this.state = useState({\\n            hasInputFocused: false,\\n        });\\n\\n        useAutofocus();\\n        this.inputRef = useRef(\\"autofocus\\");\\n\\n        // Close on outside click\\n        useExternalListener(window, \\"mousedown\\", (/** @type {MouseEvent} */ ev) => {\\n            // This target is kept in order to impeach close on outside click behavior if the click\\n            // has been initiated from the quickcreate root element (mouse selection in an input...)\\n            this.mousedownTarget = ev.target;\\n        });\\n        useExternalListener(\\n            window,\\n            \\"click\\",\\n            (/** @type {MouseEvent} */ ev) => {\\n                const target = this.mousedownTarget || ev.target;\\n                const gotClickedInside = this.root.el.contains(target);\\n                if (!gotClickedInside) {\\n                    this.fold();\\n                }\\n                this.mousedownTarget = null;\\n            },\\n            { capture: true }\\n        );\\n\\n        // Key Navigation\\n        useHotkey(\\"escape\\", () => this.fold());\\n        onPatched(() => {\\n            if (this.state.hasInputFocused && !this.props.folded) {\\n                this.root.el.scrollIntoView({ behavior: \\"smooth\\" });\\n            }\\n        });\\n    }\\n\\n    get relatedFieldName() {\\n        return this.props.groupByField.string;\\n    }\\n\\n    fold() {\\n        this.props.onFoldChange(true);\\n    }\\n\\n    unfold() {\\n        this.props.onFoldChange(false);\\n    }\\n\\n    validate() {\\n        const title = this.inputRef.el.value.trim();\\n        if (title.length) {\\n            this.props.onValidate(title);\\n            this.inputRef.el.value = \\"\\";\\n            this.inputRef.el.focus();\\n            this.state.hasInputFocused = true;\\n        }\\n    }\\n\\n    onInputKeydown(ev) {\\n        if (ev.key === \\"Enter\\") {\\n            this.validate();\\n        }\\n    }\\n}\\n", "import {\\n    append,\\n    combineAttributes,\\n    createElement,\\n    extractAttributes,\\n    getTag,\\n} from \\"@web/core/utils/xml\\";\\nimport { toStringExpression } from \\"@web/views/utils\\";\\nimport { toInterpolatedStringExpression, ViewCompiler } from \\"@web/views/view_compiler\\";\\n\\n/**\\n * @typedef {Object} DropdownDef\\n * @property {Element} el\\n * @property {boolean} inserted\\n * @property {boolean} shouldInsert\\n * @property {(\\"dropdown\\" | \\"toggler\\" | \\"menu\\")[]} parts\\n */\\n\\nconst ACTION_TYPES = [\\"action\\", \\"object\\"];\\nconst SPECIAL_TYPES = [\\n    ...ACTION_TYPES,\\n    \\"open\\",\\n    \\"delete\\",\\n    \\"url\\",\\n    \\"set_cover\\",\\n    \\"archive\\",\\n    \\"unarchive\\",\\n];\\n\\nexport class KanbanCompiler extends ViewCompiler {\\n    setup() {\\n        this.compilers.push(\\n            { selector: \\"t[t-call]\\", fn: this.compileTCall },\\n            { selector: \\"img\\", fn: this.compileImage }\\n        );\\n    }\\n\\n    //-----------------------------------------------------------------------------\\n    // Compilers\\n    //-----------------------------------------------------------------------------\\n\\n    /**\\n     * @override\\n     */\\n    compileButton(el, params) {\\n        const type = el.getAttribute(\\"type\\");\\n        if (!SPECIAL_TYPES.includes(type)) {\\n            // Not a kanban-specific action type.\\n            return super.compileButton(el, params);\\n        }\\n\\n        combineAttributes(el, \\"class\\", [\\"oe_kanban_action\\"]);\\n\\n        if (ACTION_TYPES.includes(type)) {\\n            if (!el.hasAttribute(\\"debounce\\")) {\\n                // action buttons are debounced in kanban records\\n                el.setAttribute(\\"debounce\\", 300);\\n            }\\n            return super.compileButton(el, params);\\n        }\\n\\n        const nodeParams = extractAttributes(el, [\\"type\\"]);\\n        if (type === \\"set_cover\\") {\\n            const { \\"auto-open\\": autoOpen, \\"data-field\\": fieldName } = extractAttributes(el, [\\n                \\"auto-open\\",\\n                \\"data-field\\",\\n            ]);\\n            Object.assign(nodeParams, { autoOpen, fieldName });\\n        }\\n        const strParams = Object.entries(nodeParams)\\n            .map(([k, v]) => [k, toStringExpression(v)].join(\\":\\"))\\n            .join(\\",\\");\\n        el.setAttribute(\\"t-on-click\\", `()=>__comp__.triggerAction({${strParams}})`);\\n\\n        const compiled = createElement(el.nodeName);\\n        for (const { name, value } of el.attributes) {\\n            compiled.setAttribute(name, value);\\n        }\\n        if (getTag(el, true) === \\"a\\" && !compiled.hasAttribute(\\"href\\")) {\\n            compiled.setAttribute(\\"href\\", \\"#\\");\\n        }\\n        for (const child of el.childNodes) {\\n            append(compiled, this.compileNode(child, params));\\n        }\\n\\n        return compiled;\\n    }\\n    /**\\n     * @returns {Element}\\n     */\\n    compileImage(el) {\\n        const element = el.cloneNode(true);\\n        element.setAttribute(\\"loading\\", \\"lazy\\");\\n        return element;\\n    }\\n\\n    /**\\n     * @override\\n     */\\n    compileField(el, params) {\\n        let compiled;\\n        const recordExpr = params.recordExpr || \\"__comp__.props.record\\";\\n        const dataPointIdExpr = params.dataPointIdExpr || `${recordExpr}.id`;\\n        if (!el.hasAttribute(\\"widget\\")) {\\n            // fields without a specified widget are rendered as simple spans in kanban records\\n            const fieldId = el.getAttribute(\\"field_id\\");\\n            compiled = createElement(\\"span\\", {\\n                \\"t-out\\": params.formattedValueExpr || `__comp__.getFormattedValue(\\"${fieldId}\\")`,\\n            });\\n        } else {\\n            compiled = super.compileField(el, params);\\n            const fieldId = el.getAttribute(\\"field_id\\");\\n            compiled.setAttribute(\\"id\\", `'${fieldId}_' + ${dataPointIdExpr}`);\\n            // In x2many kanban, records can be edited in a dialog. The same record as the one of\\n            // the kanban is used for the form view dialog, so its mode is switched to \\"edit\\", but\\n            // we don't want to see it in edition in the background. For that reason, we force its\\n            // fields to be readonly when the record is in edition, i.e. when it is opened in a form\\n            // view dialog.\\n            const readonlyAttr = compiled.getAttribute(\\"readonly\\");\\n            if (readonlyAttr) {\\n                compiled.setAttribute(\\"readonly\\", `${recordExpr}.isInEdition || (${readonlyAttr})`);\\n            } else {\\n                compiled.setAttribute(\\"readonly\\", `${recordExpr}.isInEdition`);\\n            }\\n        }\\n\\n        const attrs = {};\\n        for (const attr of el.attributes) {\\n            attrs[attr.name] = attr.value;\\n        }\\n\\n        if (el.hasAttribute(\\"widget\\")) {\\n            const attrsParts = Object.entries(attrs).map(([key, value]) => {\\n                if (key.startsWith(\\"t-attf-\\")) {\\n                    key = key.slice(7);\\n                    value = toInterpolatedStringExpression(value);\\n                } else if (key.startsWith(\\"t-att-\\")) {\\n                    key = key.slice(6);\\n                    value = `\\"\\" + (${value})`;\\n                } else if (key.startsWith(\\"t-att\\")) {\\n                    throw new Error(\\"t-att on <field> nodes is not supported\\");\\n                } else if (!key.startsWith(\\"t-\\")) {\\n                    value = toStringExpression(value);\\n                }\\n                return `'${key}':${value}`;\\n            });\\n            compiled.setAttribute(\\"attrs\\", `{${attrsParts.join(\\",\\")}}`);\\n        }\\n\\n        for (const attr in attrs) {\\n            if (attr.startsWith(\\"t-\\") && !attr.startsWith(\\"t-att\\")) {\\n                compiled.setAttribute(attr, attrs[attr]);\\n            }\\n        }\\n\\n        return compiled;\\n    }\\n\\n    /**\\n     * @param {Element} el\\n     * @param {Object} params\\n     * @returns {Element}\\n     */\\n    compileTCall(el, params) {\\n        const compiled = this.compileGenericNode(el, params);\\n        const tname = el.getAttribute(\\"t-call\\");\\n        if (tname in this.templates) {\\n            compiled.setAttribute(\\"t-call\\", `{{__comp__.templates[${toStringExpression(tname)}]}}`);\\n        }\\n        return compiled;\\n    }\\n}\\nKanbanCompiler.OWL_DIRECTIVE_WHITELIST = [\\n    ...ViewCompiler.OWL_DIRECTIVE_WHITELIST,\\n    \\"t-name\\",\\n    \\"t-esc\\",\\n    \\"t-out\\",\\n    \\"t-set\\",\\n    \\"t-value\\",\\n    \\"t-if\\",\\n    \\"t-else\\",\\n    \\"t-elif\\",\\n    \\"t-foreach\\",\\n    \\"t-as\\",\\n    \\"t-key\\",\\n    \\"t-att.*\\",\\n    \\"t-call\\",\\n];\\n", "import { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { user } from \\"@web/core/user\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { omit } from \\"@web/core/utils/objects\\";\\nimport { evaluateBooleanExpr } from \\"@web/core/py_js/py\\";\\nimport { useSetupAction } from \\"@web/search/action_hook\\";\\nimport { ActionMenus, STATIC_ACTIONS_GROUP_NUMBER } from \\"@web/search/action_menus/action_menus\\";\\nimport { Layout } from \\"@web/search/layout\\";\\nimport { usePager } from \\"@web/search/pager_hook\\";\\nimport { SearchBar } from \\"@web/search/search_bar/search_bar\\";\\nimport { useSearchBarToggler } from \\"@web/search/search_bar/search_bar_toggler\\";\\nimport { session } from \\"@web/session\\";\\nimport { useModelWithSampleData } from \\"@web/model/model\\";\\nimport { standardViewProps } from \\"@web/views/standard_view_props\\";\\nimport { MultiRecordViewButton } from \\"@web/views/view_button/multi_record_view_button\\";\\nimport { useViewButtons } from \\"@web/views/view_button/view_button_hook\\";\\nimport { useExportRecords, useDeleteRecords } from \\"@web/views/view_hook\\";\\nimport { addFieldDependencies, extractFieldsFromArchInfo } from \\"@web/model/relational_model/utils\\";\\nimport { KanbanCogMenu } from \\"./kanban_cog_menu\\";\\nimport { KanbanRenderer } from \\"./kanban_renderer\\";\\nimport { useProgressBar } from \\"./progress_bar_hook\\";\\nimport { SelectionBox } from \\"@web/views/view_components/selection_box\\";\\n\\nimport {\\n    Component,\\n    onMounted,\\n    onWillStart,\\n    reactive,\\n    useEffect,\\n    useRef,\\n    useState,\\n    useSubEnv,\\n} from \\"@odoo/owl\\";\\n\\nconst QUICK_CREATE_FIELD_TYPES = [\\"char\\", \\"boolean\\", \\"many2one\\", \\"selection\\", \\"many2many\\"];\\n\\n// -----------------------------------------------------------------------------\\n\\nexport class KanbanController extends Component {\\n    static template = `web.KanbanView`;\\n    static components = {\\n        ActionMenus,\\n        DropdownItem,\\n        Layout,\\n        KanbanRenderer,\\n        MultiRecordViewButton,\\n        SearchBar,\\n        CogMenu: KanbanCogMenu,\\n        SelectionBox,\\n    };\\n    static props = {\\n        ...standardViewProps,\\n        editable: { type: Boolean, optional: true },\\n        forceGlobalClick: { type: Boolean, optional: true },\\n        onSelectionChanged: { type: Function, optional: true },\\n        readonly: { type: Boolean, optional: true },\\n        showButtons: { type: Boolean, optional: true },\\n        Compiler: Function,\\n        Model: Function,\\n        Renderer: Function,\\n        buttonTemplate: String,\\n        archInfo: Object,\\n    };\\n\\n    static defaultProps = {\\n        createRecord: () => {},\\n        forceGlobalClick: false,\\n        selectRecord: () => {},\\n        showButtons: true,\\n    };\\n\\n    setup() {\\n        this.actionService = useService(\\"action\\");\\n        this.dialog = useService(\\"dialog\\");\\n        const { Model, archInfo } = this.props;\\n\\n        class KanbanSampleModel extends Model {\\n            setup() {\\n                super.setup(...arguments);\\n                this.initialSampleGroups = undefined;\\n            }\\n\\n            /**\\n             * @override\\n             */\\n            hasData() {\\n                if (this.root.groups) {\\n                    if (!this.root.groups.length) {\\n                        // While we don't have any data, we want to display the column quick create and\\n                        // example background. Return true so that we don't get sample data instead\\n                        return true;\\n                    }\\n                    return this.root.groups.some((group) => group.hasData);\\n                }\\n                return super.hasData();\\n            }\\n\\n            async load() {\\n                if (this.orm.isSample && this.initialSampleGroups) {\\n                    this.orm.setGroups(this.initialSampleGroups);\\n                }\\n                return super.load(...arguments);\\n            }\\n\\n            async _webReadGroup() {\\n                const result = await super._webReadGroup(...arguments);\\n                if (!this.initialSampleGroups) {\\n                    this.initialSampleGroups = JSON.parse(JSON.stringify(result.groups));\\n                }\\n                return result;\\n            }\\n\\n            removeSampleDataInGroups() {\\n                if (this.useSampleModel) {\\n                    for (const group of this.root.groups) {\\n                        const list = group.list;\\n                        group.count = 0;\\n                        list.count = 0;\\n                        if (list.records) {\\n                            list.records = [];\\n                        } else {\\n                            list.groups = [];\\n                        }\\n                    }\\n                }\\n            }\\n        }\\n\\n        this.model = useState(\\n            useModelWithSampleData(KanbanSampleModel, this.modelParams, this.modelOptions)\\n        );\\n        if (archInfo.progressAttributes) {\\n            const { activeBars } = this.props.state || {};\\n            this.progressBarState = useProgressBar(\\n                archInfo.progressAttributes,\\n                this.model,\\n                this.progressBarAggregateFields,\\n                activeBars\\n            );\\n        }\\n        this.headerButtons = archInfo.headerButtons;\\n\\n        const self = this;\\n        this.quickCreateState = reactive({\\n            get groupId() {\\n                return this._groupId || false;\\n            },\\n            set groupId(groupId) {\\n                if (self.model.useSampleModel) {\\n                    self.model.removeSampleDataInGroups();\\n                    self.model.useSampleModel = false;\\n                }\\n                this._groupId = groupId;\\n            },\\n            view: archInfo.quickCreateView,\\n        });\\n\\n        this.rootRef = useRef(\\"root\\");\\n        useViewButtons(this.rootRef, {\\n            beforeExecuteAction: this.beforeExecuteActionButton.bind(this),\\n            afterExecuteAction: this.afterExecuteActionButton.bind(this),\\n            reload: () => this.model.load(),\\n        });\\n        const { setScrollFromState } = useSetupAction({\\n            rootRef: this.rootRef,\\n            beforeUnload: this.beforeUnload.bind(this),\\n            beforeLeave: this.beforeLeave.bind(this),\\n            getLocalState: () => {\\n                const state = {\\n                    activeBars: this.progressBarState?.activeBars,\\n                    modelState: this.model.exportState(),\\n                };\\n                if (this.env.isSmall && this.model.root.isGrouped) {\\n                    const columnScrollTops = [];\\n                    const sel = \\".o_kanban_group:not(.o_column_folded)\\";\\n                    const columnEls = this.rootRef.el.querySelectorAll(sel);\\n                    const groups = this.model.root.groups;\\n                    for (const columnEl of columnEls) {\\n                        const scrollTop = columnEl.scrollTop;\\n                        if (scrollTop > 0) {\\n                            const group = groups.find((g) => g.id === columnEl.dataset.id);\\n                            columnScrollTops.push([group.serverValue, columnEl.scrollTop]);\\n                        }\\n                    }\\n                    state.scrollPositions = {\\n                        scrollLeft: this.rootRef.el.querySelector(\\".o_renderer\\")?.scrollLeft || 0,\\n                        columnScrollTops,\\n                    };\\n                }\\n                return state;\\n            },\\n        });\\n        useEffect(\\n            (isReady) => {\\n                if (isReady) {\\n                    if (this.env.isSmall && this.model.root.isGrouped) {\\n                        const { scrollPositions } = this.props.state || {};\\n                        if (scrollPositions) {\\n                            const { scrollLeft, columnScrollTops } = scrollPositions;\\n                            this.rootRef.el.querySelector(\\".o_renderer\\").scrollLeft = scrollLeft;\\n                            const groups = this.model.root.groups;\\n                            for (const [serverValue, scrollTop] of columnScrollTops) {\\n                                const group = groups.find((g) => g.serverValue === serverValue);\\n                                if (group) {\\n                                    const sel = `.o_kanban_group[data-id=${group.id}]`;\\n                                    this.rootRef.el.querySelector(sel).scrollTop = scrollTop;\\n                                }\\n                            }\\n                        }\\n                    } else {\\n                        setScrollFromState();\\n                    }\\n                }\\n            },\\n            () => [this.model.isReady]\\n        );\\n        usePager(() => {\\n            const root = this.model.root;\\n            const { count, hasLimitedCount, isGrouped, limit, offset } = root;\\n            if (!isGrouped && !this.model.useSampleModel) {\\n                return {\\n                    offset: offset,\\n                    limit: limit,\\n                    total: count,\\n                    onUpdate: async ({ offset, limit }, hasNavigated) => {\\n                        await this.model.root.load({ offset, limit });\\n                        await this.onUpdatedPager();\\n                        if (hasNavigated) {\\n                            this.onPageChangeScroll();\\n                        }\\n                    },\\n                    updateTotal: hasLimitedCount ? () => root.fetchCount() : undefined,\\n                };\\n            }\\n        });\\n        this.searchBarToggler = useSearchBarToggler();\\n        this.firstLoad = true;\\n        onMounted(() => {\\n            this.firstLoad = false;\\n        });\\n        useEffect(\\n            () => {\\n                this.onSelectionChanged();\\n            },\\n            () => [this.model.root.selection?.length, this.model.root.isDomainSelected]\\n        );\\n        onWillStart(async () => {\\n            th