.fields\\n        );\\n\\n        const modelServices = Object.fromEntries(\\n            this.props.Model.services.map((servName) => [servName, useService(servName)])\\n        );\\n        modelServices.orm = useService(\\"orm\\");\\n        const config = {\\n            resModel: this.props.resModel,\\n            resId: false,\\n            resIds: [],\\n            fields,\\n            activeFields,\\n            isMonoRecord: true,\\n            mode: \\"edit\\",\\n            context: this.props.context,\\n        };\\n        this.model = useState(new this.props.Model(this.env, { config }, modelServices));\\n\\n        onWillStart(async () => {\\n            await this.model.load();\\n            this.model.whenReady.resolve();\\n        });\\n\\n        onMounted(() => {\\n            this.uiActiveElement = this.uiService.activeElement;\\n        });\\n        // Close on outside click\\n        useExternalListener(window, \\"mousedown\\", (/** @type {MouseEvent} */ ev) => {\\n            // This target is kept in order to impeach close on outside click behavior if the click\\n            // has been initiated from the quickcreate root element (mouse selection in an input...)\\n            this.mousedownTarget = ev.target;\\n        });\\n        useExternalListener(\\n            window,\\n            \\"click\\",\\n            (/** @type {MouseEvent} */ ev) => {\\n                if (this.uiActiveElement !== this.uiService.activeElement) {\\n                    // this component isn't in the current active element -> do nothing\\n                    return;\\n                }\\n                const target = this.mousedownTarget || ev.target;\\n                // accounts for clicking on datetime picker and legacy autocomplete\\n                const gotClickedInside =\\n                    target.closest(\\".o_datetime_picker\\") ||\\n                    target.closest(\\".ui-autocomplete\\") ||\\n                    this.rootRef.el.contains(target);\\n                if (!gotClickedInside) {\\n                    let force = false;\\n                    for (const selector of ACTION_SELECTORS) {\\n                        const closestEl = target.closest(selector);\\n                        if (closestEl) {\\n                            force = true;\\n                            break;\\n                        }\\n                    }\\n                    this.cancel(force);\\n                }\\n                this.mousedownTarget = null;\\n            },\\n            { capture: true }\\n        );\\n\\n        // Key Navigation\\n        useHotkey(\\"enter\\", () => this.validate(\\"add\\"), { bypassEditableProtection: true });\\n        useHotkey(\\"escape\\", () => this.cancel(true));\\n    }\\n\\n    async validate(mode) {\\n        let resId = undefined;\\n        if (this.state.disabled) {\\n            return;\\n        }\\n        this.state.disabled = true;\\n\\n        const keys = Object.keys(this.model.root.activeFields);\\n        if (keys.length === 1 && keys[0] === \\"display_name\\") {\\n            const isValid = await this.model.root.checkValidity(); // needed to put the class o_field_invalid in the field\\n            if (isValid) {\\n                try {\\n                    [resId] = await this.model.orm.call(\\n                        this.props.resModel,\\n                        \\"name_create\\",\\n                        [this.model.root.data.display_name],\\n                        {\\n                            context: this.props.context,\\n                        }\\n                    );\\n                } catch (e) {\\n                    this.showFormDialogInError(e);\\n                }\\n            } else {\\n                this.model.notification.add(_t(\\"Invalid Display Name\\"), {\\n                    type: \\"danger\\",\\n                });\\n            }\\n        } else {\\n            await this.model.root.save({\\n                reload: false,\\n                onError: (e) => this.showFormDialogInError(e),\\n            });\\n            resId = this.model.root.resId;\\n        }\\n\\n        if (resId) {\\n            this.props.onValidate(resId, mode);\\n            if (mode === \\"add\\") {\\n                await this.model.load({ resId: false });\\n                this.state.disabled = false;\\n            }\\n        } else {\\n            this.state.disabled = false;\\n        }\\n    }\\n\\n    async cancel(force) {\\n        if (this.state.disabled) {\\n            return;\\n        }\\n        if (force || !(await this.model.root.isDirty())) {\\n            this.props.onCancel();\\n        }\\n    }\\n\\n    showFormDialogInError(e) {\\n        // TODO: filter RPC errors more specifically (eg, for access denied, there is no point in opening a dialog)\\n        if (!(e instanceof RPCError)) {\\n            throw e;\\n        }\\n\\n        const context = this.props.context;\\n        const values = this.model.root.data;\\n        context.default_name = values.name || values.display_name;\\n        this.addDialog(FormViewDialog, {\\n            resModel: this.props.resModel,\\n            context,\\n            title: _t(\\"Create\\"),\\n            onRecordSaved: async (record) => {\\n                await this.props.onValidate(record.resId, \\"add\\");\\n                await this.model.load();\\n            },\\n        });\\n    }\\n\\n    get className() {\\n        return \\"o_kanban_quick_create o_field_highlight shadow\\";\\n    }\\n}\\n\\nexport class KanbanRecordQuickCreate extends Component {\\n    static components = { KanbanQuickCreateController };\\n    static template = \\"web.KanbanRecordQuickCreate\\";\\n    static props = {\\n        quickCreateView: { type: [String, { value: null }], optional: 1 },\\n        onValidate: Function,\\n        onCancel: Function,\\n        group: Object,\\n    };\\n\\n    setup() {\\n        this.state = useState({\\n            isLoaded: false,\\n        });\\n        this.viewService = useService(\\"view\\");\\n        onMounted(() => {\\n            this.getQuickCreateProps(this.props).then(() => {\\n                this.state.isLoaded = true;\\n            });\\n        });\\n        useSubEnv({\\n            config: getDefaultConfig(),\\n        });\\n    }\\n\\n    async getQuickCreateProps(props) {\\n        let quickCreateFields = { fields: DEFAULT_QUICK_CREATE_FIELDS };\\n        let quickCreateForm = DEFAULT_QUICK_CREATE_VIEW;\\n        let quickCreateRelatedModels = {};\\n\\n        if (props.quickCreateView) {\\n            const { fields, relatedModels, views } = await this.viewService.loadViews({\\n                context: { ...props.context, form_view_ref: props.quickCreateView },\\n                resModel: props.group.resModel,\\n                views: [[false, \\"form\\"]],\\n            });\\n            quickCreateFields = { fields: fields };\\n            quickCreateForm = views.form;\\n            quickCreateRelatedModels = relatedModels;\\n        }\\n        const models = {\\n            ...quickCreateRelatedModels,\\n            [props.group.resModel]: quickCreateFields,\\n        };\\n        const archInfo = new formView.ArchParser().parse(\\n            parseXML(quickCreateForm.arch),\\n            models,\\n            props.group.resModel\\n        );\\n        this.quickCreateProps = {\\n            Model: formView.Model,\\n            Renderer: formView.Renderer,\\n            Compiler: formView.Compiler,\\n            resModel: props.group.resModel,\\n            onValidate: props.onValidate,\\n            onCancel: props.onCancel,\\n            fields: quickCreateFields.fields,\\n            context: props.group.context,\\n            archInfo,\\n        };\\n    }\\n}\\n", "import { Component, onPatched, onWillDestroy, useEffect, useRef, useState } from \\"@odoo/owl\\";\\nimport { ConfirmationDialog } from \\"@web/core/confirmation_dialog/confirmation_dialog\\";\\nimport { Dropdown } from \\"@web/core/dropdown/dropdown\\";\\nimport { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { useHotkey } from \\"@web/core/hotkeys/hotkey_hook\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { evaluateExpr } from \\"@web/core/py_js/py\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { useBus, useService } from \\"@web/core/utils/hooks\\";\\nimport { useSortable } from \\"@web/core/utils/sortable_owl\\";\\nimport { MOVABLE_RECORD_TYPES } from \\"@web/model/relational_model/dynamic_group_list\\";\\nimport { isNull } from \\"@web/views/utils\\";\\nimport { ColumnProgress } from \\"@web/views/view_components/column_progress\\";\\nimport { useBounceButton } from \\"@web/views/view_hook\\";\\nimport { KanbanColumnExamplesDialog } from \\"./kanban_column_examples_dialog\\";\\nimport { KanbanColumnQuickCreate } from \\"./kanban_column_quick_create\\";\\nimport { KanbanHeader } from \\"./kanban_header\\";\\nimport { KanbanRecord } from \\"./kanban_record\\";\\nimport { KanbanRecordQuickCreate } from \\"./kanban_record_quick_create\\";\\nimport { Widget } from \\"@web/views/widgets/widget\\";\\nimport { ActionHelper } from \\"@web/views/action_helper\\";\\n\\nconst DRAGGABLE_GROUP_TYPES = [\\"many2one\\"];\\n\\nfunction validateColumnQuickCreateExamples(data) {\\n    const { allowedGroupBys = [], examples = [], foldField = \\"\\" } = data;\\n    if (!allowedGroupBys.length) {\\n        throw new Error(\\"The example data must contain an array of allowed groupbys\\");\\n    }\\n    if (!examples.length) {\\n        throw new Error(\\"The example data must contain an array of examples\\");\\n    }\\n    const someHasFoldedColumns = examples.some(({ foldedColumns = [] }) => foldedColumns.length);\\n    if (!foldField && someHasFoldedColumns) {\\n        throw new Error(\\"The example data must contain a fold field if there are folded columns\\");\\n    }\\n}\\n\\nexport class KanbanRenderer extends Component {\\n    static template = \\"web.KanbanRenderer\\";\\n    static components = {\\n        Dropdown,\\n        DropdownItem,\\n        ColumnProgress,\\n        KanbanColumnQuickCreate,\\n        KanbanHeader,\\n        KanbanRecord,\\n        KanbanRecordQuickCreate,\\n        Widget,\\n        ActionHelper,\\n    };\\n    static props = [\\n        \\"archInfo\\",\\n        \\"Compiler\\",\\n        \\"list\\",\\n        \\"deleteRecord\\",\\n        \\"openRecord\\",\\n        \\"readonly?\\",\\n        \\"forceGlobalClick?\\",\\n        \\"noContentHelp?\\",\\n        \\"scrollTop?\\",\\n        \\"canQuickCreate?\\",\\n        \\"quickCreateState?\\",\\n        \\"progressBarState?\\",\\n        \\"addLabel?\\",\\n        \\"onAdd?\\",\\n    ];\\n\\n    static defaultProps = {\\n        scrollTop: () => {},\\n        quickCreateState: { groupId: false },\\n        tooltipInfo: {},\\n    };\\n\\n    setup() {\\n        this.dialogClose = [];\\n        /**\\n         * @type {{ processedIds: string[], columnQuickCreateIsFolded: boolean }}\\n         */\\n        this.state = useState({\\n            selectionAvailable: false,\\n            processedIds: [],\\n            columnQuickCreateIsFolded:\\n                !this.props.list.isGrouped || this.props.list.groups.length > 0,\\n        });\\n        this.dialog = useService(\\"dialog\\");\\n        this.exampleData = registry\\n            .category(\\"kanban_examples\\")\\n            .get(this.props.archInfo.examples, null);\\n        if (this.exampleData) {\\n            validateColumnQuickCreateExamples(this.exampleData);\\n        }\\n        this.lastCheckedRecord = null;\\n\\n        // Sortable\\n        let dataRecordId;\\n        let dataGroupId;\\n        this.rootRef = useRef(\\"root\\");\\n        if (this.canUseSortable) {\\n            useSortable({\\n                enable: () => this.canResequenceRecords,\\n                // Params\\n                ref: this.rootRef,\\n                elements: \\".o_draggable\\",\\n                ignore: \\".dropdown,select\\",\\n                groups: () => this.props.list.isGrouped && \\".o_kanban_group\\",\\n                connectGroups: () => this.canMoveRecords,\\n                cursor: \\"move\\",\\n                placeholderClasses: [\\"visible\\", \\"opacity-50\\", \\"my-2\\"],\\n                // Hooks\\n                onDragStart: (params) => {\\n                    const { element, group } = params;\\n                    dataRecordId = element.dataset.id;\\n                    dataGroupId = group && group.dataset.id;\\n                    if (this.props.list.selection?.length) {\\n                        this.props.list.selection.forEach((record) => {\\n                            record.toggleSelection(false);\\n                        });\\n                    }\\n                    return this.sortStart(params);\\n                },\\n                onDragEnd: (params) => this.sortStop(params),\\n                onGroupEnter: (params) => this.sortRecordGroupEnter(params),\\n                onGroupLeave: (params) => this.sortRecordGroupLeave(params),\\n                onDrop: (params) => this.sortRecordDrop(dataRecordId, dataGroupId, params),\\n            });\\n            useSortable({\\n                enable: () => this.canResequenceGroups,\\n                // Params\\n                ref: this.rootRef,\\n                elements: \\".o_group_draggable\\",\\n                handle: \\".o_column_title\\",\\n                cursor: \\"move\\",\\n                // Hooks\\n                onDragStart: (params) => {\\n                    const { element } = params;\\n                    dataGroupId = element.dataset.id;\\n                    return this.sortStart(params);\\n                },\\n                onDragEnd: (params) => this.sortStop(params),\\n                onDrop: (params) => this.sortGroupDrop(dataGroupId, params),\\n            });\\n        }\\n\\n        useBounceButton(this.rootRef, (clickedEl) => {\\n            if (\\n                this.props.list.isGrouped\\n                    ? !this.props.list.recordCount\\n                    : !this.props.list.count || this.props.list.model.useSampleModel\\n            ) {\\n                return clickedEl.matches(\\n                    [\\n                        \\".o_kanban_renderer\\",\\n                        \\".o_kanban_group\\",\\n                        \\".o_kanban_header\\",\\n                        \\".o_column_quick_create\\",\\n                        \\".o_view_nocontent_smiling_face\\",\\n                    ].join(\\", \\")\\n                );\\n            }\\n            return false;\\n        });\\n        onWillDestroy(() => {\\n            this.dialogClose.forEach((close) => close());\\n        });\\n\\n        if (this.env.searchModel) {\\n            useBus(this.env.searchModel, \\"focus-view\\", () => {\\n                const { model } = this.props.list;\\n                if (model.useSampleModel || !model.hasData()) {\\n                    return;\\n                }\\n                const firstCard = this.rootRef.el.querySelector(\\".o_kanban_record\\");\\n                if (firstCard) {\\n                    // Focus first kanban card\\n                    firstCard.focus();\\n                }\\n            });\\n        }\\n\\n        useHotkey(\\n            \\"Enter\\",\\n            ({ target }) => {\\n                if (target.closest(\\".o_kanban_selection_active\\") !== null) {\\n                    return;\\n                }\\n\\n                if (!target.classList.contains(\\"o_kanban_record\\")) {\\n                    return;\\n                }\\n\\n                if (this.props.archInfo.canOpenRecords) {\\n                    target.click();\\n                    return;\\n                }\\n\\n                // Open first link\\n                const firstLink = target.querySelector(\\"a, button\\");\\n                if (firstLink) {\\n                    firstLink.click();\\n                }\\n            },\\n            { area: () => this.rootRef.el }\\n        );\\n\\n        useHotkey(\\"space\\", ({ target }) => this.onSpaceKeyPress(target), {\\n            area: () => this.rootRef.el,\\n        });\\n\\n        useHotkey(\\"shift+space\\", ({ target }) => this.onSpaceKeyPress(target, true), {\\n            area: () => this.rootRef.el,\\n        });\\n\\n        const arrowsOptions = { area: () => this.rootRef.el, allowRepeat: true };\\n        if (this.env.searchModel) {\\n            useHotkey(\\n                \\"ArrowUp\\",\\n                ({ area }) => {\\n                    if (!this.focusNextCard(area, \\"up\\")) {\\n                        this.env.searchModel.trigger(\\"focus-search\\");\\n                    }\\n                },\\n                arrowsOptions\\n            );\\n        }\\n        useHotkey(\\"ArrowDown\\", ({ area }) => this.focusNextCard(area, \\"down\\"), arrowsOptions);\\n        useHotkey(\\"ArrowLeft\\", ({ area }) => this.focusNextCard(area, \\"left\\"), arrowsOptions);\\n        useHotkey(\\"ArrowRight\\", ({ area }) => this.focusNextCard(area, \\"right\\"), arrowsOptions);\\n        const handleAltKeyDown = (ev) => {\\n            if (ev.key === \\"Alt\\") {\\n                this.state.selectionAvailable = true;\\n            }\\n        };\\n        const handleAltKeyUp = () => {\\n            this.state.selectionAvailable = false;\\n        };\\n        useEffect(\\n            () => {\\n                window.addEventListener(\\"keydown\\", handleAltKeyDown);\\n                window.addEventListener(\\"keyup\\", handleAltKeyUp);\\n                window.addEventListener(\\"blur\\", handleAltKeyUp);\\n                return () => {\\n                    window.removeEventListener(\\"keydown\\", handleAltKeyDown);\\n                    window.removeEventListener(\\"keyup\\", handleAltKeyUp);\\n                    window.removeEventListener(\\"blur\\", handleAltKeyUp);\\n                };\\n            },\\n            () => []\\n        );\\n\\n        // After a group is unfolded through onGroupClick, we want to scroll towards\\n        // the next group if it exists and is folded, and to the unfolded group\\n        // itself otherwise\\n        onPatched(() => {\\n            if (this.lastOpenedGroupId) {\\n                const groups = this.getGroupsOrRecords();\\n                const lastOpenedGroupIndex = groups.findIndex(\\n                    (g) => g.group.id === this.lastOpenedGroupId\\n                );\\n                let groupIdToFocus = this.lastOpenedGroupId;\\n                if (\\n                    lastOpenedGroupIndex < groups.length - 1 &&\\n                    groups[lastOpenedGroupIndex + 1].group.isFolded\\n                ) {\\n                    groupIdToFocus = groups[lastOpenedGroupIndex + 1].group.id;\\n                }\\n                const groupEl = this.rootRef.el.querySelector(\\n                    `.o_kanban_group[data-id=\\"${groupIdToFocus}\\"]`\\n                );\\n                const rect = groupEl.getBoundingClientRect();\\n                // Don't scroll if the group to focus is completely inside of the viewport\\n                if (rect.x + rect.width > window.innerWidth) {\\n                    groupEl.scrollIntoView({ behavior: \\"smooth\\", inline: \\"end\\" });\\n                }\\n                delete this.lastOpenedGroupId;\\n            }\\n        });\\n    }\\n\\n    // ------------------------------------------------------------------------\\n    // Getters\\n    // ------------------------------------------------------------------------\\n\\n    get canUseSortable() {\\n        return !this.env.isSmall;\\n    }\\n\\n    get canMoveRecords() {\\n        if (!this.canResequenceRecords) {\\n            return false;\\n        }\\n        const groupByField = this.props.list.groupByField;\\n        if (!groupByField) {\\n            return true;\\n        }\\n        const fieldNodes = Object.values(this.props.archInfo.fieldNodes).filter(\\n            (fieldNode) => fieldNode.name === groupByField.name\\n        );\\n        let isReadonly = this.props.list.fields[groupByField.name].readonly;\\n        if (!isReadonly && fieldNodes.length) {\\n            isReadonly = fieldNodes.every((fieldNode) => {\\n                if (!fieldNode.readonly) {\\n                    return false;\\n                }\\n                try {\\n                    return evaluateExpr(fieldNode.readonly, this.props.list.evalContext);\\n                } catch {\\n                    return false;\\n                }\\n            });\\n        }\\n        return !isReadonly && this.isMovableField(groupByField);\\n    }\\n\\n    get canResequenceGroups() {\\n        if (!this.props.list.isGrouped) {\\n            return false;\\n        }\\n        const { type } = this.props.list.groupByField;\\n        const { groupsDraggable } = this.props.archInfo;\\n        return groupsDraggable && DRAGGABLE_GROUP_TYPES.includes(type);\\n    }\\n\\n    get canResequenceRecords() {\\n        const { isGrouped, orderBy } = this.props.list;\\n        const { handleField, recordsDraggable } = this.props.archInfo;\\n        return Boolean(\\n            recordsDraggable &&\\n                (isGrouped || (handleField && (!orderBy[0] || orderBy[0].name === handleField)))\\n        );\\n    }\\n\\n    get canShowExamples() {\\n        const { allowedGroupBys = [], examples = [] } = this.exampleData || {};\\n        const hasExamples = Boolean(examples.length);\\n        return hasExamples && allowedGroupBys.includes(this.props.list.groupByField.name);\\n    }\\n\\n    get showNoContentHelper() {\\n        const { model, isGrouped, groupByField, groups } = this.props.list;\\n        if (model.useSampleModel) {\\n            return true;\\n        }\\n        if (isGrouped) {\\n            if (this.props.quickCreateState.groupId) {\\n                return false;\\n            }\\n            if (this.canCreateGroup() && !this.state.columnQuickCreateIsFolded) {\\n                return false;\\n            }\\n            if (groups.length === 0) {\\n                return groupByField.type !== \\"many2one\\";\\n            }\\n        }\\n        return !model.hasData();\\n    }\\n\\n    getSelection() {\\n        return this.props.list.selection || [];\\n    }\\n\\n    /**\\n     * When the kanban records are grouped, the 'false' or 'undefined' group\\n     * must appear first.\\n     * @returns {any[]}\\n     */\\n    getGroupsOrRecords() {\\n        const { list } = this.props;\\n        if (list.isGrouped) {\\n            return [...list.groups]\\n                .sort((a, b) => (a.value && !b.value ? 1 : !a.value && b.value ? -1 : 0))\\n                .map((group, i) => ({\\n                    group,\\n                    key: isNull(group.value) ? `group_key_${i}` : String(group.value),\\n                }));\\n        } else {\\n            return list.records.map((record) => ({ record, key: record.id }));\\n        }\\n    }\\n\\n    /**\\n     * @param {RelationalGroup} group\\n     * @param {boolean} isGroupProcessing\\n     * @returns {string}\\n     */\\n    getGroupClasses(group, isGroupProcessing) {\\n        const classes = [];\\n        if (!isGroupProcessing && this.canResequenceGroups && group.value) {\\n            classes.push(\\"o_group_draggable\\");\\n        }\\n        if (!group.count) {\\n            classes.push(\\"o_kanban_no_records\\");\\n        }\\n        if (!this.env.isSmall && group.isFolded) {\\n            classes.push(\\"o_column_folded\\", \\"flex-basis-0\\");\\n        }\\n        if (this.props.progressBarState && !group.isFolded) {\\n            const progressBarInfo = this.props.progressBarState.getGroupInfo(group);\\n            if (progressBarInfo.activeBar) {\\n                const progressBar = progressBarInfo.bars.find(\\n                    (b) => b.value === progressBarInfo.activeBar\\n                );\\n                classes.push(\\"o_kanban_group_show\\", `o_kanban_group_show_${progressBar.color}`);\\n            }\\n        }\\n        return classes.join(\\" \\");\\n    }\\n\\n    getGroupUnloadedCount(group) {\\n        const records = group.list.records.filter((r) => !r.isInQuickCreation);\\n        const count = this.props.progressBarState?.getGroupCount(group) || group.count;\\n        return count - records.length;\\n    }\\n\\n    /**\\n     * @param {string} id\\n     * @returns {boolean}\\n     */\\n    isProcessing(id) {\\n        return this.state.processedIds.includes(id);\\n    }\\n\\n    isMovableField(field) {\\n        return MOVABLE_RECORD_TYPES.includes(field.type);\\n    }\\n\\n    // ------------------------------------------------------------------------\\n    // Permissions\\n    // ------------------------------------------------------------------------\\n\\n    canCreateGroup() {\\n        const { activeActions, defaultGroupBy } = this.props.archInfo;\\n        return (\\n            activeActions.createGroup &&\\n            this.props.list.groupByField.type === \\"many2one\\" &&\\n            this.props.list.groupByField.name === defaultGroupBy?.[0]\\n        );\\n    }\\n\\n    canQuickCreate() {\\n        return this.props.canQuickCreate;\\n    }\\n\\n    // ------------------------------------------------------------------------\\n    // Edition methods\\n    // ------------------------------------------------------------------------\\n\\n    async archiveRecord(record, active) {\\n        if (active) {\\n            this.dialog.add(ConfirmationDialog, {\\n                body: _t(\\"Are you sure that you want to archive this record?\\"),\\n                confirmLabel: _t(\\"Archive\\"),\\n                confirm: () => record.archive(),\\n                cancel: () => {},\\n            });\\n        } else {\\n            return record.unarchive();\\n        }\\n    }\\n\\n    async validateQuickCreate(recordId, mode, group) {\\n        const record = await group.addExistingRecord(recordId, true);\\n        if (mode === \\"edit\\") {\\n            await this.props.openRecord(record);\\n        } else {\\n            this.props.progressBarState?.updateCounts(group);\\n        }\\n        this.props.quickCreateState.groupId = mode === \\"add\\" ? group.id : false;\\n    }\\n\\n    cancelQuickCreate() {\\n        this.props.quickCreateState.groupId = false;\\n    }\\n\\n    async deleteGroup(group) {\\n        await this.props.list.deleteGroups([group]);\\n        if (this.props.list.groups.length === 0) {\\n            this.state.columnQuickCreateIsFolded = false;\\n        }\\n    }\\n\\n    toggleGroup(group) {\\n        return group.toggle();\\n    }\\n\\n    loadMore(group) {\\n        return group.list.load({ limit: group.list.records.length + group.model.initialLimit });\\n    }\\n\\n    /**\\n     * @param {string} id\\n     * @param {boolean} isProcessing\\n     */\\n    toggleProcessing(id, isProcessing) {\\n        if (isProcessing) {\\n            this.state.processedIds = [...this.state.processedIds, id];\\n        } else {\\n            this.state.processedIds = this.state.processedIds.filter(\\n                (processedId) => processedId !== id\\n            );\\n        }\\n    }\\n\\n    toggleSelection(record, isRange = false) {\\n        if (isRange) {\\n            this.toggleRangeSelection(record);\\n        } else {\\n            record.toggleSelection();\\n        }\\n        this.lastCheckedRecord = record;\\n    }\\n\\n    toggleRangeSelection(record) {\\n        const { records } = this.props.list;\\n        const recordIndex = records.findIndex((e) => e.id === record.id);\\n        const lastCheckedRecordIndex = records.findIndex((e) => e.id === this.lastCheckedRecord.id);\\n        const start = Math.min(recordIndex, lastCheckedRecordIndex);\\n        const end = Math.max(recordIndex, lastCheckedRecordIndex);\\n        for (let i = start; i <= end; i++) {\\n            records[i].toggleSelection(!record.selected);\\n        }\\n    }\\n\\n    // ------------------------------------------------------------------------\\n    // Handlers\\n    // ------------------------------------------------------------------------\\n\\n    async onGroupClick(group, ev) {\\n        if (!this.env.isSmall && group.isFolded) {\\n            this.lastOpenedGroupId = group.id;\\n            await group.toggle();\\n            this.props.scrollTop();\\n        }\\n    }\\n\\n    /**\\n     * @param {string} dataGroupId\\n     * @param {Object} params\\n     * @param {HTMLElement} params.element\\n     * @param {HTMLElement} [params.group]\\n     * @param {HTMLElement} [params.next]\\n     * @param {HTMLElement} [params.parent]\\n     * @param {HTMLElement} [params.previous]\\n     */\\n    async sortGroupDrop(dataGroupId, { previous }) {\\n        this.toggleProcessing(dataGroupId, true);\\n        const refId = previous ? previous.dataset.id : null;\\n        try {\\n            await this.props.list.resequence(dataGroupId, refId);\\n        } finally {\\n            this.toggleProcessing(dataGroupId, false);\\n        }\\n    }\\n\\n    onSpaceKeyPress(target, isRange) {\\n        if (target.classList.contains(\\"o_kanban_record\\")) {\\n            const record = this.props.list.records.find((e) => e.id === target.dataset.id);\\n            this.toggleSelection(record, isRange);\\n        }\\n    }\\n\\n    showExamples() {\\n        this.dialog.add(KanbanColumnExamplesDialog, {\\n            examples: this.exampleData.examples,\\n            applyExamplesText: this.exampleData.applyExamplesText || _t(\\"Use This For My Kanban\\"),\\n            applyExamples: (index) => {\\n                const { examples, foldField } = this.exampleData;\\n                const { columns, foldedColumns = [] } = examples[index];\\n                for (const groupName of columns) {\\n                    this.props.list.createGroup(groupName);\\n                }\\n                for (const groupName of foldedColumns) {\\n                    this.props.list.createGroup(groupName, foldField);\\n                }\\n            },\\n        });\\n    }\\n\\n    /**\\n     * @param {string} dataRecordId\\n     * @param {string} dataGroupId\\n     * @param {Object} params\\n     * @param {HTMLElement} params.element\\n     * @param {HTMLElement} [params.group]\\n     * @param {HTMLElement} [params.next]\\n     * @param {HTMLElement} [params.parent]\\n     * @param {HTMLElement} [params.previous]\\n     */\\n    async sortRecordDrop(dataRecordId, dataGroupId, { element, parent, previous }) {\\n        if (\\n            !this.props.list.isGrouped ||\\n            parent.classList.contains(\\"o_kanban_hover\\") ||\\n            parent.dataset.id === element.parentElement.dataset.id\\n        ) {\\n            if (!this.props.list.records.find((r) => r.id === dataRecordId)) {\\n                // Race condition: a new rendering has been scheduled/is ongoing but hasn't been\\n                // applied to the DOM yet, so the user dropped a record that is no longer referenced\\n                // in the model. In that case, we can't to anything else than abort.\\n                return;\\n            }\\n            this.toggleProcessing(dataRecordId, true);\\n\\n            parent?.classList.remove(\\"o_kanban_hover\\");\\n            while (previous && !previous.dataset.id) {\\n                previous = previous.previousElementSibling;\\n            }\\n            const refId = previous ? previous.dataset.id : null;\\n            const targetGroupId = parent?.dataset.id;\\n            try {\\n                await this.props.list.moveRecord(dataRecordId, dataGroupId, refId, targetGroupId);\\n            } finally {\\n                this.toggleProcessing(dataRecordId, false);\\n            }\\n        }\\n    }\\n\\n    /**\\n     * @param {Object} params\\n     * @param {HTMLElement} params.group\\n     */\\n    sortRecordGroupEnter({ group }) {\\n        group.classList.add(\\"o_kanban_hover\\");\\n    }\\n\\n    /**\\n     * @param {Object} params\\n     * @param {HTMLElement} params.group\\n     */\\n    sortRecordGroupLeave({ group }) {\\n        group.classList.remove(\\"o_kanban_hover\\");\\n    }\\n\\n    /**\\n     * @param {Object} params\\n     * @param {HTMLElement} params.element\\n     * @param {HTMLElement} [params.group]\\n     */\\n    sortStart({ element }) {\\n        element.classList.add(\\"shadow\\");\\n    }\\n\\n    /**\\n     * @param {Object} params\\n     * @param {HTMLElement} params.element\\n     * @param {HTMLElement} [params.group]\\n     */\\n    sortStop({ element, group }) {\\n        element.classList.remove(\\"shadow\\");\\n        if (group) {\\n            group.classList.remove(\\"o_kanban_hover\\");\\n        }\\n    }\\n\\n    /**\\n     * Focus next card in the area within the chosen direction.\\n     *\\n     * @param {HTMLElement} area\\n     * @param {\\"down\\"|\\"up\\"|\\"right\\"|\\"left\\"} direction\\n     * @returns {true?} true if the next card has been focused\\n     */\\n    focusNextCard(area, direction) {\\n        const { isGrouped } = this.props.list;\\n        const closestCard = document.activeElement.closest(\\".o_kanban_record\\");\\n        if (!closestCard) {\\n            return;\\n        }\\n        const groups = isGrouped ? [...area.querySelectorAll(\\".o_kanban_group\\")] : [area];\\n        const cards = [...groups]\\n            .map((group) => [...group.querySelectorAll(\\".o_kanban_record\\")])\\n            .filter((group) => group.length);\\n\\n        let iGroup;\\n        let iCard;\\n        for (iGroup = 0; iGroup < cards.length; iGroup++) {\\n            const i = cards[iGroup].indexOf(closestCard);\\n            if (i !== -1) {\\n                iCard = i;\\n                break;\\n            }\\n        }\\n        // Find next card to focus\\n        let nextCard;\\n        switch (direction) {\\n            case \\"down\\":\\n                nextCard = iCard < cards[iGroup].length - 1 && cards[iGroup][iCard + 1];\\n                break;\\n            case \\"up\\":\\n                nextCard = iCard > 0 && cards[iGroup][iCard - 1];\\n                break;\\n            case \\"right\\":\\n                if (isGrouped) {\\n                    nextCard = iGroup < cards.length - 1 && cards[iGroup + 1][0];\\n                } else {\\n                    nextCard = iCard < cards[0].length - 1 && cards[0][iCard + 1];\\n                }\\n                break;\\n            case \\"left\\":\\n                if (isGrouped) {\\n                    nextCard = iGroup > 0 && cards[iGroup - 1][0];\\n                } else {\\n                    nextCard = iCard > 0 && cards[0][iCard - 1];\\n                }\\n                break;\\n        }\\n\\n        if (nextCard && nextCard instanceof HTMLElement) {\\n            nextCard.focus();\\n            return true;\\n        }\\n    }\\n}\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { RelationalModel } from \\"@web/model/relational_model/relational_model\\";\\nimport { KanbanArchParser } from \\"./kanban_arch_parser\\";\\nimport { KanbanCompiler } from \\"./kanban_compiler\\";\\nimport { KanbanController } from \\"./kanban_controller\\";\\nimport { KanbanRenderer } from \\"./kanban_renderer\\";\\n\\nexport const kanbanView = {\\n    type: \\"kanban\\",\\n\\n    ArchParser: KanbanArchParser,\\n    Controller: KanbanController,\\n    Model: RelationalModel,\\n    Renderer: KanbanRenderer,\\n    Compiler: KanbanCompiler,\\n\\n    buttonTemplate: \\"web.KanbanView.Buttons\\",\\n\\n    props: (genericProps, view) => {\\n        const { arch, relatedModels, resModel } = genericProps;\\n        const { ArchParser } = view;\\n        const archInfo = new ArchParser().parse(arch, relatedModels, resModel);\\n        return {\\n            ...genericProps,\\n            readonly: genericProps.readonly || !archInfo.activeActions?.edit,\\n            Compiler: view.Compiler,\\n            Model: view.Model,\\n            Renderer: view.Renderer,\\n            buttonTemplate: view.buttonTemplate,\\n            archInfo,\\n        };\\n    },\\n};\\n\\nregistry.category(\\"views\\").add(\\"kanban\\", kanbanView);\\n", "import { reactive } from \\"@odoo/owl\\";\\nimport { Domain } from \\"@web/core/domain\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport {\\n    extractInfoFromGroupData,\\n    getAggregateSpecifications,\\n} from \\"@web/model/relational_model/utils\\";\\n\\nconst FALSE = Symbol(\\"False\\");\\n\\n/**\\n *\\n * @param {*} groups: returned by formatted_read_group\\n * @param {*} groupByField\\n * @param {*} value\\n * @returns\\n */\\n\\nfunction _findGroup(groups, groupByField, value) {\\n    return groups.find((g) => g[groupByField.name] === value) || {};\\n}\\n\\nfunction _createFilterDomain(fieldName, bars, value) {\\n    let filterDomain = undefined;\\n    if (value === FALSE) {\\n        const keys = bars.filter((x) => x.value !== FALSE).map((x) => x.value);\\n        filterDomain = [\\"!\\", [fieldName, \\"in\\", keys]];\\n    } else {\\n        filterDomain = [[fieldName, \\"=\\", value]];\\n    }\\n    return filterDomain;\\n}\\n\\nfunction _groupsToAggregateValues(groups, groupBy, fields, domain) {\\n    const groupByFieldName = groupBy[0].split(\\":\\")[0];\\n    return groups.map((g) => {\\n        const groupInfo = extractInfoFromGroupData(g, groupBy, fields, domain);\\n        return Object.assign(groupInfo.aggregates, { [groupByFieldName]: groupInfo.serverValue });\\n    });\\n}\\n\\nclass ProgressBarState {\\n    constructor(progressAttributes, model, aggregateFields, activeBars = {}) {\\n        this.progressAttributes = progressAttributes;\\n        this.model = model;\\n        this._groupsInfo = {};\\n        this._aggregateFields = aggregateFields;\\n        this.activeBars = activeBars;\\n        this._aggregateValues = [];\\n        this._pbCounts = null;\\n    }\\n\\n    getGroupInfo(group) {\\n        if (this._pbCounts === null) {\\n            // progressbar isn't loaded yet\\n            return {\\n                activeBar: null,\\n                bars: [],\\n                isReady: false,\\n            };\\n        }\\n        if (!this._groupsInfo[group.id]) {\\n            const aggValues = _findGroup(\\n                this._aggregateValues,\\n                group.groupByField,\\n                group.serverValue\\n            );\\n            const index = this._aggregateValues.indexOf(aggValues);\\n            if (index > -1) {\\n                this._aggregateValues.splice(index, 1);\\n            }\\n            this._aggregateValues.push({\\n                ...group.aggregates,\\n                [group.groupByField.name]: group.serverValue,\\n            });\\n            const groupValue = this._getGroupValue(group);\\n            const pbCount = this._pbCounts[groupValue];\\n            const { fieldName, colors } = this.progressAttributes;\\n            const { selection: fieldSelection } = this.model.root.fields[fieldName];\\n            const selection = fieldSelection && Object.fromEntries(fieldSelection);\\n            const bars = Object.entries(colors).map(([value, color]) => {\\n                let string;\\n                if (selection) {\\n                    string = selection[value];\\n                } else {\\n                    string = String(value);\\n                }\\n                return {\\n                    count: (pbCount && pbCount[value]) || 0,\\n                    value,\\n                    string,\\n                    color,\\n                };\\n            });\\n            bars.push({\\n                count: group.count - bars.map((r) => r.count).reduce((a, b) => a + b, 0),\\n                value: FALSE,\\n                string: _t(\\"Other\\"),\\n                color: \\"200\\",\\n            });\\n\\n            // Update activeBars count and aggreagates\\n            if (this.activeBars[group.serverValue]) {\\n                this.activeBars[group.serverValue].count = bars.find(\\n                    (x) => x.value === this.activeBars[group.serverValue].value\\n                ).count;\\n\\n                if (this.activeBars[group.serverValue].count === 0) {\\n                    group.applyFilter(undefined).then(() => {\\n                        delete this.activeBars[group.serverValue];\\n                        group.model.notify();\\n                    });\\n                }\\n\\n                if (this._aggregateFields.length) {\\n                    //recompute the aggregates is not necessary\\n                    //the formatted_read_group was already done with the correct domain (containing the applied filter)\\n                    this.activeBars[group.serverValue].aggregates = _findGroup(\\n                        this._aggregateValues,\\n                        group.groupByField,\\n                        group.serverValue\\n                    );\\n                }\\n            }\\n\\n            const self = this;\\n            const progressBar = {\\n                get activeBar() {\\n                    return self.activeBars[group.serverValue]?.value || null;\\n                },\\n                bars,\\n                isReady: true,\\n            };\\n\\n            this._groupsInfo[group.id] = progressBar;\\n        }\\n        return this._groupsInfo[group.id];\\n    }\\n\\n    getAggregateValue(group, aggregateField) {\\n        const { groupByField, serverValue } = group;\\n        const title = aggregateField ? aggregateField.string : _t(\\"Count\\");\\n        let value = 0;\\n        if (!this.activeBars[serverValue]) {\\n            value = group.count;\\n            if (value && aggregateField) {\\n                value = _findGroup(this._aggregateValues, groupByField, serverValue)[\\n                    aggregateField.name\\n                ];\\n            }\\n        } else {\\n            value = this.activeBars[serverValue].count;\\n            if (value && aggregateField) {\\n                value =\\n                    this.activeBars[serverValue]?.aggregates &&\\n                    this.activeBars[serverValue]?.aggregates[aggregateField.name];\\n            }\\n        }\\n        value ||= 0;\\n        if (aggregateField.type === \\"monetary\\" && aggregateField.currency_field) {\\n            const aggValues = _findGroup(this._aggregateValues, groupByField, serverValue);\\n            const currencies = aggValues?.[aggregateField.currency_field];\\n            if (currencies?.length > 1) {\\n                return {\\n                    value,\\n                    currencies,\\n                };\\n            }\\n            if (currencies?.[0]) {\\n                return {\\n                    title,\\n                    value,\\n                    currencies: [currencies[0]],\\n                };\\n            }\\n        }\\n        return { title, value };\\n    }\\n\\n    async selectBar(groupId, bar) {\\n        const group = this.model.root.groups.find((group) => group.id === groupId);\\n        const progressBar = this.getGroupInfo(group);\\n        const nextActiveBar = {};\\n        if (bar.value && this.activeBars[group.serverValue]?.value !== bar.value) {\\n            nextActiveBar.value = bar.value;\\n        } else {\\n            group.applyFilter(undefined).then(() => {\\n                delete this.activeBars[group.serverValue];\\n                group.model.notify();\\n            });\\n            return;\\n        }\\n        const { bars } = progressBar;\\n        const filterDomain = _createFilterDomain(\\n            this.progressAttributes.fieldName,\\n            bars,\\n            nextActiveBar.value\\n        );\\n        const proms = [];\\n        proms.push(\\n            group.applyFilter(filterDomain).then((res) => {\\n                const groupInfo = this.getGroupInfo(group);\\n                nextActiveBar.count = groupInfo.bars.find(\\n                    (x) => x.value === nextActiveBar.value\\n                ).count;\\n            })\\n        );\\n        if (this._aggregateFields.length) {\\n            proms.push(this._updateAggregateGroup(group, bars, nextActiveBar));\\n        }\\n        await Promise.all(proms);\\n        this.activeBars[group.serverValue] = nextActiveBar;\\n        this.updateCounts(group);\\n    }\\n\\n    _updateAggregateGroup(group, bars, activeBar) {\\n        const filterDomain = _createFilterDomain(\\n            this.progressAttributes.fieldName,\\n            bars,\\n            activeBar.value\\n        );\\n        const { context, fields, groupBy, resModel } = this.model.root;\\n        const kwargs = { context };\\n        const aggregateSpecs = getAggregateSpecifications(this._aggregateFields);\\n        const domain = filterDomain\\n            ? Domain.and([group.groupDomain, filterDomain]).toList()\\n            : group.groupDomain;\\n        return this.model.orm\\n            .formattedReadGroup(resModel, domain, groupBy, aggregateSpecs, kwargs)\\n            .then((groups) => {\\n                if (groups.length) {\\n                    const groupByField = group.groupByField;\\n                    const aggrValues = _groupsToAggregateValues(groups, groupBy, fields, domain);\\n                    activeBar.aggregates = _findGroup(aggrValues, groupByField, group.serverValue);\\n                }\\n            });\\n    }\\n\\n    updateCounts(group) {\\n        this._updateProgressBar();\\n        if (this._aggregateFields.length) {\\n            this._updateAggregates();\\n            this.updateAggregateGroup(group);\\n        }\\n\\n        // If the selected bar is empty, remove the selection\\n        for (const group of this.model.root.groups) {\\n            if (this.activeBars[group.serverValue] && group.list.count === 0) {\\n                this.selectBar(group.id, { value: null });\\n            }\\n        }\\n    }\\n\\n    updateAggregateGroup(group) {\\n        if (group && this.activeBars[group.serverValue]) {\\n            const { bars } = this.getGroupInfo(group);\\n            this._updateAggregateGroup(group, bars, this.activeBars[group.serverValue]);\\n        }\\n    }\\n\\n    async _updateAggregates() {\\n        const { context, fields, groupBy, domain, resModel } = this.model.root;\\n        const kwargs = { context };\\n        const groups = await this.model.orm.formattedReadGroup(\\n            resModel,\\n            domain,\\n            groupBy,\\n            getAggregateSpecifications(this._aggregateFields),\\n            kwargs\\n        );\\n        this._aggregateValues = _groupsToAggregateValues(groups, groupBy, fields);\\n    }\\n\\n    async _updateProgressBar() {\\n        const groupBy = this.model.root.groupBy;\\n        if (groupBy.length) {\\n            const resModel = this.model.root.resModel;\\n            const domain = this.model.root.domain;\\n            const context = this.model.root.context;\\n            const { colors, fieldName: field, help } = this.progressAttributes;\\n            const groupsId = this.model.root.groups.map((g) => g.id).join();\\n            const res = await this.model.orm.call(resModel, \\"read_progress_bar\\", [], {\\n                domain,\\n                group_by: groupBy[0],\\n                progress_bar: { colors, field, help },\\n                context,\\n            });\\n            if (groupsId !== this.model.root.groups.map((g) => g.id).join()) {\\n                return;\\n            }\\n            this._pbCounts = res;\\n            for (const group of this.model.root.groups) {\\n                if (!group.isFolded) {\\n                    const groupInfo = this.getGroupInfo(group);\\n                    const groupValue = this._getGroupValue(group);\\n                    const counts = res[groupValue];\\n                    for (const bar of groupInfo.bars) {\\n                        bar.count = (counts && counts[bar.value]) || 0;\\n                    }\\n                    groupInfo.bars.find((b) => b.value === FALSE).count = counts\\n                        ? group.count - Object.values(counts).reduce((a, b) => a + b, 0)\\n                        : group.count;\\n\\n                    if (this.activeBars[group.serverValue]) {\\n                        this.activeBars[group.serverValue].count = groupInfo.bars.find(\\n                            (x) => x.value === this.activeBars[group.serverValue].value\\n                        ).count;\\n                    }\\n                }\\n            }\\n        }\\n    }\\n\\n    async loadProgressBar({ context, domain, groupBy, resModel }) {\\n        if (groupBy.length) {\\n            const { colors, fieldName: field, help } = this.progressAttributes;\\n            const res = await this.model.orm.call(resModel, \\"read_progress_bar\\", [], {\\n                domain,\\n                group_by: groupBy[0],\\n                progress_bar: { colors, field, help },\\n                context,\\n            });\\n            this._pbCounts = res;\\n        }\\n    }\\n\\n    getGroupCount(group) {\\n        const progressBarInfo = this.getGroupInfo(group);\\n        if (progressBarInfo.activeBar) {\\n            const progressBar = progressBarInfo.bars.find(\\n                (b) => b.value === progressBarInfo.activeBar\\n            );\\n            return progressBar.count;\\n        }\\n    }\\n\\n    /**\\n     * We must be able to match groups returned by the read_progress_bar call with groups previously\\n     * returned by formatted_read_group. When grouped on date(time) fields, the key of each group is the\\n     * displayName of the period (e.g. \\"W8 2024\\"). When grouped on boolean fields, it's \\"True\\" and\\n     * \\"False\\". For falsy values (e.g. unset many2one), it's \\"False\\". In all other cases, it's the\\n     * group's value (e.g. the id for a many2one).\\n     *\\n     * @param {Group} group\\n     * @return string\\n     */\\n    _getGroupValue(group) {\\n        if (group.value === true) {\\n            return \\"True\\";\\n        } else if (group.value === false) {\\n            return \\"False\\";\\n        }\\n        return group.serverValue;\\n    }\\n}\\n\\nexport function useProgressBar(progressAttributes, model, aggregateFields, activeBars) {\\n    const progressBarState = reactive(\\n        new ProgressBarState(progressAttributes, model, aggregateFields, activeBars)\\n    );\\n\\n    const onWillLoadRoot = model.hooks.onWillLoadRoot;\\n    let prom;\\n    model.hooks.onWillLoadRoot = (config) => {\\n        onWillLoadRoot();\\n        prom = progressBarState.loadProgressBar({\\n            context: config.context,\\n            domain: config.domain,\\n            groupBy: config.groupBy,\\n            resModel: config.resModel,\\n        });\\n    };\\n    const onRootLoaded = model.hooks.onRootLoaded;\\n    model.hooks.onRootLoaded = async (root) => {\\n        await onRootLoaded(root);\\n        if (model.isReady) {\\n            // do not wait for the progressbar on first load, to show the kanban view asap\\n            return prom;\\n        }\\n    };\\n\\n    return progressBarState;\\n}\\n", "import { renderToElement } from \\"@web/core/utils/render\\";\\nimport { useDebounced } from \\"@web/core/utils/timing\\";\\nimport {\\n    formatDate,\\n    formatDateTime,\\n    toLocaleDateString,\\n    toLocaleDateTimeString,\\n} from \\"@web/core/l10n/dates\\";\\nimport { localization } from \\"@web/core/l10n/localization\\";\\n\\nimport {\\n    onMounted,\\n    onWillUnmount,\\n    status,\\n    useComponent,\\n    useEffect,\\n    useExternalListener,\\n    xml,\\n} from \\"@odoo/owl\\";\\n\\n// This file defines a hook that encapsulates the column width logic of the list view. This logic\\n// aims at optimizing the available space between columns and, once computed, at freezing the table\\n// to ensure that the columns don't flicker. This hook is meant to be used by the ListRenderer only,\\n// it isn't a generic hook that can be used in various contexts.\\n//\\n// Widths computation specs\\n// ------------------------\\n//\\n// For some field types, we harcode the column width because we know the required space to display\\n// values for that type (e.g. a Date field always requires the same space). A width can also be\\n// hardcoded in the arch (`width=\\"60px\\"`). In those cases, the column has a fixed width that we\\n// enforce. Note that the column width will be the given width + the cell's left and right paddings.\\n// Numeric fields don't technically have a fixed width, but rather a range: we always want enough\\n// space s.t. `1 million` would fit, and we consider that we don't need more space than `1 billion`\\n// would require to fit. Depending on the field type (integer, float, monetary), we determine the\\n// necessary width to display those numbers.\\n// The other columns have an hardcoded min width, that we always want to guarantee, but they have no\\n// max width.\\n//\\n// There're two cases. In both of them, we need to compute a starting point for the widths:\\n//   - there's no data in the table: we force all columns with hardcoded widths to those widths and\\n//     uniformly distribute the remaining space among the other columns.\\n//   - there're records in the table, we let the browser compute ideal widths based on the content\\n//     of the table.\\n// Once this is done, we ensure that each column complies with their min and max widths. It may\\n// happen that some columns are too narrow (because their content is small, and there're a lot of\\n// columns), so we expand them to their minimal width. It may also happen that some columns are too\\n// wide (if they have a max width), so we shrink them.\\n// Once this is done, we must ensure that the sum of the column widths still fills 100% of the\\n// table. That means that we might have to expand/narrow columns, again. It may happen that the\\n// table has too many columns s.t. they can't fit within the 100% by complying the the rules, it's\\n// fine, an horizontal scrollbar will be displayed in that case.\\n//\\n// Freeze logic\\n// ------------\\n//\\n// Once optimal widths have been computed, we want the table to be frozen s.t. columns don't resize\\n// upon user interaction, like inline edition, adding or removing a record... The computed widths\\n// are thus stored, and re-applied at each rendering. There're exceptions though. If the columns\\n// change (e.g. optional column toggled), if the window is resized, if we remove a filter or open\\n// a group s.t. the list contains records for the first time, we forget the computed widths and\\n// start over.\\n\\n// Hardcoded widths\\nconst DEFAULT_MIN_WIDTH = 80;\\nconst SELECTOR_WIDTH = 20;\\nconst OPEN_FORM_VIEW_BUTTON_WIDTH = 54;\\nconst DELETE_BUTTON_WIDTH = 12;\\nlet _dateWidths = null; // computed dynamically, lazily, see @computeOptimalDateWidths\\nexport const FIELD_WIDTHS = Object.freeze({\\n    boolean: [20, 100], // [minWidth, maxWidth]\\n    char: [80], // only minWidth, no maxWidth\\n    get date() {\\n        if (!_dateWidths) {\\n            computeOptimalDateWidths();\\n        }\\n        return _dateWidths.date;\\n    },\\n    get datetime() {\\n        if (!_dateWidths) {\\n            computeOptimalDateWidths();\\n        }\\n        return _dateWidths.datetime;\\n    },\\n    get numeric_date() {\\n        if (!_dateWidths) {\\n            computeOptimalDateWidths();\\n        }\\n        return _dateWidths.numericDate;\\n    },\\n    get numeric_datetime() {\\n        if (!_dateWidths) {\\n            computeOptimalDateWidths();\\n        }\\n        return _dateWidths.numericDatetime;\\n    },\\n    float: 93,\\n    integer: 71,\\n    many2many: [80],\\n    many2one_reference: [80],\\n    many2one: [80],\\n    monetary: 105,\\n    one2many: [80],\\n    reference: [80],\\n    selection: [80],\\n    text: [80, 1200],\\n});\\n\\nexport function resetDateFieldWidths() {\\n    // useful for tests\\n    _dateWidths = null;\\n}\\n\\n/**\\n * Compute ideal date and datetime widths. There's no static value for them as they depend on the\\n * localization. Moreover, as we want to have the exact minimum width necessary, it also depends on\\n * the fonts (we never want to see \\"...\\" in date fields). So we render date(time) values, we insert\\n * them into the DOM and compute their width.\\n */\\nfunction computeOptimalDateWidths() {\\n    const { timeFormat } = localization;\\n    const values = {\\n        date: [],\\n        datetime: [],\\n        numericDate: [],\\n        numericDatetime: [],\\n    };\\n    // dates in the \\"human readable\\" format (must generate a date by month as width could vary)\\n    for (let month = 1; month <= 12; month++) {\\n        values.date.push(toLocaleDateString(luxon.DateTime.local(2017, month, 20)));\\n        values.datetime.push(\\n            toLocaleDateTimeString(luxon.DateTime.local(2017, month, 25, 10, 0, 0), {\\n                showSeconds: true,\\n            })\\n        );\\n        if (timeFormat === \\"hh:mm:ss a\\") {\\n            // generate a date in the afternoon if time is displayed with AM/PM or equivalent\\n            values.datetime.push(\\n                toLocaleDateTimeString(luxon.DateTime.local(2017, month, 25, 22, 0, 0), {\\n                    showSeconds: true,\\n                })\\n            );\\n        }\\n    }\\n    // dates in the \\"numeric\\" format\\n    values.numericDate.push(formatDate(luxon.DateTime.local(2017, 1, 1)));\\n    values.numericDatetime.push(formatDateTime(luxon.DateTime.local(2017, 1, 1, 10, 0, 0)));\\n    if (timeFormat === \\"hh:mm:ss a\\") {\\n        // generate a date in the afternoon if time is displayed with AM/PM or equivalent\\n  