t: { type: Object },\\n    };\\n    setup() {\\n        this.dialog = useService(\\"dialog\\");\\n    }\\n\\n    get configItems() {\\n        const args = { permissions: this.permissions };\\n        return this.props.configItems.map(([key, desc]) => ({\\n            key,\\n            label: desc.label,\\n            class: typeof desc.class === \\"function\\" ? desc.class(args) : desc.class,\\n            icon: desc.icon,\\n            isVisible: typeof desc.isVisible === \\"function\\" ? desc.isVisible(args) : desc.isVisible,\\n            method: typeof desc.method === \\"function\\" ? desc.method : this[desc.method].bind(this),\\n        }));\\n    }\\n\\n    get group() {\\n        return this.props.group;\\n    }\\n\\n    get permissions() {\\n        return [\\"canDeleteGroup\\", \\"canEditGroup\\"].reduce((o, key) => {\\n            Object.defineProperty(o, key, { get: () => this[key]() });\\n            return o;\\n        }, {});\\n    }\\n\\n    deleteGroup() {\\n        this.dialog.add(ConfirmationDialog, {\\n            body: _t(\\"Are you sure you want to delete this column?\\"),\\n            confirm: () => this.props.deleteGroup(this.group),\\n            confirmLabel: _t(\\"Delete\\"),\\n            cancel: () => {},\\n        });\\n    }\\n\\n    editGroup() {\\n        const { context, displayName, groupByField, value } = this.group;\\n        this.props.dialogClose.push(\\n            this.dialog.add(FormViewDialog, {\\n                context,\\n                resId: value,\\n                resModel: groupByField.relation,\\n                title: _t(\\"Edit: %s\\", displayName),\\n                onRecordSaved: () => this.props.list.load(),\\n            })\\n        );\\n    }\\n\\n    canDeleteGroup() {\\n        const { deleteGroup } = this.props.activeActions;\\n        const { groupByField, value } = this.group;\\n        return deleteGroup && isRelational(groupByField) && value;\\n    }\\n\\n    canEditGroup() {\\n        const { editGroup } = this.props.activeActions;\\n        const { groupByField, value } = this.group;\\n        return editGroup && isRelational(groupByField) && value;\\n    }\\n}\\n\\nconst groupConfigItems = registry.category(\\"group_config_items\\");\\ngroupConfigItems.add(\\n    \\"edit_group\\",\\n    {\\n        label: _t(\\"Edit\\"),\\n        isVisible: ({ permissions }) => permissions.canEditGroup,\\n        class: \\"o_group_edit\\",\\n        icon: \\"fa-pencil\\",\\n        method: \\"editGroup\\",\\n    },\\n    { sequence: 20 }\\n);\\ngroupConfigItems.add(\\n    \\"delete_group\\",\\n    {\\n        label: _t(\\"Delete\\"),\\n        isVisible: ({ permissions }) => permissions.canDeleteGroup,\\n        class: \\"o_group_delete text-danger\\",\\n        icon: \\"fa-trash\\",\\n        method: \\"deleteGroup\\",\\n    },\\n    { sequence: 30 }\\n);\\n", "import { Component } from \\"@odoo/owl\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { TimePicker } from \\"@web/core/time_picker/time_picker\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { Record } from \\"@web/model/record\\";\\nimport { useCallbackRecorder } from \\"@web/search/action_hook\\";\\nimport { FormRenderer } from \\"@web/views/form/form_renderer\\";\\n\\nexport class MultiCreatePopover extends Component {\\n    static template = \\"web.MultiCreatePopover\\";\\n    static components = {\\n        FormRenderer,\\n        Record,\\n        TimePicker,\\n    };\\n    static props = {\\n        close: Function,\\n        multiCreateArchInfo: Object,\\n        multiCreateRecordProps: Object,\\n        onAdd: Function,\\n        callbackRecorder: Object,\\n        timeRange: { type: [Object, { value: null }] },\\n    };\\n\\n    setup() {\\n        this.notification = useService(\\"notification\\");\\n\\n        this.multiCreateData = {\\n            timeRange: this.props.timeRange && { ...this.props.timeRange },\\n        };\\n        this.multiCreateArchInfo = this.props.multiCreateArchInfo;\\n        this.multiCreateRecordProps = {\\n            ...this.props.multiCreateRecordProps,\\n            hooks: {\\n                onRootLoaded: (record) => {\\n                    this.multiCreateData.record = record;\\n                },\\n            },\\n        };\\n\\n        useCallbackRecorder(this.props.callbackRecorder, () => this.multiCreateData);\\n    }\\n\\n    setMultiCreateTimeRange(timeRange) {\\n        Object.assign(this.multiCreateData.timeRange, timeRange);\\n    }\\n\\n    async isValidMultiCreateData() {\\n        const isValid = await this.multiCreateData.record.checkValidity({\\n            displayNotification: true,\\n        });\\n        if (!isValid) {\\n            return false;\\n        }\\n        if (this.multiCreateData.timeRange) {\\n            const { start, end } = this.multiCreateData.timeRange;\\n            if (!start || !end) {\\n                this.notification.add(_t(\\"Invalid time range\\"), {\\n                    title: \\"User Error\\",\\n                    type: \\"warning\\",\\n                });\\n                return false;\\n            }\\n            if (\\n                luxon.DateTime.fromObject(start.toObject()) >\\n                luxon.DateTime.fromObject(end.toObject())\\n            ) {\\n                this.notification.add(_t(\\"Start time should be before end time\\"), {\\n                    title: \\"User Error\\",\\n                    type: \\"warning\\",\\n                });\\n                return false;\\n            }\\n        }\\n        return true;\\n    }\\n\\n    async onAdd() {\\n        const isValid = await this.isValidMultiCreateData();\\n        if (isValid) {\\n            this.props.onAdd(this.multiCreateData);\\n            this.props.close();\\n        }\\n    }\\n}\\n", "import { Component, onWillStart, useExternalListener, useState } from \\"@odoo/owl\\";\\nimport { getCurrency, getCurrencyRates } from \\"@web/core/currency\\";\\