Markup\\n    };\\n    static defaultProps = {\\n        dynamicFilters: [],\\n        multiSelect: true,\\n        searchViewId: false,\\n        domain: [],\\n        context: {},\\n    };\\n\\n    setup() {\\n        this.viewService = useService(\\"view\\");\\n        this.dialogService = useService(\\"dialog\\");\\n        this.state = useState({ resIds: [] });\\n        const noContentHelp = this.props.noContentHelp || getDefaultNoContentHelp();\\n        this.busy = false; // flag used to ensure we only call once the onSelected/onUnselect props\\n        this.baseViewProps = {\\n            display: { searchPanel: false },\\n            noBreadcrumbs: true,\\n            noContentHelp,\\n            showButtons: false,\\n            selectRecord: (resId) => this.select([resId]),\\n            onSelectionChanged: (resIds) => {\\n                this.state.resIds = resIds;\\n            },\\n        };\\n    }\\n\\n    get viewProps() {\\n        const type = this.env.isSmall ? \\"kanban\\" : \\"list\\";\\n        const props = {\\n            loadIrFilters: true,\\n            ...this.baseViewProps,\\n            context: this.props.context,\\n            domain: this.props.domain,\\n            dynamicFilters: this.props.dynamicFilters,\\n            readonly: true,\\n            resModel: this.props.resModel,\\n            searchViewId: this.props.searchViewId,\\n            type,\\n        };\\n        if (type === \\"list\\") {\\n            props.allowSelectors = this.props.multiSelect;\\n            props.allowOpenAction = false;\\n        } else if (type === \\"kanban\\") {\\n            props.forceGlobalClick = true;\\n        }\\n        return props;\\n    }\\n\\n    async executeOnceAndClose(callback) {\\n        if (!this.busy) {\\n            this.busy = true;\\n            try {\\n                await callback();\\n            } catch (e) {\\n                this.busy = false;\\n                throw e;\\n            }\\n            this.props.close();\\n        }\\n    }\\n\\n    async select(resIds) {\\n        if (this.props.onSelected) {\\n            this.executeOnceAndClose(() => this.props.onSelected(resIds));\\n        }\\n    }\\n\\n    async unselect() {\\n        if (this.props.onUnselect) {\\n            this.executeOnceAndClose(() => this.props.onUnselect());\\n        }\\n    }\\n\\n    get canUnselect() {\\n        return this.env.isSmall && !!this.props.onUnselect;\\n    }\\n\\n    async createEditRecord() {\\n        if (this.props.onCreateEdit) {\\n            await this.props.onCreateEdit();\\n            this.props.close();\\n        } else {\\n            this.dialogService.add(FormViewDialog, {\\n                context: this.props.context,\\n                resModel: this.props.resModel,\\n                onRecordSaved: (record) => {\\n                    this.props.onSelected([record.resId]);\\n                    this.props.close();\\n                },\\n            });\\n        }\\n    }\\n}\\n\\nregistry.category(\\"dialogs\\").add(\\"select_create\\", SelectCreateDialog);\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { useBus, useService } from \\"@web/core/utils/hooks\\";\\nimport { browser } from \\"@web/core/browser/browser\\";\\nimport { evaluateExpr } from \\"@web/core/py_js/py\\";\\nimport { download } from \\"@web/core/network/download\\";\\nimport { rpc } from \\"@web/core/network/rpc\\";\\nimport { ExportDataDialog } from \\"@web/views/view_dialogs/export_data_dialog\\";\\nimport {\\n    deleteConfirmationMessage,\\n    ConfirmationDialog,\\n} from \\"@web/core/confirmation_dialog/confirmation_dialog\\";\\n\\nimport { useComponent, useEffect } from \\"@odoo/owl\\";\\nimport { DynamicList } from \\"@web/model/relational_model/dynamic_list\\";\\n\\n/**\\n * Allows for a component (usually a View component) to handle links with\\n * attribute type=\\"action\\". This is used to support onboarding banners and content helpers.\\n *\\n * A @web/core/concurrency:KeepLast must be present in the owl environment to allow coordinating\\n * between clicks. (env.keepLast)\\n *\\n * Note that this is similar but quite different from action buttons, since action links\\n * are not dynamic according to the record.\\n * @param {Object} params\\n * @param  {String} params.resModel The default resModel to which actions will apply\\n * @param  {Function} [params.reload] The function to execute to reload, if a button has data-reload-on-close\\n */\\nexport function useActionLinks({ resModel, reload }) {\\n    const component = useComponent();\\n    const keepLast = component.env.keepLast;\\n\\n    const orm = useService(\\"orm\\");\\n    const { doAction } = useService(\\"action\\");\\n\\n    async function handler(ev) {\\n        ev.preventDefault();\\n        ev.stopPropagation();\\n        let target = ev.target;\\n        if (target.tagName !== \\"A\\") {\\n            target = target.closest(\\"a\\");\\n        }\\n        const data = target.dataset;\\n\\n        if (data.method !== undefined && data.model !== undefined) {\\n            const options = {};\\n            if (data.reloadOnClose) {\\n                options.onClose = reload || (() => component.render());\\n            }\\n            const action = await keepLast.add(orm.call(data.model, data.method));\\n            if (action !== undefined) {\\n                keepLast.add(Promise.resolve(doAction(action, options)));\\n            }\\n        } else if (target.getAttribute(\\"name\\")) {\\n            const options = {};\\n            if (data.context) {\\n                options.additionalContext = evaluateExpr(data.context);\\n            }\\n            keepLast.add(doAction(target.getAttribute(\\"name\\"), options));\\n        } else {\\n            let views;\\n            const resId = data.resid ? parseInt(data.resid, 10) : null;\\n            if (data.views) {\\n                views = evaluateExpr(data.views);\\n            } else {\\n                views = resId\\n                    ? [[false, \\"form\\"]]\\n                    : [\\n                          [false, \\"list\\"],\\n                          [false, \\"form\\"],\\n                      ];\\n            }\\n            const action = {\\n                name: target.getAttribute(\\"title\\") || target.textContent.trim(),\\n                type: \\"ir.actions.act_window\\",\\n                res_model: data.model || resModel,\\n                target: \\"current\\",\\n                views,\\n                domain: data.domain ? evaluateExpr(data.domain) : [],\\n            };\\n            if (resId) {\\n                action.res_id = resId;\\n            }\\n\\n            const options = {};\\n            if (data.context) {\\n                options.additionalContext = evaluateExpr(data.context);\\n            }\\n            keepLast.add(doAction(action, options));\\n        }\\n    }\\n\\n    return (ev) => {\\n        const a = ev.target.closest(`a[type=\\"action\\"]`);\\n        if (a && ev.currentTarget.contains(a)) {\\n            handler(ev);\\n        }\\n    };\\n}\\n\\nexport function useBounceButton(containerRef, shouldBounce) {\\n    let timeout;\\n    const ui = useService(\\"ui\\");\\n    useEffect(\\n        (containerEl) => {\\n            if (!containerEl) {\\n                return;\\n            }\\n            const handler = (ev) => {\\n                const button = ui.activeElement.querySelector(\\"[data-bounce-button]\\");\\n                if (button && shouldBounce(ev.target)) {\\n                    button.classList.add(\\"o_catch_attention\\");\\n                    browser.clearTimeout(timeout);\\n                    timeout = browser.setTimeout(() => {\\n                        button.classList.remove(\\"o_catch_attention\\");\\n                    }, 400);\\n                }\\n            };\\n            containerEl.addEventListener(\\"click\\", handler);\\n            return () => containerEl.removeEventListener(\\"click\\", handler);\\n        },\\n        () => [containerRef.el]\\n    );\\n}\\n\\nexport function useExportRecords(env, context, getDefaultExportList) {\\n    const { model, searchModel } = env;\\n    useBus(searchModel, \\"direct-export-data\\", async () => {\\n        _downloadExport(getDefaultExportList(), false, \\"xlsx\\");\\n    });\\n    const _getExportedFields = async (isCompatible, parentParams) => {\\n        const root = model.root;\\n        let domain = parentParams ? [] : root.domain;\\n        if (!root.isDomainSelected && root.selection.length > 0) {\\n            const ids = root.selection.map((e) => e.resId);\\n            domain = [[\\"id\\", \\"in\\", ids]];\\n        }\\n        return await rpc(\\"/web/export/get_fields\\", {\\n            model: root.resModel,\\n            domain,\\n            import_compat: isCompatible,\\n            ...parentParams,\\n        });\\n    };\\n\\n    const _downloadExport = async (fields, import_compat, format) => {\\n        const root = model.root;\\n        const exportedFields = fields.map((field) => ({\\n            name: field.name || field.id,\\n            label: field.label || field.string,\\n            store: field.store,\\n            type: field.field_type || field.type,\\n        }));\\n        if (import_compat) {\\n            exportedFields.unshift({\\n                name: \\"id\\",\\n                label: _t(\\"External ID\\"),\\n            });\\n        }\\n        await download({\\n            data: {\\n                data: JSON.stringify({\\n                    import_compat,\\n                    context: root.context,\\n                    domain: root.domain,\\n                    fields: exportedFields,\\n                    groupby: root.groupBy,\\n                    ids:\\n                        !root.isDomainSelected && root.selection.length > 0\\n                            ? root.selection.map((e) => e.resId)\\n                            : false,\\n                    model: root.resModel,\\n                }),\\n            },\\n            url: `/web/export/${format}`,\\n        });\\n    };\\n\\n    return () => {\\n        const root = model.root;\\n        model.dialog.add(ExportDataDialog, {\\n            context: root.context,\\n            defaultExportList: getDefaultExportList(),\\n            download: _downloadExport,\\n            getExportedFields: _getExportedFields,\\n            root,\\n        });\\n    };\\n}\\n\\nexport function useDeleteRecords(model) {\\n    function getDefaultDialogProps(records) {\\n        const isDynamicList = model.root instanceof DynamicList;\\n        let body = deleteConfirmationMessage;\\n        if (\\n            records?.length > 1 ||\\n            (isDynamicList && (model.root.isDomainSelected || model.root.selection.length > 1))\\n        ) {\\n            body = _t(\\"Are you sure you want to delete these records?\\");\\n        }\\n        let confirm = () => records.forEach((r) => r.delete());\\n        if (isDynamicList) {\\n            confirm = () => model.root.deleteRecords(records);\\n        }\\n        return {\\n            body,\\n            cancel: () => {},\\n            cancelLabel: _t(\\"No, keep it\\"),\\n            confirm,\\n            confirmLabel: _t(\\"Delete\\"),\\n            title: _t(\\"Bye-bye, record!\\"),\\n        };\\n    }\\n    return (dialogProps, records) => {\\n        const defaultProps = getDefaultDialogProps(records);\\n        model.dialog.add(ConfirmationDialog, { ...defaultProps, ...dialogProps });\\n    };\\n}\\n", "import { rpcBus } from \\"@web/core/network/rpc\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { UPDATE_METHODS } from \\"@web/core/orm_service\\";\\n\\n/**\\n * @typedef {Object} IrFilter\\n * @property {[number, string] | false} user_id\\n * @property {string} sort\\n * @property {string} context\\n * @property {string} name\\n * @property {string} domain\\n * @property {number} id\\n * @property {boolean} is_default\\n * @property {string} model_id\\n * @property {[number, string] | false} action_id\\n * @property {number | false} embedded_action_id\\n * @property {number | false} embedded_parent_res_id\\n */\\n\\n/**\\n * @typedef {Object} ViewDescription\\n * @property {string} arch\\n * @property {number|false} id\\n * @property {number|null} [custom_view_id]\\n * @property {Object} [actionMenus] // for views other than search\\n * @property {IrFilter[]} [irFilters] // for search view\\n */\\n\\n/**\\n * @typedef {Object} LoadViewsParams\\n * @property {string} resModel\\n * @property {[number, string][]} views\\n * @property {Object} context\\n */\\n\\n/**\\n * @typedef {Object} LoadViewsOptions\\n * @property {number|false} actionId\\n * @property {boolean} loadActionMenus\\n * @property {boolean} loadIrFilters\\n */\\n\\nexport const viewService = {\\n    dependencies: [\\"orm\\"],\\n    async: [\\"loadViews\\"],\\n    start(env, { orm }) {\\n        rpcBus.addEventListener(\\"RPC:RESPONSE\\", (ev) => {\\n            const { model, method } = ev.detail.data.params;\\n            if ([\\"ir.ui.view\\", \\"ir.filters\\"].includes(model)) {\\n                if (UPDATE_METHODS.includes(method)) {\\n                    rpcBus.trigger(\\"CLEAR-CACHES\\", \\"get_views\\");\\n                }\\n            }\\n        });\\n\\n        /**\\n         * Loads various information concerning views: fields_view for each view,\\n         * fields of the corresponding model, and optionally the filters.\\n         *\\n         * @param {LoadViewsParams} params\\n         * @param {LoadViewsOptions} [options={}]\\n         * @returns {Promise<ViewDescriptions>}\\n         */\\n        async function loadViews(params, options = {}) {\\n            const { context, resModel, views } = params;\\n            const loadViewsOptions = {\\n                action_id: options.actionId || false,\\n                embedded_action_id: options.embeddedActionId || false,\\n                embedded_parent_res_id: options.embeddedParentResId || false,\\n                load_filters: options.loadIrFilters || false,\\n                toolbar: (!context?.disable_toolbar && options.loadActionMenus) || false,\\n            };\\n            for (const key in options) {\\n                if (\\n                    ![\\n                        \\"actionId\\",\\n                        \\"embeddedActionId\\",\\n                        \\"embeddedParentResId\\",\\n                        \\"loadIrFilters\\",\\n                        \\"loadActionMenus\\",\\n                    ].includes(key)\\n                ) {\\n                    loadViewsOptions[key] = options[key];\\n                }\\n            }\\n            if (env.isSmall) {\\n                loadViewsOptions.mobile = true;\\n            }\\n            if (env.debug) {\\n                loadViewsOptions.debug = true;\\n            }\\n            const filteredContext = Object.fromEntries(\\n                Object.entries(context || {}).filter(\\n                    ([k, v]) => k == \\"lang\\" || k.endsWith(\\"_view_ref\\")\\n                )\\n            );\\n\\n            const result = await orm.cache({ type: \\"disk\\" }).call(resModel, \\"get_views\\", [], {\\n                context: filteredContext,\\n                views,\\n                options: loadViewsOptions,\\n            });\\n            const viewDescriptions = {\\n                fields: result.models[resModel].fields,\\n                relatedModels: result.models,\\n                views: {},\\n            };\\n            for (const viewType in result.views) {\\n                const { arch, toolbar, id, filters, custom_view_id } = result.views[viewType];\\n                const viewDescription = { arch, id, custom_view_id };\\n                if (toolbar) {\\n                    viewDescription.actionMenus = toolbar;\\n                }\\n                if (filters) {\\n                    viewDescription.irFilters = filters;\\n                }\\n                viewDescriptions.views[viewType] = viewDescription;\\n            }\\n            return viewDescriptions;\\n        }\\n        return { loadViews };\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"view\\", viewService);\\n", "import { FileInput } from \\"@web/core/file_input/file_input\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { checkFileSize } from \\"@web/core/utils/files\\";\\nimport { standardWidgetProps } from \\"@web/views/widgets/standard_widget_props\\";\\nimport { Component } from \\"@odoo/owl\\";\\n\\nexport class AttachDocumentWidget extends Component {\\n    static template = \\"web.AttachDocument\\";\\n    static components = {\\n        FileInput,\\n    };\\n    static props = {\\n        ...standardWidgetProps,\\n        string: { type: String },\\n        action: { type: String, optional: true },\\n        highlight: { type: Boolean },\\n    };\\n\\n    setup() {\\n        this.http = useService(\\"http\\");\\n        this.notification = useService(\\"notification\\");\\n        this.fileInput = document.createElement(\\"input\\");\\n        this.fileInput.type = \\"file\\";\\n        this.fileInput.accept = \\"*\\";\\n        this.fileInput.multiple = true;\\n        this.fileInput.onchange = this.onInputChange.bind(this);\\n    }\\n\\n    async onInputChange() {\\n        const ufile = [...this.fileInput.files];\\n        for (const file of ufile) {\\n            if (!checkFileSize(file.size, this.notification)) {\\n                return null;\\n            }\\n        }\\n        const fileData = await this.http.post(\\n            \\"/web/binary/upload_attachment\\",\\n            {\\n                csrf_token: odoo.csrf_token,\\n                ufile: ufile,\\n                model: this.props.record.resModel,\\n                id: this.props.record.resId,\\n            },\\n            \\"text\\"\\n        );\\n        const parsedFileData = JSON.parse(fileData);\\n        if (parsedFileData.error) {\\n            throw new Error(parsedFileData.error);\\n        }\\n        await this.onFileUploaded(parsedFileData);\\n    }\\n\\n    async triggerUpload() {\\n        if (await this.beforeOpen()) {\\n            this.fileInput.click();\\n        }\\n    }\\n\\n    async onFileUploaded(files) {\\n        const { action, record } = this.props;\\n        if (action) {\\n            const { resId, resModel } = record;\\n            await this.env.services.orm.call(resModel, action, [resId], {\\n                attachment_ids: files.map((file) => file.id),\\n            });\\n            await record.load();\\n        }\\n    }\\n\\n    beforeOpen() {\\n        return this.props.record.save();\\n    }\\n}\\n\\nexport const attachDocumentWidget = {\\n    component: AttachDocumentWidget,\\n    extractProps: ({ attrs }) => {\\n        const { action, highlight, string } = attrs;\\n        return {\\n            action,\\n            highlight: !!highlight,\\n            string,\\n        };\\n    },\\n};\\n\\nregistry.category(\\"view_widgets\\").add(\\"attach_document\\", attachDocumentWidget);\\n", "import { session } from \\"@web/session\\";\\nimport { standardWidgetProps } from \\"@web/views/widgets/standard_widget_props\\";\\nimport { Component } from \\"@odoo/owl\\";\\nimport { registry } from \\"@web/core/registry\\";\\n\\nconst LINK_REGEX = new RegExp(\\"^https?://\\");\\n\\nexport class DocumentationLink extends Component {\\n    static template = \\"web.DocumentationLink\\";\\n    static props = {\\n        ...standardWidgetProps,\\n        record: { type: Object, optional: 1 }, // The record is not needed in this widget\\n        path: { type: String },\\n        label: { type: String, optional: 1 },\\n        icon: { type: String, optional: 1 },\\n        alertLink: { type: Boolean, optional: 1 },\\n    };\\n\\n    get url() {\\n        if