up;\\n    }\\n\\n    get isSet() {\\n        return !!this.props.record.data[this.props.name];\\n    }\\n\\n    get type() {\\n        return this.props.record.fields[this.props.name].type;\\n    }\\n\\n    findGroupId(predicate) {\\n        if (this.type === \\"selection\\") {\\n            const options = this.props.record.fields[this.props.name].selection;\\n            const option = options.findLast((o) => o[0] && predicate(o[0]));\\n            return option ? option[0] : false;\\n        } else {\\n            const groupId = this.env.resUserGroupsInfo.booleanFieldToGroupId[this.props.name];\\n            return predicate(groupId) ? groupId : false;\\n        }\\n    }\\n\\n    onClickInfoButton(ev) {\\n        if (this.popover.isOpen) {\\n            this.popover.close();\\n        } else {\\n            this.popover.open(ev.currentTarget, {\\n                groupId: this.group ? this.group.id : this.impliedGroup.id,\\n                groups: this.env.resUserGroupsInfo.groups,\\n                privileges: this.env.resUserGroupsInfo.privileges,\\n            });\\n        }\\n    }\\n}\\n\\nconst resUserGroupIdsPrivilegeField = {\\n    component: ResUserGroupIdsPrivilegeField,\\n};\\n\\nregistry.category(\\"fields\\").add(\\"res_user_group_ids_privilege\\", resUserGroupIdsPrivilegeField);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { deepCopy } from \\"@web/core/utils/objects\\";\\n\\nexport const lazySession = {\\n    dependencies: [\\"orm\\"],\\n    start(env, { orm }) {\\n        let resolveWebClientReady;\\n        let lazyConfigPromise;\\n        const fetchServerData = async () => {\\n            await webClientReadyPromise;\\n            return orm.call(\\"ir.http\\", \\"lazy_session_info\\");\\n        };\\n        const webClientReadyPromise = new Promise((r) => (resolveWebClientReady = r));\\n        env.bus.addEventListener(\\"WEB_CLIENT_READY\\", resolveWebClientReady, { once: true });\\n        return {\\n            getValue(key, callback) {\\n                if (!lazyConfigPromise) {\\n                    lazyConfigPromise = fetchServerData();\\n                }\\n                lazyConfigPromise.then((config) => callback(deepCopy(config)[key]));\\n            },\\n        };\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"lazy_session\\", lazySession);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { BinaryField, binaryField } from \\"@web/views/fields/binary/binary_field\\";\\n\\nexport class SettingsBinaryField extends BinaryField {\\n    static template = \\"web.SettingsBinaryField\\";\\n\\n    getDownloadData() {\\n        const related = this.props.record.fields[this.props.name].related;\\n        const [fieldName, relatedFieldName] = related.split(\\".\\");\\n        return {\\n            ...super.getDownloadData(),\\n            model: this.props.record.fields[fieldName].relation,\\n            field: relatedFieldName ?? fieldName,\\n            id: this.props.record.data[fieldName].id,\\n        }\\n    }\\n\\n}\\n\\nconst settingsBinaryField = {\\n    ...binaryField,\\n    component: SettingsBinaryField,\\n};\\n\\nregistry.category(\\"fields\\").add(\\"base_settings.binary\\", settingsBinaryField);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { booleanField, BooleanField } from \\"@web/views/fields/boolean/boolean_field\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { UpgradeDialog } from \\"./upgrade_dialog\\";\\n\\n/**\\n *  The upgrade boolean field is intended to be used in config settings.\\n *  When checked, an upgrade popup is showed to the user.\\n */\\n\\nexport class UpgradeBooleanField extends BooleanField {\\n    setup() {\\n        super.setup();\\n        this.dialogService = useService(\\"dialog\\");\\n        this.isEnterprise = odoo.info && odoo.info.isEnterprise;\\n    }\\n\\n    async onChange(newValue) {\\n        if (!this.isEnterprise) {\\n            this.dialogService.ad