},\\n    Model: SettingModel,\\n    ControlPanel: ControlPanel,\\n    Controller: SettingsFormController,\\n    Compiler: SettingsFormCompiler,\\n    Renderer: SettingsFormRenderer,\\n    props: (genericProps, view) => {\\n        [...genericProps.arch.querySelectorAll(\\"setting[type='header'] field\\")].forEach((el) => {\\n            const options = evaluateExpr(el.getAttribute(\\"options\\") || \\"{}\\");\\n            options.isHeaderField = true;\\n            el.setAttribute(\\"options\\", JSON.stringify(options));\\n        });\\n        return formView.props(genericProps, view);\\n    },\\n};\\n\\nregistry.category(\\"views\\").add(\\"base_settings\\", settingsFormView);\\n", "import { rpc } from \\"@web/core/network/rpc\\";\\nimport { registry } from \\"@web/core/registry\\";\\n\\nexport const demoDataService = {\\n    async start() {\\n        let isDemoDataActiveProm;\\n        return {\\n            isDemoDataActive() {\\n                if (!isDemoDataActiveProm) {\\n                    isDemoDataActiveProm = rpc(\\"/base_setup/demo_active\\");\\n                }\\n                return isDemoDataActiveProm;\\n            },\\n        };\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"demo_data\\", demoDataService);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\nimport { SettingsBlock } from \\"../settings/settings_block\\";\\nimport { Setting } from \\"../../../views/form/setting/setting\\";\\n\\nimport { Component, onWillStart } from \\"@odoo/owl\\";\\nimport { standardWidgetProps } from \\"@web/views/widgets/standard_widget_props\\";\\nimport { router } from \\"@web/core/browser/router\\";\\n\\n/**\\n * Widget in the settings that handles the \\"Developer Tools\\" section.\\n * Can be used to enable/disable the debug modes.\\n * Can be used to load the demo data.\\n */\\nexport class ResConfigDevTool extends Component {\\n    static template = \\"res_config_dev_tool\\";\\n    static components = {\\n        SettingsBlock,\\n        Setting,\\n    };\\n    static props = {\\n        ...standardWidgetProps,\\n    };\\n\\n    setup() {\\n        this.isDebug = Boolean(odoo.debug);\\n        this.isAssets = odoo.debug.includes(\\"assets\\");\\n        this.isTests = odoo.debug.includes(\\"tests\\");\\n\\n        this.action = useService(\\"action\\");\\n        this.demo = useService(\\"demo_data\\");\\n\\n        onWillStart(async () => {\\n            this.isDemoDataActive = await this.demo.isDemoDataActive();\\n        });\\n    }\\n\\n    activateDebug(value) {\\n        router.pushState({ debug: value }, { reload: true });\\n    }\\n\\n    /**\\n     * Forces demo data to be installed in a database without demo data installed.\\n     */\\n    onClickForceDemo() {\\n        this.action.doAction(\\"base.demo_force_install_action\\");\\n    }\\n}\\n\\nexport const resConfigDevTool = {\\n    component: ResConfigDevTool,\\n};\\n\\nregistry.category(\\"view_widgets\\").add(\\"res_config_dev_tool\\", resConfigDevTool);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { session } from \\"@web/session\\";\\nimport { Setting } from \\"@web/views/form/setting/setting\\";\\n\\nimport { Component } from \\"@odoo/owl\\";\\nimport { standardWidgetProps } from \\"@web/views/widgets/standard_widget_props\\";\\nconst { DateTime } = luxon;\\n\\n/**\\n * Widget in the settings that handles a part of the \\"About\\" section.\\n * Contains info about the odoo version, database expiration date and copyrights.\\n */\\nclass ResConfigEdition extends Component {\\n    static template = \\"res_config_edition\\";\\n    static components = { Setting };\\n    static props = {\\n        ...standardWidgetProps,\\n    };\\n\\n    setup() {\\n        this.serverVersion = session.server_version;\\n        this.expirationDate = session.expiration_date\\n            ? DateTime.fromSQL(session.expiration_date).toLocaleString(DateTime.DATE_FULL)\\n            : DateTime.now().plus({ days: 30 }).toLocaleString(DateTime.DATE_FULL);\\n    }\\n}\\n\\nexport const resConfigEdition = {\\n    component: ResConfigEdition,\\n};\\n\\nregistry.category(\\"view_widgets\\").add(\\"res_config_edition\\", resConfigEdition);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { unique } from \\"@web/core/utils/arrays\\";\\nimport { useService } from \\"@web/core/utils/hooks\\";\\n\\nimport { Component, useState, onWillStart } from \\"@odoo/owl\\";\\nimport { standardWidgetProps } from \\"@web/views/widgets/standard_widget_props\\";\\n\\nclass ResConfigInviteUsers extends Component {\\n    static template = \\"res_config_invite_users\\";\\n    static props = {\\n        ...standardWidgetProps,\\n    };\\n\\n    setup() {\\n        this.orm = useService(\\"orm\\");\\n        this.invite = useService(\\"user_invite\\");\\n        this.action = useService(\\"action\\");\\n        this.notification = useService(\\"notification\\");\\n\\n        this.state = useState({\\n            status: \\"idle\\", // idle, inviting\\n            emails: \\"\\",\\n            invite: null,\\n        });\\n\\n        onWillStart(async () => {\\n            this.state.invite = await this.invite.fetchData();\\n        });\\n    }\\n\\n    /**\\n     * @param {string} email\\n     * @returns {boolean} true if the given email address is valid\\n     */\\n    validateEmail(email) {\\n        const re =\\n            /^([a-z0-9][-a-z0-9_+.]*)@((?:[\\\\w-]+\\\\.)*\\\\w[\\\\w-]{0,66})\\\\.([a-z]{2,63}(?:\\\\.[a-z]{2})?)$/i;\\n        return re.test(email);\\n    }\\n\\n    get emails() {\\n        return unique(\\n            this.state.emails\\n                .split(/[ ,;\\\\n]+/)\\n                .map((email) => email.trim())\\n                .filter((email) => email.length)\\n        );\\n    }\\n\\n    validate() {\\n        if (!this.emails.length) {\\n            throw new Error(_t(\\"Empty email address\\"));\\n        }\\n        const invalidEmails = [];\\n        for (const email of this.emails) {\\n            if (!this.validateEmail(email)) {\\n                invalidEmails.push(email);\\n            }\\n        }\\n        if (invalidEmails.length) {\\n            const errorMessage = (() => {\\n                switch (invalidEmails.length) {\\n                    case 1:\\n                        return _t(\\"Invalid email address: %(address)s\\", {\\n                            address: invalidEmails[0],\\n                        });\\n                    case 2:\\n                        return _t(\\"Invalid email addresses: %(two_addresses)s\\", {\\n                            two_addresses: invalidEmails,\\n                        });\\n                    default:\\n                        return _t(\\"Invalid email addresses: %(addresses)s\\", {\\n                            addresses: invalidEmails,\\n                        });\\n                }\\n            })();\\n            throw new Error(errorMessage);\\n        }\\n    }\\n\\n    get inviteButtonText() {\\n        if (this.state.status === \\"inviting\\") {\\n            return _t(\\"Inviting...\\");\\n        }\\n        return _t(\\"Invite\\");\\n    }\\n\\n    onClickMore(ev) {\\n        this.action.doAction(this.state.invite.action_pending_users);\\n    }\\n\\n    onClickUser(ev, user) {\\n        const action = Object.assign({}, this.state.invite.action_pending_users, {\\n            res_id: user[0],\\n        });\\n        this.action.doAction(action);\\n    }\\n\\n    onKeydownUserEmails(ev) {\\n        const keys = [\\"Enter\\", \\"Tab\\", \\",\\"];\\n        if (keys.includes(ev.key)) {\\n            if (ev.key === \\"Tab\\" && !this.emails.length) {\\n                return;\\n            }\\n            ev.preventDefault();\\n            this.sendInvite();\\n        }\\n    }\\n\\n    /**\\n     * Send invitation for valid and unique email addresses\\n     *\\n     * @private\\n     */\\n    async sendInvite() {\\n        try {\\n            this.validate();\\n        } catch (e) {\\n            this.notification.add(e.message, { type: \\"danger\\" });\\n            return;\\n        }\\n\\n        this.state.status = \\"inviting\\";\\n\\n        const pendingUserEmails = this.state.invite.pending_users.map((user) => user[1]);\\n        const emailsLeftToProcess = this.emails.filter(\\n            (email) => !pendingUserEmails.includes(email)\\n        );\\n\\n        try {\\n            if (emailsLeftToProcess) {\\n                await this.orm.call(\\"res.users\\", \\"web_create_users\\", [emailsLeftToProcess]);\\n                this.state.invite = await this.invite.fetchData(true);\\n            }\\n        } finally {\\n            this.state.emails = \\"\\";\\n            this.state.status = \\"idle\\";\\n        }\\n    }\\n}\\n\\nexport const resConfigInviteUsers = {\\n    component: ResConfigInviteUsers,\\n};\\n\\nregistry.category(\\"view_widgets\\").add(\\"res_config_invite_users\\", resConfigInviteUsers);\\n", "import { rpc } from \\"@web/core/network/rpc\\";\\nimport { registry } from \\"@web/core/registry\\";\\n\\nexport const userInviteService = {\\n    async start() {\\n        let dataProm;\\n        return {\\n            fetchData(reload = false) {\\n                if (!dataProm || reload) {\\n                    dataProm = rpc(\\"/base_setup/data\\");\\n                }\\n                return dataProm;\\n            },\\n        };\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"user_invite\\", userInviteService);\\n", "import { registry } from \\"@web/core/registry\\";\\nimport { browser } from \\"@web/core/browser/browser\\";\\n\\n/**\\n * @return {Promise<{\\n *     title:string,\\n *     text:string,\\n *     url:string,\\n *     externalMediaFiles:File[]\\n * }>}\\n */\\nconst getShareTargetDataFromServiceWorker = () => {\\n    return new Promise((resolve) => {\\n        const onmessage = (event) => {\\n            if (event.data.action === \\"odoo_share_target_ack\\") {\\n                resolve(event.data.shared_files);\\n                browser.navigator.serviceWorker.removeEventListener(\\"message\\", onmessage);\\n            }\\n        };\\n        browser.navigator.serviceWorker.addEventListener(\\"message\\", onmessage);\\n        browser.navigator.serviceWorker.controller.postMessage(\\"odoo_share_target\\");\\n    });\\n};\\n\\nexport const shareTargetService = {\\n    dependencies: [\\"menu\\"],\\n    start(env, { menu }) {\\n        let sharedFiles = null;\\n        if (\\n            browser.navigator.serviceWorker &&\\n            new URL(browser.location).searchParams.get(\\"share_target\\") === \\"trigger\\"\\n        ) {\\n            const app = menu.getApps().find((app) => \\"expenses\\" === app.actionPath);\\n            if (app) {\\n                const clientReadyListener = async () => {\\n                    sharedFiles = await getShareTargetDataFromServiceWorker();\\n                    if (sharedFiles?.length) {\\n                        await menu.selectMenu(app);\\n                    }\\n                    env.bus.removeEventListener(\\"WEB_CLIENT_READY\\", clientReadyListener);\\n                };\\n                env.bus.addEventListener(\\"WEB_CLIENT_READY\\", clientReadyListener);\\n            }\\n        }\\n        return {\\n            /**\\n             * Return true if we receive share target files from service worker\\n             * @return {boolean}\\n             */\\n            hasSharedFiles: () => !!sharedFiles?.length,\\n            /**\\n             * Return the shared files retrieve for upload\\n             * @return {null|File[]}\\n             */\\n            getSharedFilesToUpload: () => {\\n                const files = sharedFiles;\\n                sharedFiles = null;\\n                return files;\\n            },\\n        };\\n    },\\n};\\n\\nregistry.category(\\"services\\").add(\\"shareTarget\\", shareTargetService);\\n", "import { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { Component, useState } from \\"@odoo/owl\\";\\nimport { user } from \\"@web/core/user\\";\\n\\nexport class SwitchCompanyItem extends Component {\\n    static template = \\"web.SwitchCompanyItem\\";\\n    static components = { DropdownItem, SwitchCompanyItem };\\n    static props = {\\n        company: {},\\n        level: { type: Number },\\n    };\\n\\n    setup() {\\n        this.companySelector = useState(this.env.companySelector);\\n    }\\n\\n    get isCompanySelected() {\\n        return this.companySelector.isCompanySelected(this.props.company.id);\\n    }\\n\\n    get isCompanyAllowed() {\\n        return user.allowedCompanies.map((c) => c.id).includes(this.props.company.id);\\n    }\\n\\n    get isCurrent() {\\n        return this.props.company.id === user.activeCompany.id;\\n    }\\n\\n    logIntoCompany() {\\n        if (this.isCompanyAllowed) {\\n            this.companySelector.switchCompany(\\"loginto\\", this.props.company.id);\\n        }\\n    }\\n\\n    toggleCompany() {\\n        if (this.isCompanyAllowed) {\\n            this.companySelector.switchCompany(\\"toggle\\", this.props.company.id);\\n        }\\n    }\\n}\\n", "import { Dropdown } from \\"@web/core/dropdown/dropdown\\";\\nimport { DropdownGroup } from \\"@web/core/dropdown/dropdown_group\\";\\nimport { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { registry } from \\"@web/core/registry\\";\\n\\nimport { Component, useChildSubEnv, useRef, useState } from \\"@odoo/owl\\";\\nimport { useCommand } from \\"@web/core/commands/command_hook\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { symmetricalDifference } from \\"@web/core/utils/arrays\\";\\nimport { useBus, useChildRef, useService } from \\"@web/core/utils/hooks\\";\\nimport { SwitchCompanyItem } from \\"@web/webclient/switch_company_menu/switch_company_item\\";\\nimport { useHotkey } from \\"@web/core/hotkeys/hotkey_hook\\";\\nimport { useDropdownState } from \\"@web/core/dropdown/dropdown_hooks\\";\\nimport { user, userBus } from \\"@web/core/user\\";\\nimport { router } from \\"@web/core/browser/router\\";\\n\\nfunction getCompany(cid) {\\n    return user.allowedCompaniesWithAncestors.find((c) => c.id === cid);\\n}\\n\\nexport class CompanySelector {\\n    constructor(actionService, dropdownState) {\\n        this.actionService = actionService;\\n        this.dropdownState = dropdownState;\\n        this.selectedCompaniesIds = user.activeCompanies.map((c) => c.id);\\n    }\\n\\n    get hasSelectionChanged() {\\n        return (\\n            symmetricalDifference(\\n                this.selectedCompaniesIds,\\n                user.activeCompanies.map((c) => c.id)\\n            ).length > 0\\n        );\\n    }\\n\\n    isCompanySelected(companyId) {\\n        return this.selectedCompaniesIds.includes(companyId);\\n    }\\n\\n    switchCompany(mode, companyId) {\\n        if (mode === \\"toggle\\") {\\n            if (this.selectedCompaniesIds.includes(companyId)) {\\n                this._deselectCompany(companyId);\\n            } else {\\n                this._selectCompany(companyId);\\n            }\\n        } else if (mode === \\"loginto\\") {\\n            if (this._isSingleCompanyMode()) {\\n                this.selectedCompaniesIds.splice(0, this.selectedCompaniesIds.length);\\n            }\\n            this._selectCompany(companyId, true);\\n            this.apply();\\n\\n            this.dropdownState.close?.();\\n        }\\n    }\\n\\n    async apply() {\\n        user.activateCompanies(this.selectedCompaniesIds, {\\n            includeChildCompanies: false,\\n            reload: false,\\n        });\\n\\n        const controller = this.actionService.currentController;\\n        const state = {};\\n        const options = { reload: true };\\n        if (controller?.props.resId && controller?.props.resModel) {\\n            const hasReadRights = await user.checkAccessRight(\\n                controller.props.resModel,\\n                \\"read\\",\\n                controller.props.resId\\n            );\\n\\n            if (!hasReadRights) {\\n                options.replace = true;\\n                state.actionStack = router.current.actionStack.slice(0, -1);\\n            }\\n        }\\n\\n        router.pushState(state, options);\\n    }\\n\\n    reset() {\\n        this.selectedCompaniesIds = user.activeCompanies.map((c) => c.id);\\n    }\\n\\n    selectAll(companyIds) {\\n        let shouldSelectAll = true;\\n\\n        // If any company is selected, just unselect all\\n        for (let i = this.selectedCompaniesIds.length - 1; i >= 0; i--) {\\n            if (companyIds.includes(this.selectedCompaniesIds[i])) {\\n                this.selectedCompaniesIds.splice(i, 1);\\n                shouldSelectAll = false;\\n            }\\n        }\\n\\n        // If no company is selected, select all\\n        if (shouldSelectAll) {\\n            for (const companyId of companyIds) {\\n                if (!this.selectedCompaniesIds.includes(companyId)) {\\n                    this.selectedCompaniesIds.push(companyId);\\n                }\\n            }\\n        }\\n    }\\n\\n    _selectCompany(companyId, unshift = false) {\\n        if (this._isCompanyAllowed(companyId)) {\\n            if (!this.selectedCompaniesIds.includes(companyId)) {\\n                if (unshift) {\\n                    this.selectedCompaniesIds.unshift(companyId);\\n                } else {\\n                    this.selectedCompaniesIds.push(companyId);\\n                }\\n            } else if (unshift) {\\n                const index = this.selectedCompaniesIds.findIndex((c) => c === companyId);\\n                this.selectedCompaniesIds.splice(index, 1);\\n                this.selectedCompaniesIds.unshift(companyId);\\n            }\\n        }\\n\\n        this._getBranches(companyId).forEach((companyId) => this._selectCompany(companyId));\\n    }\\n\\n    _deselectCompany(companyId) {\\n        if (this.selectedCompaniesIds.includes(companyId)) {\\n            this.selectedCompaniesIds.splice(this.selectedCompaniesIds.indexOf(companyId), 1);\\n        }\\n        this._getBranches(companyId).forEach((companyId) => this._deselectCompany(companyId));\\n    }\\n\\n    _getBranches(companyId) {\\n        return getCompany(companyId).child_ids || [];\\n    }\\n    \\n    _isCompanyAllowed(companyId) {\\n        return user.allowedCompanies.some((c) => c.id == companyId);\\n    }\\n\\n    _isSingleCompanyMode() {\\n        if (this.selectedCompaniesIds.length === 1) {\\n            return true;\\n        }\\n\\n        const getActiveCompany = (companyId) => {\\n            const isActive = this.selectedCompaniesIds.includes(companyId);\\n            return isActive ? getCompany(companyId) : null;\\n        };\\n\\n        let rootCompany = undefined;\\n        for (const companyId of this.selectedCompaniesIds) {\\n            let company = getActiveCompany(companyId);\\n\\n            // Find the root active parent of the company\\n            while (getActiveCompany(company.parent_id)) {\\n                company = getActiveCompany(company.parent_id);\\n            }\\n\\n            if (rootCompany === undefined) {\\n                rootCompany = company;\\n            } else if (rootCompany !== company) {\\n                return false;\\n            }\\n        }\\n\\n        // If some children or sub-children of the root company\\n        // are not active, we are in multi-company mode.\\n        if (rootCompany && rootCompany.child_ids) {\\n            const queue = [...rootCompany.child_ids];\\n            while (queue.length > 0) {\\n                const company = getActiveCompany(queue.pop());\\n                if (company && company.child_ids) {\\n                    queue.push(...company.child_ids);\\n                } else if (!company) {\\n                    return false;\\n                }\\n            }\\n        }\\n\\n        return true;\\n    }\\n}\\n\\nexport class SwitchCompanyMenu extends Component {\\n    static template = \\"web.SwitchCompanyMenu\\";\\n    static components = { Dropdown, DropdownItem, DropdownGroup, SwitchCompanyItem };\\n    static props = {};\\n    static CompanySelector = CompanySelector;\\n\\n    setup() {\\n        this.dropdown = useDropdownState();\\n        this.user = user;\\n        const actionService = useService(\\"action\\");\\n\\n        this.companySelector = useState(\\n            new this.constructor.CompanySelector(actionService, this.dropdown)\\n        );\\n        useChildSubEnv({ companySelector: this.companySelector });\\n\\n        this.searchInputRef = useRef(\\"inputRef\\");\\n        this.state = useState({});\\n        this.resetState();\\n\\n        useHotkey(\\"control+enter\\", () => this.confirm(), {\\n            bypassEditableProtection: true,\\n            isAvailable: () => this.companySelector.hasSelectionChanged,\\n        });\\n\\n        useCommand(_t(\\"Switch Company\\"), () => this.dropdown.open(), { hotkey: \\"alt+shift+u\\" });\\n        useBus(userBus, \\"ACTIVE_COMPANIES_CHANGED\\", () => {\\n            this.companySelector.reset();\\n        });\\n\\n        this.containerRef = useChildRef();\\n        this.navigationOptions = {\\n            hotkeys: {\\n                space: (navigator) => {\\n                    const navItem = navigator.activeItem;\\n                    if (!navItem) {\\n                        return;\\n                    }\\n                    if (navItem.el.classList.contains(\\"o_switch_company_item\\")) {\\n                        const companyId = parseInt(navItem.el.dataset.companyId);\\n                        this.companySelector.switchCompany(\\"toggle\\", companyId);\\n                    }\\n                },\\n                enter: (navigator) => {\\n                    const navItem = navigator.activeItem;\\n                    if (!navItem) {\\n                        return;\\n                    }\\n                    if (navItem.el.classList.contains(\\"o_switch_company_item\\")) {\\n                        const companyId = parseInt(navItem.el.dataset.companyId);\\n                        this.companySelector.switchCompany(\\"loginto\\", companyId);\\n                        this.dropdown.close();\\n                    } else {\\n                        navItem.select();\\n                    }\\n                },\\n            },\\n        };\\n    }\\n\\n    get hasLotsOfCompanies() {\\n        return user.allowedCompaniesWithAncestors.length > 9;\\n    }\\n\\n    get visibleCompanies() {\\n        return this.state.visibleCompanies;\\n    }\\n\\n    get hasSelectedCompanies() {\\n        return this.visibleCompanies.some((c) =>\\n            this.companySelector.isCompanySelected(c.company.id)\\n        );\\n    }\\n\\n    get selectAllClass() {\\n        if (\\n            this.visibleCompanies.every((c) => this.companySelector.isCompanySelected(c.company.id))\\n        ) {\\n            return \\"btn-link text-primary\\";\\n        } else {\\n            return \\"btn-link text-secondary\\";\\n        }\\n    }\\n\\n    get selectAllIcon() {\\n        if (\\n            this.visibleCompanies.every((c) => this.companySelector.isCompanySelected(c.company.id))\\n        ) {\\n            return \\"fa-check-square text-primary\\";\\n        } else if (\\n            this.visibleCompanies.some((c) => this.companySelector.isCompanySelected(c.company.id))\\n        ) {\\n            return \\"fa-minus-square-o\\";\\n        } else {\\n            return \\"fa-square-o\\";\\n        }\\n    }\\n\\n    computeVisibleCompanies() {\\n        const companies = [];\\n\\n        const addCompany = (company, level = 0) => {\\n            if (this.matchSearch(company.name)) {\\n                companies.push({ company, level });\\n            }\\n\\n            if (company.child_ids) {\\n                for (const companyId of company.child_ids) {\\n                    addCompany(getCompany(companyId), level + 1);\\n                }\\n            }\\n        };\\n\\n        user.allowedCompaniesWithAncestors\\n            .filter((c) => !c.parent_id)\\n            .sort((c1, c2) => c1.sequence - c2.sequence)\\n            .forEach((c) => addCompany(c));\\n\\n        return companies;\\n    }\\n\\n    resetState() {\\n        this.state.searchFilter = \\"\\";\\n        this.state.showFilter = this.hasLotsOfCompanies;\\n        this.state.visibleCompanies = this.computeVisibleCompanies();\\n    }\\n\\n    onSearch(ev) {\\n        this.state.searchFilter = ev.target.value;\\n        this.state.showFilter = true;\\n        this.state.visibleCompanies = this.computeVisibleCompanies();\\n    }\\n\\n    matchSearch(companyName) {\\n        if (!this.state.searchFilter) {\\n            return true;\\n        }\\n\\n        const name = companyName.toLocaleLowerCase().replace(/\\\\s/g, \\"\\");\\n        const filter = this.state.searchFilter.toLocaleLowerCase().replace(/\\\\s/g, \\"\\");\\n        return name.includes(filter);\\n    }\\n\\n    handleDropdownChange(isOpen) {\\n        if (isOpen) {\\n            if (this.searchInputRef.el) {\\n                this.searchInputRef.el.focus();\\n            }\\n\\n            if (this.containerRef.el) {\\n                // Fixes the container width so it doesn't change when searching.\\n                const currentWidth = this.containerRef.el.getBoundingClientRect().width;\\n                this.containerRef.el.style.width = currentWidth + \\"px\\";\\n            }\\n        } else {\\n            this.resetState();\\n        }\\n    }\\n\\n    confirm() {\\n        this.dropdown.close();\\n        this.companySelector.apply();\\n    }\\n\\n    selectAll() {\\n        const companyIds = this.visibleCompanies.map((entry) => entry.company.id);\\n        this.companySelector.selectAll(companyIds);\\n    }\\n\\n    get isSingleCompany() {\\n        return user.allowedCompaniesWithAncestors.length === 1;\\n    }\\n}\\n\\nexport const systrayItem = {\\n    Component: SwitchCompanyMenu,\\n};\\n\\nregistry.category(\\"systray\\").add(\\"SwitchCompanyMenu\\", systrayItem, { sequence: 1 });\\n", "import { Dropdown } from \\"@web/core/dropdown/dropdown\\";\\nimport { DropdownGroup } from \\"@web/core/dropdown/dropdown_group\\";\\nimport { DropdownItem } from \\"@web/core/dropdown/dropdown_item\\";\\nimport { CheckBox } from \\"@web/core/checkbox/checkbox\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { user } from \\"@web/core/user\\";\\nimport { session } from \\"@web/session\\";\\n\\nimport { Component } from \\"@odoo/owl\\";\\nimport { imageUrl } from \\"@web/core/utils/urls\\";\\n\\nconst userMenuRegistry = registry.category(\\"user_menuitems\\");\\n\\nexport class UserMenu extends Component {\\n    static template = \\"web.UserMenu\\";\\n    static components = { DropdownGroup, Dropdown, DropdownItem, CheckBox };\\n    static props = {};\\n\\n    setup() {\\n        this.userName = user.name;\\n        this.dbName = session.db;\\n        const { partnerId, writeDate } = user;\\n        this.source = imageUrl(\\"res.partner\\", partnerId, \\"avatar_128\\", { unique: writeDate });\\n    }\\n\\n    getElements() {\\n        const sortedItems = userMenuRegistry\\n            .getAll()\\n            .map((element) => element(this.env))\\n            .filter((element) => (element.show ? element.show() : true))\\n            .sort((x, y) => {\\n                const xSeq = x.sequence ? x.sequence : 100;\\n                const ySeq = y.sequence ? y.sequence : 100;\\n                return xSeq - ySeq;\\n            });\\n        return sortedItems;\\n    }\\n}\\n\\nexport const systrayItem = {\\n    Component: UserMenu,\\n};\\nregistry.category(\\"systray\\").add(\\"web.user_menu\\", systrayItem, { sequence: 0 });\\n", "import { Component, markup } from \\"@odoo/owl\\";\\nimport { isMacOS } from \\"@web/core/browser/feature_detection\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { rpc } from \\"@web/core/network/rpc\\";\\nimport { user } from \\"@web/core/user\\";\\nimport { session } from \\"@web/session\\";\\nimport { browser } from \\"../../core/browser/browser\\";\\nimport { registry } from \\"../../core/registry\\";\\n\\nfunction supportItem(env) {\\n    const url = session.support_url;\\n    return {\\n        type: \\"item\\",\\n        id: \\"support\\",\\n        description: _t(\\"Help\\"),\\n        href: url,\\n        callback: () => {\\n            browser.open(url, \\"_blank\\");\\n        },\\n        sequence: 20,\\n    };\\n}\\n\\nclass ShortcutsFooterComponent extends Component {\\n    static template = \\"web.UserMenu.ShortcutsFooterComponent\\";\\n    static props = {\\n        switchNamespace: { type: Function, optional: true },\\n    };\\n    setup() {\\n        this.runShortcutKey = isMacOS() ? \\"CONTROL\\" : \\"ALT\\";\\n    }\\n}\\n\\nfunction shortCutsItem(env) {\\n    return {\\n        type: \\"item\\",\\n        id: \\"shortcuts\\",\\n        hide: env.isSmall,\\n        description: markup`\\n            <div class=\\"d-flex align-items-center justify-content-between p-0 w-100\\">\\n                <span>${_t(\\"Shortcuts\\")}</span>\\n                <span class=\\"fw-bold\\">${isMacOS() ? \\"CMD\\" : \\"CTRL\\"}+K</span>\\n            </div>`,\\n        callback: () => {\\n            env.services.command.openMainPalette({ FooterComponent: ShortcutsFooterComponent });\\n        },\\n        sequence: 30,\\n    };\\n}\\n\\nfunction separator() {\\n    return {\\n        type: \\"separator\\",\\n        sequence: 40,\\n    };\\n}\\n\\nexport function preferencesItem(env) {\\n    return {\\n        type: \\"item\\",\\n        id: \\"preferences\\",\\n        description: _t(\\"My Preferences\\"),\\n        callback: async function () {\\n            const actionDescription = await env.services.orm.call(\\"res.users\\", \\"action_get\\");\\n            actionDescription.res_id = user.userId;\\n            env.services.action.doAction(actionDescription);\\n        },\\n        sequence: 50,\\n    };\\n}\\n\\nexport function odooAccountItem(env) {\\n    return {\\n        type: \\"item\\",\\n        id: \\"account\\",\\n        description: _t(\\"My Odoo.com Account\\"),\\n        callback: () => {\\n            rpc(\\"/web/session/account\\")\\n                .then((url) => {\\n                    browser.open(url, \\"_blank\\");\\n                })\\n                .catch(() => {\\n                    browser.open(\\"https://accounts.odoo.com/account\\", \\"_blank\\");\\n                });\\n        },\\n        sequence: 60,\\n    };\\n}\\n\\nfunction installPWAItem(env) {\\n    let description = _t(\\"Install App\\");\\n    let callback = () => env.services.pwa.show();\\n    let show = () => env.services.pwa.isAvailable;\\n    const currentApp = env.services.menu.getCurrentApp();\\n    if (currentApp && [\\"barcode\\", \\"field-service\\", \\"shop-floor\\"].includes(currentApp.actionPath)) {\\n        // While the feature could work with all apps, we have decided to only\\n        // support the installation of the apps contained in this list\\n        // The list can grow in the future, by simply adding their path\\n        description = _t(\\"Install %s\\", currentApp.name);\\n        callback = () => {\\n            window.open(\\n                `/scoped_app?app_id=${currentApp.webIcon.split(\\",\\")[0]}&path=${encodeURIComponent(\\n                    \\"scoped_app/\\" + currentApp.actionPath\\n                )}`\\n            );\\n        };\\n        show = () => !env.services.pwa.isScopedApp;\\n    }\\n    return {\\n        type: \\"item\\",\\n        id: \\"install_pwa\\",\\n        description,\\n        callback,\\n        show,\\n        sequence: 65,\\n    };\\n}\\n\\nfunction logOutItem(env) {\\n    let route = \\"/web/session/logout\\";\\n    if (env.services.pwa.isScopedApp) {\\n        route += `?redirect=${encodeURIComponent(env.services.pwa.startUrl)}`;\\n    }\\n    return {\\n        type: \\"item\\",\\n        id: \\"logout\\",\\n        description: _t(\\"Log out\\"),\\n        href: `${browser.location.origin}${route}`,\\n        callback: () => {\\n            browser.navigator.serviceWorker?.controller?.postMessage(\\"user_logout\\");\\n            browser.location.href = route;\\n        },\\n        sequence: 70,\\n    };\\n}\\n\\nregistry\\n    .category(\\"user_menuitems\\")\\n    .add(\\"support\\", supportItem)\\n    .add(\\"shortcuts\\", shortCutsItem)\\n    .add(\\"separator\\", separator)\\n    .add(\\"preferences\\", preferencesItem)\\n    .add(\\"odoo_account\\", odooAccountItem)\\n    .add(\\"install_pwa\\", installPWAItem)\\n    .add(\\"log_out\\", logOutItem);\\n", "import { useOwnDebugContext } from \\"@web/core/debug/debug_context\\";\\nimport { DebugMenu } from \\"@web/core/debug/debug_menu\\";\\nimport { localization } from \\"@web/core/l10n/localization\\";\\nimport { MainComponentsContainer } from \\"@web/core/main_components_container\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { useBus, useService } from \\"@web/core/utils/hooks\\";\\nimport { ActionContainer } from \\"./actions/action_container\\";\\nimport { NavBar } from \\"./navbar/navbar\\";\\n\\nimport { Component, onMounted, onWillStart, useExternalListener, useState } from \\"@odoo/owl\\";\\nimport { router, routerBus } from \\"@web/core/browser/router\\";\\nimport { browser } from \\"@web/core/browser/browser\\";\\nimport { rpcBus } from \\"@web/core/network/rpc\\";\\n\\nexport class WebClient extends Component {\\n    static template = \\"web.WebClient\\";\\n    static props = {};\\n    static components = {\\n        ActionContainer,\\n        NavBar,\\n        MainComponentsContainer,\\n    };\\n\\n    setup() {\\n        this.menuService = useService(\\"menu\\");\\n        this.actionService = useService(\\"action\\");\\n        this.title = useService(\\"title\\");\\n        useOwnDebugContext({ categories: [\\"default\\"] });\\n        if (this.env.debug) {\\n            registry.category(\\"systray\\").add(\\n                \\"web.debug_mode_menu\\",\\n                {\\n                    Component: DebugMenu,\\n                },\\n                { sequence: 100 }\\n            );\\n        }\\n        this.localization = localization;\\n        this.state = useState({\\n            fullscreen: false,\\n        });\\n        useBus(routerBus, \\"ROUTE_CHANGE\\", async () => {\\n            document.body.style.pointerEvents = \\"none\\";\\n            try {\\n                await this.loadRouterState();\\n            } finally {\\n                document.body.style.pointerEvents = \\"auto\\";\\n            }\\n        });\\n        useBus(this.env.bus, \\"ACTION_MANAGER:UI-UPDATED\\", ({ detail: mode }) => {\\n            if (mode !== \\"new\\") {\\n                this.state.fullscreen = mode === \\"fullscreen\\";\\n            }\\n        });\\n        useBus(this.env.bus, \\"WEBCLIENT:LOAD_DEFAULT_APP\\", this._loadDefaultApp);\\n        onMounted(() => {\\n            this.loadRouterState();\\n            // the chat window and dialog services listen to 'web_client_ready' event in\\n            // order to initialize themselves:\\n            this.env.bus.trigger(\\"WEB_CLIENT_READY\\");\\n        });\\n        useExternalListener(window, \\"click\\", this.onGlobalClick, { capture: true });\\n        onWillStart(this.registerServiceWorker);\\n    }\\n\\n    async loadRouterState() {\\n        // ** url-retrocompatibility **\\n        // the menu_id in the url is only possible if we came from an old url\\n        let menuId = Number(router.current.menu_id || 0);\\n        const storedMenuId = Number(browser.sessionStorage.getItem(\\"menu_id\\"));\\n        const firstAction = router.current.actionStack?.[0]?.action;\\n        if (!menuId && firstAction) {\\n            // Find all menus that match this action\\n            const matchingMenus = this.menuService\\n                .getAll()\\n                .filter((m) => m.actionID === firstAction || m.actionPath === firstAction);\\n\\n            if (matchingMenus.length > 0) {\\n                // Use sessionStorage context to determine the correct menu\\n                menuId = matchingMenus.find(m => \\n                    m.appID === storedMenuId\\n                )?.appID;\\n                if (!menuId) {\\n                    menuId = matchingMenus[0]?.appID;\\n                }\\n            }\\n        }\\n        if (menuId) {\\n            this.menuService.setCurrentMenu(menuId);\\n        }\\n        let stateLoaded = await this.actionService.loadState();\\n\\n        // ** url-retrocompatibility **\\n        // when there is only menu_id in url\\n        if (!stateLoaded && menuId) {\\n            // Determines the current actionId based on the current menu\\n            const menu = this.menuService.getAll().find((m) => menuId === m.id);\\n            const actionId = menu && menu.actionID;\\n            if (actionId) {\\n                await this.actionService.doAction(actionId, { clearBreadcrumbs: true });\\n                stateLoaded = true;\\n            }\\n        }\\n\\n        // Setting the menu based on the action after it was loaded (eg when the action in url is an xmlid)\\n        if (stateLoaded && !menuId) {\\n            // Determines the current menu based on the current action\\n            const currentController = this.actionService.currentController;\\n            const actionId = currentController && currentController.action.id;\\n            menuId = this.menuService.getAll().find((m) => m.actionID === actionId)?.appID;\\n            if (!menuId) {\\n                // Setting the menu based on the session storage if no other menu was found\\n                menuId = storedMenuId;\\n            }\\n            if (menuId) {\\n                // Sets the menu according to the current action\\n                this.menuService.setCurrentMenu(menuId);\\n            }\\n        }\\n\\n        // Scroll to anchor after the state is loaded\\n        if (stateLoaded) {\\n            if (browser.location.hash !== \\"\\") {\\n                try {\\n                    const el = document.querySelector(browser.location.hash);\\n                    if (el !== null) {\\n                        el.scrollIntoView(true);\\n                    }\\n                } catch {\\n                    // do nothing if the hash is not a correct selector.\\n                }\\n            }\\n        }\\n\\n        if (!stateLoaded) {\\n            // If no action => falls back to the default app\\n            await this._loadDefaultApp();\\n        }\\n    }\\n\\n    _loadDefaultApp() {\\n        // Selects the first root menu if any\\n        const root = this.menuService.getMenu(\\"root\\");\\n        const firstApp = root.children[0];\\n        if (firstApp) {\\n            return this.menuService.selectMenu(firstApp);\\n        }\\n    }\\n\\n    /**\\n     * @param {MouseEvent} ev\\n     */\\n    onGlobalClick(ev) {\\n        // When a ctrl-click occurs inside an <a href/> element\\n        // we let the browser do the default behavior and\\n        // we do not want any other listener to execute.\\n        if (\\n            (ev.ctrlKey || ev.metaKey) &&\\n            !ev.target.isContentEditable &&\\n            ((ev.target instanceof HTMLAnchorElement && ev.target.href) ||\\n                (ev.target instanceof HTMLElement && ev.target.closest(\\"a[href]:not([href=''])\\")))\\n        ) {\\n            ev.stopImmediatePropagation();\\n            return;\\n        }\\n    }\\n\\n    registerServiceWorker() {\\n        if (navigator.serviceWorker) {\\n            navigator.serviceWorker\\n                .register(\\"/web/service-worker.js\\", { scope: \\"/odoo\\" })\\n                .then(() => {\\n                    navigator.serviceWorker.ready.then(() => {\\n                        if (!navigator.serviceWorker.controller) {\\n                            // https://stackoverflow.com/questions/51597231/register-service-worker-after-hard-refresh\\n                            rpcBus.trigger(\\"CLEAR-CACHES\\");\\n                        }\\n                    });\\n                })\\n                .catch((error) => {\\n                    console.error(\\"Service worker registration failed, error:\\", error);\\n                });\\n        }\\n    }\\n}\\n", "import { useService } from \\"@web/core/utils/hooks\\";\\nimport { useSetupAction } from \\"@web/search/action_hook\\";\\nimport { Layout } from \\"@web/search/layout\\";\\nimport { getDefaultConfig } from \\"@web/views/view\\";\\nimport { useEnrichWithActionLinks } from \\"@web/webclient/actions/reports/report_hook\\";\\n\\nimport { Component, useRef, useSubEnv } from \\"@odoo/owl\\";\\n\\n/**\\n * Most of the time reports are printed as pdfs.\\n * However, reports have 3 possible actions: pdf, text and HTML.\\n * This file is the HTML action.\\n * The HTML action is a client action (with control panel) rendering the template in an iframe.\\n * If not defined as the default action, the HTML is the fallback to pdf if wkhtmltopdf is not available.\\n *\\n * It has a button to print the report.\\n * It uses a feature to automatically create links to other odoo pages if the selector [res-id][res-model][view-type]\\n * is detected.\\n */\\nexport class ReportAction extends Component {\\n    static components = { Layout };\\n    static template = \\"web.ReportAction\\";\\n    static props = [\\"*\\"];\\n    setup() {\\n        useSubEnv({\\n            config: {\\n                ...getDefaultConfig(),\\n                ...this.env.config,\\n            },\\n        });\\n        useSetupAction();\\n\\n        this.action = useService(\\"action\\");\\n        this.title = this.props.display_name || this.props.name;\\n        this.reportUrl = this.props.report_url;\\n        this.iframe = useRef(\\"iframe\\");\\n        useEnrichWithActionLinks(this.iframe);\\n    }\\n\\n    onIframeLoaded(ev) {\\n        const iframeDocument = ev.target.contentWindow.document;\\n        iframeDocument.body.classList.add(\\"o_in_iframe\\", \\"container-fluid\\");\\n        iframeDocument.body.classList.remove(\\"container\\");\\n    }\\n\\n    print() {\\n        this.action.doAction({\\n            type: \\"ir.actions.report\\",\\n            report_type: \\"qweb-pdf\\",\\n            report_name: this.props.report_name,\\n            report_file: this.props.report_file,\\n            data: this.props.data || {},\\n            context: this.props.context || {},\\n            display_name: this.title,\\n        });\\n    }\\n}\\n", "import { useComponent, useEffect } from \\"@odoo/owl\\";\\n\\n/**\\n * Hook used to enrich html and provide automatic links to action.\\n * Dom elements must have those attrs [res-id][res-model][view-type]\\n * Each element with those attrs will become a link to the specified resource.\\n * Works with Iframes.\\n *\\n * @param {owl reference} ref Owl ref to the element to enrich\\n * @param {string} [selector] Selector to apply to the element resolved by the ref.\\n */\\nexport function useEnrichWithActionLinks(ref, selector = null) {\\n    const comp = useComponent();\\n    useEffect(\\n        (element) => {\\n            // If we get an iframe, we need to wait until everything is loaded\\n            if (element.matches(\\"iframe\\")) {\\n                element.onload = () => enrich(comp, element, selector, true);\\n            } else {\\n                enrich(comp, element, selector);\\n            }\\n        },\\n        () => [ref.el]\\n    );\\n}\\n\\nfunction enrich(component, targetElement, selector, isIFrame = false) {\\n    let doc = window.document;\\n\\n    // If we are in an iframe, we need to take the right document\\n    // both for the element and the doc\\n    if (isIFrame) {\\n        targetElement = targetElement.contentDocument;\\n        doc = targetElement;\\n    }\\n\\n    // If there are selector, we may have multiple blocks of code to enrich\\n    const targets = [];\\n    if (selector) {\\n        targets.push(...targetElement.querySelectorAll(selector));\\n    } else {\\n        targets.push(targetElement);\\n    }\\n\\n    // Search the elements with the selector, update them and bind an action.\\n    for (const currentTarget of targets) {\\n        const elementsToWrap = currentTarget.querySelectorAll(\\"[res-id][res-model][view-type]\\");\\n        for (const element of elementsToWrap.values()) {\\n            const wrapper = doc.createElement(\\"a\\");\\n            wrapper.setAttribute(\\"href\\", \\"#\\");\\n            wrapper.addEventListener(\\"click\\", (ev) => {\\n                ev.preventDefault();\\n                component.env.services.action.doAction({\\n                    type: \\"ir.actions.act_window\\",\\n                    view_mode: element.getAttribute(\\"view-type\\"),\\n                    res_id: Number(element.getAttribute(\\"res-id\\")),\\n                    res_model: element.getAttribute(\\"res-model\\"),\\n                    views: [[element.getAttribute(\\"view-id\\"), element.getAttribute(\\"view-type\\")]],\\n                });\\n            });\\n            element.parentNode.insertBefore(wrapper, element);\\n            wrapper.appendChild(element);\\n        }\\n    }\\n}\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { download } from \\"@web/core/network/download\\";\\n\\n/**\\n * Generates the report url given a report action.\\n *\\n * @param {Object} action the report action\\n * @param {\\"text\\"|\\"qweb\\"|\\"html\\"} type the type of the report\\n * @param {Object} userContext the user context\\n * @returns {string}\\n */\\nexport function getReportUrl(action, type, userContext) {\\n    let url = `/report/${type}/${action.report_name}`;\\n    const actionContext = action.context || {};\\n    if (action.data && JSON.stringify(action.data) !== \\"{}\\") {\\n        // build a query string with `action.data` (it's the place where reports\\n        // using a wizard to customize the output traditionally put their options)\\n        const options = encodeURIComponent(JSON.stringify(action.data));\\n        const context = encodeURIComponent(JSON.stringify(actionContext));\\n        url += `?options=${options}&context=${context}`;\\n    } else {\\n        if (actionContext.active_ids) {\\n            url += `/${actionContext.active_ids.join(\\",\\")}`;\\n        }\\n        if (type === \\"html\\") {\\n            const context = encodeURIComponent(JSON.stringify(userContext));\\n            url += `?context=${context}`;\\n        }\\n    }\\n    return url;\\n}\\n\\n// messages that might be shown to the user dependening on the state of wkhtmltopdf\\nfunction getWKHTMLTOPDF_MESSAGES(status) {\\n    const link = '<br><br><a href=\\"http://wkhtmltopdf.org/\\" target=\\"_blank\\">wkhtmltopdf.org</a>'; // FIXME missing markup\\n    const _status = {\\n        broken: _t(\\n            \\"Your installation of Wkhtmltopdf seems to be broken. The report will be shown in html.%(link)s\\",\\n            { link }\\n        ),\\n        install: _t(\\n            \\"Unable to find Wkhtmltopdf on this system. The report will be shown in html.%(link)s\\",\\n            { link }\\n        ),\\n        upgrade: _t(\\n            \\"You should upgrade your version of Wkhtmltopdf to at least 0.12.0 in order to get a correct display of headers and footers as well as support for table-breaking between pages.%(link)s\\",\\n            { link }\\n        ),\\n        workers: _t(\\n            \\"You need to start Odoo with at least two workers to print a pdf version of the reports.\\"\\n