l simply open a link that will trigger the download of\\n     * the associated file. If the url is not valid, the function will display\\n     * an error message.\\n     */\\n    async download() {\\n        try {\\n            await downloadFile(this.fileModel.downloadUrl);\\n        } catch {\\n            this.dialogService.add(AlertDialog, {\\n                body: _t(\\n                    \\"Oops, the file %s could not be found. Please replace this file box by a new one to re-upload the file.\\",\\n                    this.fileModel.name\\n                ),\\n                title: _t(\\"Missing File\\"),\\n                confirm: () => {},\\n                confirmLabel: _t(\\"Close\\"),\\n            });\\n        }\\n    }\\n\\n    onClickFileImage() {\\n        if (this.fileModel.isViewable) {\\n            this.attachmentViewer.open(this.fileModel);\\n        } else {\\n            this.download();\\n        }\\n    }\\n}\\n\\nexport const readonlyFileEmbedding = {\\n    name: \\"file\\",\\n    Component: ReadonlyEmbeddedFileComponent,\\n    getProps: (host) => ({ host, ...getEmbeddedProps(host) }),\\n};\\n", "import { FileModel } from \\"@web/core/file_viewer/file_model\\";\\n\\nexport class StateFileModel extends FileModel {\\n    constructor(state) {\\n        super();\\n        this.state = state;\\n        for (const property of [\\n            \\"access_token\\",\\n            \\"checksum\\",\\n            \\"extension\\",\\n            \\"filename\\",\\n            \\"id\\",\\n            \\"mimetype\\",\\n            \\"name\\",\\n            \\"type\\",\\n            \\"tmpUrl\\",\\n            \\"url\\",\\n            \\"uploading\\",\\n        ]) {\\n            Object.defineProperty(this, property, {\\n                get() {\\n                    return this.state.fileData[property];\\n                },\\n                set(value) {\\n                    this.state.fileData[property] = value;\\n                },\\n                configurable: true,\\n                enumerable: true,\\n            });\\n        }\\n    }\\n\\n    /**\\n     * For embedded files stored without an `id` (i.e. demo data or old\\n     * knowledge embedded files converted from \\"Knowledge Behavior\\"), allow\\n     * direct usage of the file `url` as an `urlRoute` for the fileViewer and\\n     * download attempts.\\n     *\\n     * @override\\n     */\\n    get urlRoute() {\\n        if (this.isUrl && !this.id) {\\n            return this.url;\\n        }\\n        return super.urlRoute;\\n    }\\n}\\n", "import { Component, onWillStart, useState } from \\"@odoo/owl\\";\\nimport { TableOfContentManager } from \\"@html_editor/others/embedded_components/core/table_of_content/table_of_content_manager\\";\\n\\nexport class EmbeddedTableOfContentComponent extends Component {\\n    static template = \\"html_editor.EmbeddedTableOfContent\\";\\n    static props = {\\n        manager: { type: TableOfContentManager },\\n        readonly: { type: Boolean, optional: true },\\n    };\\n\\n    setup() {\\n        this.state = useState({ toc: this.props.manager.structure, folded: false });\\n        onWillStart(async () => {\\n            await this.props.manager.batchedUpdateStructure();\\n        });\\n    }\\n\\n    displayTocHint() {\\n        return this.state.toc.headings.length < 2 && !this.props.readonly;\\n    }\\n\\n    /**\\n     * @param {Object} heading\\n     */\\n    onTocLinkClick(heading) {\\n        this.props.manager.scrollIntoView(heading);\\n    }\\n}\\n\\nexport const tableOfContentEmbedding = {\\n    name: \\"tableOfContent\\",\\n    Component: EmbeddedTableOfContentComponent,\\n};\\n\\nexport const readonlyTableOfContentEmbedding = {\\n    name: \\"tableOfContent\\",\\n    Component: EmbeddedTableOfContentComponent,\\n    getProps: (host) => ({\\n        readonly: true,\\n    }),\\n};\\n", "import { batched, reactive } from \\"@odoo/owl\\";\\n\\nexport const HEADINGS = [\\"H1\\", \\"H2\\", \\"H3\\", \\"H4\\", \\"H5\\", \\"H6\\"];\\n\\nexport class TableOfContentManager {\\n    constructor(containerRef) {\\n        this.containerRef = containerRef;\\n        this.structure = reactive({\\n            headings: [],\\n        });\\n        this.batchedUpdateStructure = batched(this.updateStructure.bind(this));\\n    }\\n\\n    getContainerEl() {\\n        return this.containerRef.el;\\n    }\\n\\n    /**\\n     * Allows to fetch relevant headings in the page when building the Table of Content.\\n     * Will filter out things we don't want:\\n     * - Empty headers\\n     * - Headers only containing the 'ZeroWidthSpace' element ('\\\\u200B')\\n     * - Headers descendants of an element with `data-embedded`\\n     *\\n     * @param {Element} element\\n     */\\n    fetchValidHeadings(element) {\\n        const inEmbeddedHeadings = new Set(\\n            element.querySelectorAll(\\n                HEADINGS.map((heading) => `[data-embedded] ${heading}`).join(\\",\\")\\n            )\\n        );\\n        return Array.from(element.querySelectorAll(HEADINGS.join(\\",\\")))\\n            .filter((heading) => heading.innerText.trim().replaceAll(\\"\\\\u200B\\", \\"\\").length > 0)\\n            .filter((heading) => !inEmbeddedHeadings.has(heading));\\n    }\\n\\n    scrollIntoView(heading) {\\n        if (!heading) {\\n            return;\\n        }\\n        const { target } = heading;\\n        target.scrollIntoView({ behavior: \\"smooth\\" });\\n        target.classList.add(\\"o_embedded_toc_header_highlight\\");\\n        window.setTimeout(() => {\\n            target.classList.remove(\\"o_embedded_toc_header_highlight\\");\\n        }, 2000);\\n    }\\n\\n    updateStructure() {\\n        const container = this.getContainerEl();\\n        if (!container) {\\n            return;\\n        }\\n        const tagDepthStack = [];\\n        this.structure.headings = this.fetchValidHeadings(container).map((heading) => {\\n            while (tagDepthStack.at(-1) >= heading.tagName) {