  outdentBlocks(blocks) {\\n        for (const block of blocks) {\\n            const firstTab = descendants(block).find(isEditorTab);\\n            if (firstTab && isIndentationTab(firstTab)) {\\n                this.removeTrailingZWS(firstTab);\\n                firstTab.remove();\\n            }\\n        }\\n    }\\n\\n    removeTrailingZWS(tab) {\\n        const selection = this.dependencies.selection.getEditableSelection();\\n        const { anchorNode, anchorOffset, focusNode, focusOffset } = selection;\\n        const updateAnchor = anchorNode === tab.nextSibling;\\n        const updateFocus = focusNode === tab.nextSibling;\\n        let zwsRemoved = 0;\\n        while (\\n            tab.nextSibling &&\\n            tab.nextSibling.nodeType === Node.TEXT_NODE &&\\n            tab.nextSibling.textContent.startsWith(\\"\\\\u200B\\")\\n        ) {\\n            splitTextNode(tab.nextSibling, 1, DIRECTIONS.LEFT);\\n            tab.nextSibling.remove();\\n            zwsRemoved++;\\n        }\\n        if (updateAnchor || updateFocus) {\\n            this.dependencies.selection.setSelection({\\n                anchorNode: updateAnchor ? tab.nextSibling : anchorNode,\\n                anchorOffset: updateAnchor ? Math.max(0, anchorOffset - zwsRemoved) : anchorOffset,\\n                focusNode: updateFocus ? tab.nextSibling : focusNode,\\n                focusOffset: updateFocus ? Math.max(0, focusOffset - zwsRemoved) : focusOffset,\\n            });\\n        }\\n    }\\n\\n    /**\\n     * @param {HTMLSpanElement} tabSpan - span.oe-tabs element\\n     */\\n    adjustTabWidth(tabSpan) {\\n        let tabPreviousSibling = tabSpan.previousSibling;\\n        while (isZWS(tabPreviousSibling)) {\\n            tabPreviousSibling = tabPreviousSibling.previousSibling;\\n        }\\n        if (isEditorTab(tabPreviousSibling)) {\\n            tabSpan.style.width = `${GRID_COLUMN_WIDTH}px`;\\n            return;\\n        }\\n        const spanRect = tabSpan.getBoundingClientRect();\\n        const referenceRect = this.editable.firstElementChild?.getBoundingClientRect();\\n        // @ todo @phoenix Re-evaluate if this check is necessary.\\n        // Values from getBoundingClientRect() are all zeros during\\n        // Editor startup or saving. We cannot recalculate the tabs\\n        // width in thoses cases.\\n        if (!referenceRect?.width || !spanRect.width) {\\n            return;\\n        }\\n        const relativePosition = spanRect.left - referenceRect.left;\\n        const distToNextGridLine = GRID_COLUMN_WIDTH - (relativePosition % GRID_COLUMN_WIDTH);\\n        // Round to the first decimal point.\\n        const width = distToNextGridLine.toFixed(1);\\n        tabSpan.style.width = `${width}px`;\\n    }\\n\\n    /**\\n     * Aligns the tabs under the specified tree to a grid.\\n     *\\n     * @param {HTMLElement} [root] - The tree root.\\n     */\\n    alignTabs(root = this.editable) {\\n        const block = closestBlock(root);\\n        if (!block) {\\n            return;\\n        }\\n        for (const tab of block.querySelectorAll(\\"span.oe-tabs\\")) {\\n            this.adjustTabWidth(tab);\\n        }\\n    }\\n\\n    // When deleting an editor tab, we need to ensure it's related\\n    // ZWS will deleted as well.\\n    // @todo @phoenix: for some reason, there might be more than one ZWS.\\n    // Investigate why.\\n    expandRangeToIncludeZWS(tabElement) {\\n        let previous = tabElement;\\n        let node = tabElement.nextSibling;\\n        while (node?.nodeType === Node.TEXT_NODE) {\\n            for (let i = 0; i < node.textContent.length; i++) {\\n                if (node.textContent[i] !== \\"\\\\u200B\\") {\\n                    return [node, i];\\n                }\\n            }\\n            previous = node;\\n            node = node.nextSibling;\\n        }\\n        return [previous.parentElement, childNodeIndex(previous) + 1];\\n    }\\n\\n    // @todo consider registering this as adjustRange callback instead.\\n    handleDeleteForward(range) {\\n        let { endContainer, endOffset } = range;\\n        if (!(endContainer?.nodeType === Node.ELEMENT_NODE) || !endOffset) {\\n            return;\\n        }\\n        const nodeToDelete = endContainer.childNodes[endOffset - 1];\\n        if (isEditorTab(nodeToDelete)) {\\n            [endContainer, endOffset] = this.expandRangeToIncludeZWS(nodeToDelete);\\n            range = this.dependencies.delete.deleteRange({ ...range, endContainer, endOffset });\\n            this.dependencies.selection.setSelection({\\n                anchorNode: range.startContainer,\\n                anchorOffset: range.startOffset,\\n            });\\n            return true;\\n        }\\n    }\\n    normalize(el) {\\n        this.alignTabs(el);\\n    }\\n}\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { Plugin } from \\"../plugin\\";\\nimport { closestBlock } from \\"../utils/blocks\\";\\nimport { closestElement } from \\"../utils/dom_traversal\\";\\nimport { isContentEditable, isTextNode } from \\"@html_editor/utils/dom_info\\";\\nimport { isHtmlContentSupported } from \\"@html_editor/core/selection_plugin\\";\\n\\nexport class TextDirectionPlugin extends Plugin {\\n    static id = \\"textDirection\\";\\n    static dependencies = [\\"selection\\", \\"history\\", \\"split\\", \\"format\\"];\\n    resources = {\\n        user_commands: [\\n            {\\n                id: \\"switchDirection\\",\\n                title: _t(\\"Switch direction\\"),\\n                description: _t(\\"Switch the text's direction\\"),\\n                icon: \\"fa-exchange\\",\\n                run: this.switchDirection.bind(this),\\n                isAvailable: isHtmlContentSupported,\\n            },\\n        ],\\n        powerbox_items: [\\n            {\\n                categoryId: \\"format\\",\\n                commandId: \\"switchDirection\\",\\n            },\\n        ],\\n    };\\n\\n    setup() {\\n        if (this.config.direction) {\\n            this.editable.setAttribute(\\"dir\\", this.config.direction);\\n        }\\n        this.direction = this.config.direction || \\"ltr\\";\\n    }\\n\\n    switchDirection() {\\n        const selection = this.dependencies.split.splitSelection();\\n        const targetedTextNodes = [\\n            selection.anchorNode,\\n            ...this.dependencies.selection.getTargetedNodes(),\\n        ].filter((n) => isTextNode(n) && isContentEditable(n) && n.nodeValue.trim().length);\\n        const blocks = new Set(\\n            targetedTextNodes.map(\\n                (textNode) => closestElement(textNode, \\"ul,ol\\") || closestBlock(textNode)\\n            )\\n        );\\n\\n        const shouldApplyStyle = !this.dependencies.format.isSelectionFormat(\\"switchDirection\\");\\n\\n        for (const block of blocks) {\\n            for (const node of block.querySelectorAll(\\"ul,ol\\")) {\\n                blocks.add(node);\\n            }\\n        }\\n        for (const block of blocks) {\\n            if (!shouldApplyStyle) {\\n                block.removeAttribute(\\"dir\\");\\n            } else {\\n                block.setAttribute(\\"dir\\", this.direction === \\"ltr\\" ? \\"rtl\\" : \\"ltr\\");\\n            }\\n        }\\n\\n        for (const element of blocks) {\\n            const style = getComputedStyle(element);\\n            if (style.direction === \\"ltr\\" && style.textAlign === \\"right\\") {\\n                element.style.setProperty(\\"text-align\\", \\"left\\");\\n            } else if (style.direction === \\"rtl\\" && style.textAlign === \\"left\\") {\\n                element.style.setProperty(\\"text-align\\", \\"right\\");\\n            }\\n        }\\n        this.dependencies.history.addStep();\\n    }\\n}\\n", "import { Component, onMounted, useExternalListener, useRef } from \\"@odoo/owl\\";\\nimport { Toolbar } from \\"./toolbar\\";\\n\\nexport class ToolbarMobile extends Component {\\n    static template = \\"html_editor.MobileToolbar\\";\\n    static props = [\\"*\\"];\\n    static components = {\\n        Toolbar,\\n    };\\n\\n    setup() {\\n        this.toolbar = useRef(\\"toolbarWrapper\\");\\n        useExternalListener(window.visualViewport, \\"resize\\", this.fixToolbarPosition);\\n        useExternalListener(window.visualViewport, \\"scroll\\", this.fixToolbarPosition);\\n        onMounted(() => {\\n            this.fixToolbarPosition();\\n        });\\n    }\\n\\n    /**\\n     * Fixes the position of the toolbar for the keyboard height.\\n     */\\n    fixToolbarPosition() {\\n        const keyboardHeight =\\n            window.innerHeight - (window.visualViewport.height + window.visualViewport.offsetTop);\\n        if (keyboardHeight > 0) {\\n            this.toolbar.el.style.bottom = `${keyboardHeight}px`;\\n        } else {\\n            this.toolbar.el.style.bottom = `0px`;\\n        }\\n    }\\n}\\n", "import { Component, useState, validate } from \\"@odoo/owl\\";\\nimport { omit, pick } from \\"@web/core/utils/objects\\";\\n\\nexport class Toolbar extends Component {\\n    static template = \\"html_editor.Toolbar\\";\\n    static props = {\\n        class: { type: String, optional: true },\\n        getSelection: Function,\\n        focusEditable: Function,\\n        state: {\\n            type: Object,\\n            shape: {\\n                namespace: { type: String, optional: true },\\n                buttonGroups: {\\n                    type: Array,\\n                    element: {\\n                        type: Object,\\n                        shape: {\\n                            id: String,\\n                            buttons: {\\n                                type: Array,\\n                                element: {\\n                                    type: Object,\\n                                    validate: (button) => {\\n                                        const base = {\\n                                            id: String,\\n                                            description: String,\\n                                            isDisabled: Boolean,\\n                                        };\\n                                        if (button.Component) {\\n                                            validate(button, {\\n                                                ...base,\\n                                                Component: Function,\\n                                                props: { type: Object, optional: true },\\n                                            });\\n                                        } else {\\n                                            validate(button, {\\n                                                ...base,\\n                                                run: Function,\\n                                                icon: { type: String, optional: true },\\n                                                text: { type: String, optional: true },\\n                                                isActive: Boolean,\\n                                            });\\n                                        }\\n                                        return true;\\n                                    },\\n                                },\\n                            },\\n                        },\\n                    },\\n                },\\n            },\\n        },\\n    };\\n\\n    setup() {\\n        this.state = useState(this.props.state);\\n    }\\n\\n    onButtonClick(button) {\\n        button.run();\\n        this.props.focusEditable();\\n    }\\n}\\n\\nexport const toolbarButtonProps = {\\n    title: [String, Function],\\n    getSelection: Function,\\n    isDisabled: Boolean,\\n};\\n\\n/** @typedef {import(\\"@html_editor/core/user_command_plugin\\").UserCommand} UserCommand */\\n/** @typedef {import(\\"./toolbar_plugin\\").ToolbarCommandItem} ToolbarCommandItem */\\n/** @typedef {import(\\"./toolbar_plugin\\").ToolbarCommandButton} ToolbarCommandButton */\\n\\n/**\\n * @param {UserCommand} userCommand\\n * @param {ToolbarCommandItem} toolbarItem\\n * @returns {ToolbarCommandButton}\\n */\\nexport function composeToolbarButton(userCommand, toolbarItem) {\\n    const description = toolbarItem.description || userCommand.description;\\n    return {\\n        ...pick(userCommand, \\"icon\\"),\\n        ...omit(toolbarItem, \\"commandId\\", \\"commandParams\\"),\\n        run: () => userCommand.run(toolbarItem.commandParams),\\n        isAvailable: (selection) =>\\n            [userCommand.isAvailable, toolbarItem.isAvailable]\\n                .filter(Boolean)\\n                .every((predicate) => predicate(selection)),\\n        description: description instanceof Function ? description : () => description,\\n    };\\n}\\n", "import { Plugin } from \\"@html_editor/plugin\\";\\nimport { isEmptyTextNode, isZWS } from \\"@html_editor/utils/dom_info\\";\\nimport { reactive } from \\"@odoo/owl\\";\\nimport { composeToolbarButton, Toolbar } from \\"./toolbar\\";\\nimport { hasTouch } from \\"@web/core/browser/feature_detection\\";\\nimport { registry } from \\"@web/core/registry\\";\\nimport { ToolbarMobile } from \\"./mobile_toolbar\\";\\nimport { debounce } from \\"@web/core/utils/timing\\";\\nimport { omit, pick } from \\"@web/core/utils/objects\\";\\nimport { withSequence } from \\"@html_editor/utils/resource\\";\\nimport { _t } from \\"@web/core/l10n/translation\\";\\nimport { memoize } from \\"@web/core/utils/functions\\";\\nimport { closestElement } from \\"@html_editor/utils/dom_traversal\\";\\n\\n/** @typedef { import(\\"@html_editor/core/selection_plugin\\").EditorSelection } EditorSelection */\\n/** @typedef { import(\\"@html_editor/core/user_command_plugin\\").UserCommand } UserCommand */\\n/** @typedef { import(\\"@web/core/l10n/translation.js\\")._t} _t */\\n/** @typedef { ReturnType<_t> } TranslatedString */\\n/** @typedef { (selection: EditorSelection, nodes: Node[]) => TranslatedString } TranslatedStringGetter */\\n\\n/**\\n * @typedef {Object} ToolbarNamespace\\n * @property {string} id\\n * @property {(targetedNodes: Node[]) => boolean} isApplied\\n *\\n *\\n * @typedef {Object} ToolbarGroup\\n * @property {string} id\\n * @property {string[]} [namespaces]\\n *\\n *\\n * @typedef {ToolbarCommandItem | ToolbarComponentItem} ToolbarItem\\n *\\n * @typedef {Object} ToolbarCommandItem\\n * Regular button: derives from a user command specified by commandId.\\n * The properties maked with * can be omitted if they are present in the user command.\\n * The ones marked with ?* are both optional and derivable from the user command.\\n * @property {string} id\\n * @property {string} groupId Id of a toolbar group\\n * @property {string} commandId\\n * @property {string[]} [namespaces]\\n * @property {Object} [commandParams] Passed to the command's `run` function\\n * @property {TranslatedString | TranslatedStringGetter} [description] * - becomes the button's title (and tooltip content)\\n * @property {string} [icon] *\\n * @property {string} [text] Can be used with (or instead of) `icon`\\n * @property {(selection: EditorSelection) => boolean} [isAvailable] ? *\\n * @property {(selection: EditorSelection, nodes: Node[]) => boolean} [isActive]\\n * @property {(selection: EditorSelection, nodes: Node[]) => boolean} [isDisabled]\\n *\\n * @typedef {Object} ToolbarComponentItem\\n * Adds a custom component to the toolbar.\\n * @property {string} id\\n * @property {string} groupId\\n * @property {string[]} [namespaces]\\n * @property {TranslatedString | TranslatedStringGetter} [description]\\n * @property {Function} Component\\n * @property {Object} props\\n * @property {(selection: EditorSelection) => boolean} [isAvailable]\\n *\\n * ToolbarItem.id maps to the button's `name` attribute\\n * ToolbarItem.description maps to the button's `title` attribute (tooltip content)\\n */\\n\\n/**\\n * A ToolbarCommandItem must derive from a user command ( @see UserCommand )\\n * specified by commandId. Properties defined in a toolbar item override those\\n * from a user command.\\n *\\n * Example:\\n *\\n * resources = {\\n *     user_commands: [\\n *         @type {UserCommand}\\n *         {\\n *             id: myCommand,\\n *             run: myCommandFunction,\\n *             description: _t(\\"My Command\\"),\\n *             icon: \\"fa-bug\\",\\n *         },\\n *     ],\\n *     toolbar_groups: [\\n *         @type {ToolbarGroup}\\n *         { id: \\"myGroup\\" },\\n *     ],\\n *     toolbar_items: [\\n *         @type {ToolbarCommandItem}\\n *         {\\n *             id: \\"myButton\\",\\n *             groupId: \\"myGroup\\",\\n *             commandId: \\"myCommand\\",\\n *             description: _t(\\"My Toolbar Command Button\\"), // overrides the user command's `description`\\n *             // `icon` is inferred from the user command\\n *         },\\n *         @type {ToolbarComponentItem}\\n *         {\\n *             id: \\"myComponentButton\\",\\n *             groupId: \\"myGroup\\",\\n *             description: _t(\\"My Toolbar Component Button\\"),\\n *             Component: MyComponent,\\n *             props: { myProp: \\"myValue\\" },\\n *         },\\n *     ],\\n * };\\n */\\n\\n/**\\n * Types after conversion to renderable toolbar buttons:\\n *\\n * @typedef {Object} ToolbarCommandButton\\n * @property {string} id\\n * @property {string} groupId\\n * @property {TranslatedStringGetter} description\\n * @property {Function} run\\n * @property {string} [icon]\\n * @property {string} [text]\\n * @property {(selection: EditorSelection) => boolean} isAvailable\\n * @property {(selection: EditorSelection, nodes: Node[]) => boolean} [isActive]\\n * @property {(selection: EditorSelection, nodes: Node[]) => boolean} [isDisabled]\\n *\\n * @typedef {Object} ToolbarComponentButton\\n * Adds a custom component to the toolbar (processed version with required fields).\\n * @property {string} id\\n * @property {string} groupId\\n * @property {string[]} [namespaces]\\n * @property {TranslatedStringGetter} description\\n * @property {Function} Component\\n * @property {Object} props\\n * @property {(selection: EditorSelection) => boolean} isAvailable\\n *\\n * @typedef {ToolbarCommandButton | ToolbarComponentButton} ToolbarButton\\n */\\n\\n/** Delay in ms for toolbar open after keyup, double click or triple click. */\\nconst DELAY_TOOLBAR_OPEN = 300;\\n/** Number of buttons below which toolbar will open directly in its expanded form */\\nconst MIN_SIZE_FOR_COMPACT = 7;\\n\\n/**\\n * @typedef { Object } ToolbarShared\\n * @property { ToolbarPlugin['getToolbarInfo'] } getToolbarInfo\\n */\\n\\nexport class ToolbarPlugin extends Plugin {\\n    static id = \\"toolbar\\";\\n    static dependencies = [\\"overlay\\", \\"selection\\", \\"userCommand\\"];\\n    static shared = [\\"getToolbarInfo\\"];\\n    resources = {\\n        selectionchange_handlers: this.handleSelectionChange.bind(this),\\n        selection_leave_handlers: () => this.closeToolbar(),\\n        step_added_handlers: () => this.updateToolbar(),\\n        user_commands: {\\n            id: \\"expandToolbar\\",\\n            run: () => {\\n                this.isToolbarExpanded = true;\\n                this.updateToolbar();\\n            },\\n        },\\n        toolbar_groups: [\\n            withSequence(100, { id: \\"expand_toolbar\\", namespaces: [\\"compact\\"] }),\\n            withSequence(30, { id: \\"layout\\" }),\\n        ],\\n        toolbar_items: {\\n            id: \\"expand_toolbar\\",\\n            groupId: \\"expand_toolbar\\",\\n            commandId: \\"expandToolbar\\",\\n            description: _t(\\"Expand toolbar\\"),\\n            icon: \\"oi-ellipsis-v\\",\\n        },\\n        toolbar_namespaces: [\\n            withSequence(99, { id: \\"compact\\", isApplied: () => !this.isToolbarExpanded }),\\n            withSequence(100, { id: \\"expanded\\", isApplied: () => true }),\\n        ],\\n    };\\n\\n    setup() {\\n        const groupIds = new Set();\\n        for (const group of this.getResource(\\"toolbar_groups\\")) {\\n            if (groupIds.has(group.id)) {\\n                throw new Error(`Duplicate toolbar group id: ${group.id}`);\\n            }\\n            groupIds.add(group.id);\\n        }\\n        this.buttonGroups = this.getButtonGroups();\\n        this.buttonsByNamespace = this.getButtonsByNamespace();\\n\\n        this.isMobileToolbar = hasTouch() && window.visualViewport;\\n\\n        if (this.isMobileToolbar) {\\n            this.overlay = new MobileToolbarOverlay(this.editable);\\n        } else {\\n            this.overlay = this.dependencies.overlay.createOverlay(Toolbar, {\\n                positionOptions: {\\n                    position: \\"top-start\\",\\n                },\\n                closeOnPointerdown: false,\\n            });\\n        }\\n        this.state = reactive({ buttonGroups: [], namespace: undefined });\\n\\n        this.onSelectionChangeActive = true;\\n        this.debouncedUpdateToolbar = debounce(this._updateToolbar, DELAY_TOOLBAR_OPEN);\\n\\n        if (this.isMobileToolbar) {\\n            this.addDomListener(this.editable, \\"pointerup\\", () => {\\n                // Collapse toolbar to compact mode when tapping outside of it\\n                this.isToolbarExpanded = false;\\n            });\\n        } else {\\n            // Mouse interaction behavior:\\n            // Close toolbar on mousedown and prevent it from opening until mouseup.\\n            this.addDomListener(this.editable, \\"mousedown\\", (ev) => {\\n                // Don't close if the mousedown is on an overlay.\\n                if (!ev.target?.closest?.(\\".o-overlay-item\\")) {\\n                    this.closeToolbar();\\n                    this.debouncedUpdateToolbar.cancel();\\n                    this.onSelectionChangeActive = false;\\n                }\\n            });\\n            this.addGlobalDomListener(\\"mouseup\\", (ev) => {\\n                if (ev.detail >= 2) {\\n                    // Delayed open, waiting for a possible triple click.\\n                    this.onSelectionChangeActive = true;\\n                    this.debouncedUpdateToolbar();\\n                } else {\\n                    // Fast open, just wait for a possible selection change due\\n                    // to mouseup.\\n                    setTimeout(() => {\\n                        this.updateToolbar();\\n                        this.onSelectionChangeActive = true;\\n                    });\\n                }\\n            });\\n\\n            // Keyboard interaction behavior:\\n            // Close toolbar on keydown Arrows and prevent it from opening until\\n            // keyup. Opening is debounced to avoid open/close between\\n            // sequential keystrokes.\\n            this.addDomListener(this.editable, \\"keydown\\", (ev) => {\\n                // reason for \\"key?\\":\\n                // On Chrome, if there is a password saved for a login page,\\n                // a mouse click trigger a keydown event without any key\\n                if (ev.key?.startsWith(\\"Arrow\\")) {\\n                    this.closeToolbar();\\n                    this.onSelectionChangeActive = false;\\n                }\\n            });\\n            this.addDomListener(this.editable, \\"keyup\\", (ev) => {\\n                if (ev.key?.startsWith(\\"Arrow\\")) {\\n                    this.onSelectionChangeActive = true;\\n                    this.debouncedUpdateToolbar();\\n                }\\n            });\\n        }\\n        this.isToolbarExpanded = false;\\n        this.toolbarProps = {\\n            class: \\"shadow rounded my-2\\",\\n            getSelection: () => this.dependencies.selection.getSelectionData(),\\n            focusEditable: () => this.dependencies.selection.focusEditable(),\\n            state: this.state,\\n        };\\n    }\\n\\n    destroy() {\\n        this.debouncedUpdateToolbar.cancel();\\n        this.updateToolbar.cancel();\\n        this.overlay.close();\\n        super.destroy();\\n    }\\n\\n    /**\\n     * @returns {ToolbarButton[]}\\n     */\\n    getButtons() {\\n        /** @type {ToolbarItem[]} */\\n        const toolbarItems = this.getResource(\\"toolbar_items\\");\\n\\n        /** @type {(item: ToolbarCommandItem) => ToolbarCommandButton} */\\n        const commandItemToButton = (item) => {\\n            const command = this.dependencies.userCommand.getCommand(item.commandId);\\n            return composeToolbarButton(command, item);\\n        };\\n        /** @type {(item: ToolbarComponentItem) => ToolbarComponentButton} */\\n        const componentItemToButton = (item) => ({\\n            isAvailable: () => true,\\n            ...item,\\n            description:\\n                item.description instanceof Function ? item.description : () => item.description,\\n        });\\n\\n        return toolbarItems.map((item) =>\\n            \\"Component\\" in item ? componentItemToButton(item) : commandItemToButton(item)\\n        );\\n    }\\n\\n    getButtonGroups() {\\n        const buttons = this.getButtons();\\n        /** @type {ToolbarGroup[]} */\\n        const groups = this.getResource(\\"toolbar_groups\\");\\n\\n        return groups.map((group) => ({\\n            ...omit(group, \\"namespaces\\"),\\n            buttons: buttons\\n                .filter((button) => button.groupId === group.id)\\n                .map((button) => ({\\n                    ...button,\\n                    namespaces: button.namespaces || group.namespaces || [\\"expanded\\"],\\n                })),\\n        }));\\n    }\\n\\n    /**\\n     * @returns {Object<string, ToolbarButton[]>}\\n     */\\n    getButtonsByNamespace() {\\n        const namespaces = this.getResource(\\"toolbar_namespaces\\").map((ns) => ns.id);\\n        const buttonsByNamespace = {};\\n        for (const namespace of namespaces) {\\n            buttonsByNamespace[namespace] = this.buttonGroups.flatMap((group) =>\\n                group.buttons.filter((btn) => btn.namespaces.includes(namespace))\\n            );\\n        }\\n        return buttonsByNamespace;\\n    }\\n\\n    getToolbarInfo() {\\n        return {\\n            buttonGroups: this.buttonGroups,\\n        };\\n    }\\n\\n    handleSelectionChange(selectionData) {\\n        if (this.onSelectionChangeActive) {\\n            this.updateToolbar(selectionData);\\n        }\\n    }\\n\\n    /**\\n     * Different handlers might call updateToolbar (e.g. step added and\\n     * selection change) in the same tick. To avoid unnecessary updates, we\\n     * batch the calls.\\n     */\\n    updateToolbar = debounce(this._updateToolbar, 0, { trailing: true });\\n    _updateToolbar(selectionData = this.dependencies.selection.getSelectionData()) {\\n        const targetedNodes = this.getFilteredTargetedNodes();\\n        this.updateNamespace(targetedNodes);\\n        this.updateToolbarVisibility(selectionData, targetedNodes);\\n        if (!this.overlay.isOpen) {\\n            return;\\n        }\\n        this.updateButtonsStates(selectionData.editableSelection, targetedNodes);\\n    }\\n\\n    getFilteredTargetedNodes() {\\n        return this.dependencies.selection\\n            .getTargetedNodes()\\n            .filter(\\n                (node) =>\\n                    this.dependencies.selection.isNodeEditable(node) &&\\n                    (node.nodeType !== Node.TEXT_NODE || (!isEmptyTextNode(node) && !isZWS(node)))\\n            )\\n            .filter((node) => {\\n                const element = closestElement(node);\\n                const style = this.document.defaultView.getComputedStyle(element);\\n                return style.display !== \\"none\\" && style.visibility !== \\"hidden\\";\\n            });\\n    }\\n\\n    updateToolbarVisibility(selectionData, targetedNodes) {\\n        if (this.shouldBeVisible(selectionData, targetedNodes)) {\\n            // Do not reposition the toolbar if it's already open.\\n            if (!this.overlay.isOpen) {\\n                this.overlay.open({ props: this.toolbarProps });\\n            }\\n        } else if (this.overlay.isOpen && !this.shouldPreventClosing()) {\\n            this.closeToolbar();\\n        }\\n    }\\n\\n    shouldBeVisible(selectionData, targetedNodes) {\\n        const inEditable =\\n            selectionData.currentSelectionIsInEditable &&\\n            !selectionData.documentSelectionIsProtected &&\\n            !selectionData.documentSelectionIsProtecting;\\n        if (!inEditable) {\\n            return false;\\n        }\\n        const canDisplayToolbar = this.getResource(\\"can_display_toolbar\\").every((fn) =>\\n            fn(this.state.namespace)\\n        );\\n        if (!canDisplayToolbar) {\\n            return false;\\n        }\\n        if (this.isMobileToolbar) {\\n            return true;\\n        }\\n        const isCollapsed = selectionData.editableSelection.isCollapsed;\\n        if (isCollapsed) {\\n            return this.getResource(\\"collapsed_selection_toolbar_predicate\\").some((fn) =>\\n                fn(selectionData)\\n            );\\n        }\\n        return !!targetedNodes.length;\\n    }\\n\\n    shouldPreventClosing() {\\n        // Should check in the document with overlays.\\n        const preventClosing = document\\n            .getSelection()\\n            ?.anchorNode?.closest?.(\\"[data-prevent-closing-overlay]\\");\\n        return preventClosing?.dataset?.preventClosingOverlay === \\"true\\";\\n    }\\n\\n    updateNamespace(targetedNodes) {\\n        const namespaces = this.getResource(\\"toolbar_namespaces\\");\\n        const activeNamespace = namespaces.find((ns) => ns.isApplied(targetedNodes));\\n        this.state.namespace = activeNamespace?.id;\\n    }\\n\\n    /**\\n     * @param {EditorSelection} selection\\n     * @param {Node[]} targetedNodes\\n     */\\n    updateButtonsStates(selection, targetedNodes) {\\n        const availableButtons = this.getAvailableButtonsSet(selection);\\n        const buttonGroups = this.buttonGroups\\n            .map((group) => ({\\n                id: group.id,\\n                buttons: group.buttons\\n                    .filter((button) => availableButtons.has(button))\\n                    .map((button) => ({\\n                        id: button.id,\\n                        description: button.description(selection, targetedNodes),\\n                        isDisabled: !!button.isDisabled?.(selection, targetedNodes),\\n                        ...(button.Component\\n                            ? pick(button, \\"Component\\", \\"props\\")\\n                            : {\\n                                  ...pick(button, \\"run\\", \\"icon\\", \\"text\\"),\\n                                  isActive: !!button.isActive?.(selection, targetedNodes),\\n                              }),\\n                    })),\\n            }))\\n            // Filter out groups left empty\\n            .filter((group) => group.buttons.length > 0);\\n\\n        this.state.buttonGroups = buttonGroups;\\n    }\\n\\n    /**\\n     * Get the set of available buttons for the current namespace and selection.\\n     *\\n     * @param {EditorSelection} selection\\n     * @returns {Set<ToolbarButton>}\\n     */\\n    getAvailableButtonsSet(selection) {\\n        if (this.state.namespace === \\"compact\\") {\\n            return this.getAvailableButtonsCompact(selection);\\n        }\\n        const isAvailable = (button) => button.isAvailable(selection);\\n        return new Set(this.buttonsByNamespace[this.state.namespace].filter(isAvailable));\\n    }\\n\\n    /**\\n     * We only display the toolbar in its compact form if the expanded form is\\n     * larger than a threshold, and larger than the compact version itself.\\n     * Otherwise, we display the expanded toolbar directly.\\n     *\\n     * @param {EditorSelection} selection\\n     * @returns {Set<ToolbarButton>}\\n     */\\n    getAvailableButtonsCompact(selection) {\\n        const isAvailable = memoize((button) => button.isAvailable(selection));\\n        const compact = this.buttonsByNamespace[\\"compact\\"].filter(isAvailable);\\n        const expanded = this.buttonsByNamespace[\\"expanded\\"].filter(isAvailable);\\n        const shouldDisplayCompactToolbar =\\n            // Expanded version is big enough\\n            expanded.length >= MIN_SIZE_FOR_COMPACT &&\\n            // Expanded version is bigger than the compact version\\n            expanded.length > compact.length;\\n        if (shouldDisplayCompactToolbar) {\\n            return new Set(compact);\\n        }\\n        this.state.namespace = \\"expanded\\";\\n        return new Set(expanded);\\n    }\\n\\n    closeToolbar() {\\n        this.overlay.close();\\n        this.isToolbarExpanded = false;\\n    }\\n}\\n\\nclass MobileToolbarOverlay {\\n    constructor(editable) {\\n        this.isOpen = false;\\n        this.overlayId = `mobile_toolbar_${Math.random().toString(16).slice(2)}`;\\n        this.editable = editable;\\n    }\\n\\n    open({ props }) {\\n        props.class = \\"shadow\\";\\n        if (!this.isOpen) {\\n            const modal = this.editable.closest(\\".o_modal_full\\");\\n            if (modal) {\\n                // Same height of the toolbar\\n                modal.style.paddingBottom = \\"40px\\";\\n            }\\n            registry.category(\\"main_components\\").add(this.overlayId, {\\n                Component: ToolbarMobile,\\n                props,\\n            });\\n            this.isOpen = true;\\n        }\\n    }\\n\\n    close() {\\n        const modal = this.editable.closest(\\".o_modal_full\\");\\n        if (modal) {\\n            modal.style.paddingBottom = \\"\\";\\n        }\\n        registry.category(\\"main_components\\").remove(this.overlayId, \\"MobileToolbar\\");\\n        this.isOpen = false;\\n    }\\n}\\n", "import { _t } from \\"@web/core/l10n/translation\\";\\nimport { rpc } from \\"@web/core/network/rpc\\";\\nimport { Plugin } from \\"../plugin\\";\\nimport { VideoSelector } from \\"./media/media_dialog/video_selector\\";\\n\\nexport const YOUTUBE_URL_GET_VIDEO_ID =\\n    /^(?:(?:https?:)?\\\\/\\\\/)?(?:(?:www|m)\\\\.)?(?:youtube\\\\.com|youtu\\\\.be)(?:\\\\/(?:[\\\\w-]+\\\\?v=|embed\\\\/|v\\\\/)?)([^\\\\s?&#]+)(?:\\\\S+)?$/i;\\n\\nexport class YoutubePlugin extends Plugin {\\n    static id = \\"youtube\\";\\n    static dependencies = [\\"history\\", \\"dom\\"];\\n    resources = {\\n        ...(this.config.allowVideo && {\\n            paste_media_url_command_providers: this.getCommandForVideoUrlPaste.bind(this),\\n        }),\\n    };\\n    /**\\n     * @param {string} url\\n     */\\n    getCommandForVideoUrlPaste(url) {\\n        const youtubeUrl = YOUTUBE_URL_GET_VIDEO_ID.exec(url);\\n        if (youtubeUrl) {\\n            // URL is a YouTube video.\\n            return {\\n                title: _t(\\"Embed Youtube Video\\"),\\n                description: _t(\\"Embed the youtube video in the document.\\"),\\n                icon: \\"fa-youtube-play\\",\\n                run: async () => {\\n                    const videoElement = await this.getYoutubeVideoElement(youtubeUrl[0]);\\n                    this.dependencies.dom.insert(videoElement);\\n                    this.dependencies.history.addStep();\\n                },\\n            };\\n        }\\n    }\\n    // @todo @phoenix: Should this be in this plugin?\\n    /**\\n     * @param {string} url\\n     * @returns {HTMLElement} saved video element or undefined if the URL\\n     * is not a valid YouTube video URL.\\n     */\\n    async getYoutubeVideoElement(url) {\\n        if (!URL.canParse(url)) {\\n            return;\\n        }\\n        const parsedUrl = new URL(url);\\n        const urlParams = parsedUrl.searchParams;\\n        const start_from = urlParams.get(\\"start\\") || urlParams.get(\\"t\\");\\n\\n        const autoplay = urlParams.get(\\"autoplay\\") === \\"1\\";\\n        const loop = urlParams.get(\\"loop\\") === \\"1\\";\\n        const hide_controls = urlParams.get(\\"controls\\") === \\"0\\";\\n        const hide_fullscreen = urlParams.get(\\"fs\\") === \\"0\\";\\n\\n        const videoData = await rpc(\\"/html_editor/video_url/data\\", {\\n            video_url: url,\\n            autoplay,\\n            loop,\\n            hide_controls,\\n            hide_fullscreen,\\n            start_from,\\n        });\\n        const savedVideo = this.createVideoElement(videoData);\\n        savedVideo.classList.add(...VideoSelector.mediaSpecificClasses);\\n        return savedVideo;\\n    }\\n\\n    createVideoElement(videoData) {\\n        return VideoSelector.createElements([{ src: videoData.embed_url }])[0];\\n    }\\n}\\n", "const urlParams = new URLSearchParams(window.location.search);\\nconst collaborationDebug = urlParams.get(\\"collaborationDebug\\");\\nconst COLLABORATION_LOCALSTORAGE_KEY = \\"odoo_editor_collaboration_debug\\";\\nif (typeof collaborationDebug === \\"string\\") {\\n    if (collaborationDebug === \\"false\\") {\\n        localStorage.removeItem(\\n            COLLABORATION_LOCALSTORAGE_KEY,\\n            urlParams.get(\\"collaborationDebug\\")\\n        );\\n    } else {\\n        localStorage.setItem(COLLABORATION_LOCALSTORAGE_KEY, urlParams.get(\\"collaborationDebug\\"));\\n    }\\n}\\nconst debugValue = localStorage.getItem(COLLABORATION_LOCALSTORAGE_KEY);\\n\\nconst debugShowLog = [\\"\\", \\"true\\", \\"all\\"].includes(debugValue);\\nconst debugShowNotifications = debugValue === \\"all\\";\\n\\nconst baseNotificationMethods = {\\n    ptp_request: async function (notification) {\\n        const { requestId, requestName, requestPayload, requestTransport } =\\n            notification.notificationPayload;\\n        this._onRequest(\\n            notification.fromPeerId,\\n            requestId,\\n            requestName,\\n            requestPayload,\\n            requestTransport\\n        );\\n    },\\n    ptp_request_result: function (notification) {\\n        const { requestId, result } = notification.notificationPayload;\\n        // If not in _pendingRequestResolver, it means it has timeout.\\n        if (this._pendingRequestResolver[requestId]) {\\n            clearTimeout(this._pendingRequestResolver[requestId].rejectTimeout);\\n            this._pendingRequestResolver[requestId].resolve(result);\\n            delete this._pendingRequestResolver[requestId];\\n        }\\n    },\\n\\n    ptp_join: async function (notification) {\\n        const peerId = notification.fromPeerId;\\n        if (this.peersInfos[peerId] && this.peersInfos[peerId].peerConnection) {\\n            return this.peersInfos[peerId];\\n        }\\n        this._createPeer(peerId);\\n    },\\n\\n    rtc_signal_icecandidate: async function (notification) {\\n        if (debugShowLog) {\\n            console.log(`%creceive candidate`, \\"background: darkgreen; color: white;\\");\\n        }\\n        const peerInfos = this.peersInfos[notification.fromPeerId];\\n        if (\\n            !peerInfos ||\\n            !peerInfos.peerConnection ||\\n            peerInfos.peerConnection.connectionState === \\"closed\\"\\n        ) {\\n            console.groupCollapsed(\\"=== ERROR: Handle Ice Candidate from undefined|closed ===\\");\\n            console.trace(peerInfos);\\n            console.groupEnd();\\n            return;\\n        }\\n        if (!peerInfos.peerConnection.remoteDescription) {\\n            peerInfos.iceCandidateBuffer.push(notification.notificationPayload);\\n        } else {\\n            this._addIceCandidate(peerInfos, notification.notificationPayload);\\n        }\\n    },\\n    rtc_signal_description: async function (notification) {\\n        const description = notification.notificationPayload;\\n        if (debugShowLog) {\\n            console.log(\\n                `%cdescription received:`,\\n                \\"background: blueviolet; color: white;\\",\\n                description\\n            );\\n        }\\n\\n        const peerInfos =\\n            this.peersInfos[notification.fromPeerId] || this._createPeer(notification.fromPeerId);\\n        const pc = peerInfos.peerConnection;\\n\\n        if (!pc || pc.connectionState === \\"closed\\") {\\n            if (debugShowLog) {\\n                console.groupCollapsed(\\"=== ERROR: handle offer ===\\");\\n                console.log(\\n                    \\"An offer has been received for a non-existent peer connection - peer: \\" +\\n                        notification.fromPeerId\\n                );\\n                console.trace(pc && pc.connectionState);\\n                console.groupEnd();\\n            }\\n            return;\\n        }\\n\\n        // Skip if we already have an offer.\\n        if (pc.signalingState === \\"have-remote-offer\\") {\\n            return;\\n        }\\n\\n        // If there is a racing conditing with the signaling offer (two\\n        // being sent at the same time). We need one peer that abort by\\n        // rollbacking to a stable signaling state where the other is\\n        // continuing the process. The peer that is polite is the one that\\n        // will rollback.\\n        const isPolite =\\n            (\\"\\" + notification.fromPeerId).localeCompare(\\"\\" + this._currentPeerId) === 1;\\n        if (debugShowLog) {\\n            console.log(\\n                `%cisPolite: %c${isPolite}`,\\n                \\"background: deepskyblue;\\",\\n                `background:${isPolite ? \\"green\\" : \\"red\\"}`\\n            );\\n        }\\n\\n        const isOfferRacing =\\n            description.type === \\"offer\\" &&\\n            (peerInfos.makingOffer || pc.signalingState !== \\"stable\\");\\n        // If there is a racing conditing with the signaling offer and the\\n        // peer is impolite, we must not process this offer and wait for\\n        // the answer for the signaling process to continue.\\n        if (isOfferRacing && !isPolite) {\\n            if (debugShowLog) {\\n                console.log(\\n                    `%creturn because isOfferRacing && !isPolite. pc.signalingState: ${pc.signalingState}`,\\n                    \\"background: red;\\"\\n                );\\n            }\\n            return;\\n        }\\n        if (debugShowLog) {\\n            console.log(`%cisOfferRacing: ${isOfferRacing}`, \\"background: red;\\");\\n            console.log(`%c SETREMOTEDESCRIPTION`, \\"background: navy; color:white;\\");\\n        }\\n        try {\\n            await pc.setRemoteDescription(description);\\n        } catch (e) {\\n            if (e instanceof DOMException && e.name === \\"InvalidStateError\\") {\\n                console.error(e);\\n                return;\\n            } else {\\n                throw e;\\n            }\\n        }\\n        if (peerInfos.iceCandidateBuffer.length) {\\n            for (const candidate of peerInfos.iceCandidateBuffer) {\\n                await this._addIceCandidate(peerInfos, candidate);\\n            }\\n            peerInfos.iceCandidateBuffer.splice(0);\\n        }\\n        if (description.type === \\"offer\\") {\\n            const answerDescription = await pc.createAnswer();\\n            try {\\n                await pc.setLocalDescription(answerDescription);\\n            } catch (e) {\\n                if (e instanceof DOMException && e.name === \\"InvalidStateError\\") {\\n                    console.error(e);\\n                    return;\\n                } else {\\n                    throw e;\\n                }\\n            }\\n            this.notifyPeer(notification.fromPeerId, \\"rtc_signal_description\\", pc.localDescription);\\n        }\\n    },\\n};\\n\\nexport class PeerToPeer {\\n    constructor(options) {\\n        this.options = options;\\n        this._currentPeerId = this.options.currentPeerId;\\n        if (debugShowLog) {\\n            console.log(\\n                `%c currentPeerId:${this._currentPeerId}`,\\n                \\"background: blue; color: white;\\"\\n            );\\n        }\\n\\n        // peerId -> PeerInfos\\n        this.peersInfos = {};\\n        this._lastRequestId = -1;\\n        this._pendingRequestResolver = {};\\n        this._stopped = false;\\n    }\\n\\n    stop() {\\n        this.closeAllConnections();\\n        this._stopped = true;\\n    }\\n\\n    getConnectedPeerIds() {\\n        return Object.entries(this.peersInfos)\\n            .filter(\\n                ([id, infos]) =>\\n                    infos.peerConnection &&\\n                    infos.peerConnection.iceConnectionState === \\"connected\\" &&\\n                    infos.dataChannel &&\\n                    infos.dataChannel.readyState === \\"open\\"\\n            )\\n            .map(([id]) => id);\\n    }\\n\\n    removePeer(peerId) {\\n        if (debugShowLog) {\\n            console.log(`%c REMOVE PEER ${peerId}`, \\"background: chocolate;\\");\\n        }\\n        this.notifySelf(\\"ptp_remove\\", peerId);\\n        const peerInfos = this.peersInfos[peerId];\\n        if (!peerInfos) {\\n            return;\\n        }\\n        clearTimeout(peerInfos.fallbackTimeout);\\n        clearTimeout(peerInfos.zombieTimeout);\\n        peerInfos.dataChannel && peerInfos.dataChannel.close();\\n        peerInfos.peerConnection && peerInfos.peerConnection.close();\\n        delete this.peersInfos[peerId];\\n    }\\n\\n    closeAllConnections() {\\n        for (const peerId of Object.keys(this.peersInfos)) {\\n            this.notifyAllPeers(\\"ptp_disconnect\\");\\n            this.removePeer(peerId);\\n        }\\n    }\\n\\n    async notifyAllPeers(notificationName, notificationPayload, { transport = \\"server\\" } = {}) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        const transportPayload = {\\n            fromPeerId: this._currentPeerId,\\n            notificationName,\\n            notificationPayload,\\n        };\\n        if (transport === \\"server\\") {\\n            await this.options.broadcastAll(transportPayload);\\n        } else if (transport === \\"rtc\\") {\\n            for (const cliendId of Object.keys(this.peersInfos)) {\\n                this._channelNotify(cliendId, transportPayload);\\n            }\\n        } else {\\n            throw new Error(\\n                `Transport \\"${transport}\\" is not supported. Use \\"server\\" or \\"rtc\\" transport.`\\n            );\\n        }\\n    }\\n\\n    notifyPeer(peerId, notificationName, notificationPayload, { transport = \\"server\\" } = {}) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        if (debugShowNotifications) {\\n            if (notificationName === \\"ptp_request_result\\") {\\n                console.log(\\n                    `%c${Date.now()} - REQUEST RESULT SEND: %c${transport}:${\\n                        notificationPayload.requestId\\n                    }:${this._currentPeerId.slice(\\"-5\\")}:${peerId.slice(\\"-5\\")}`,\\n                    \\"color: #aaa;font-weight:bold;\\",\\n                    \\"color: #aaa;font-weight:normal\\"\\n                );\\n            } else if (notificationName === \\"ptp_request\\") {\\n                console.log(\\n                    `%c${Date.now()} - REQUEST SEND: %c${transport}:${\\n                        notificationPayload.requestName\\n                    }|${notificationPayload.requestId}:${this._currentPeerId.slice(\\n                        \\"-5\\"\\n                    )}:${peerId.slice(\\"-5\\")}`,\\n                    \\"color: #aaa;font-weight:bold;\\",\\n                    \\"color: #aaa;font-weight:normal\\"\\n                );\\n            } else {\\n                console.log(\\n                    `%c${Date.now()} - NOTIFICATION SEND: %c${transport}:${notificationName}:${this._currentPeerId.slice(\\n                        \\"-5\\"\\n                    )}:${peerId.slice(\\"-5\\")}`,\\n                    \\"color: #aaa;font-weight:bold;\\",\\n                    \\"color: #aaa;font-weight:normal\\"\\n                );\\n            }\\n        }\\n        const transportPayload = {\\n            fromPeerId: this._currentPeerId,\\n            toPeerId: peerId,\\n            notificationName,\\n            notificationPayload,\\n        };\\n        if (transport === \\"server\\") {\\n            this.options.broadcastAll(transportPayload);\\n        } else if (transport === \\"rtc\\") {\\n            this._channelNotify(peerId, transportPayload);\\n        } else {\\n            throw new Error(\\n                `Transport \\"${transport}\\" is not supported. Use \\"server\\" or \\"rtc\\" transport.`\\n            );\\n        }\\n    }\\n\\n    notifySelf(notificationName, notificationPayload) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        return this.handleNotification({ notificationName, notificationPayload });\\n    }\\n\\n    handleNotification(notification) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        const isInternalNotification =\\n            typeof notification.fromPeerId === \\"undefined\\" &&\\n            typeof notification.toPeerId === \\"undefined\\";\\n        if (\\n            isInternalNotification ||\\n            (notification.fromPeerId !== this._currentPeerId && !notification.toPeerId) ||\\n            notification.toPeerId === this._currentPeerId\\n        ) {\\n            if (debugShowNotifications) {\\n                if (notification.notificationName === \\"ptp_request_result\\") {\\n                    console.log(\\n                        `%c${Date.now()} - REQUEST RESULT RECEIVE: %c${\\n                            notification.notificationPayload.requestId\\n                        }:${notification.fromPeerId.slice(\\"-5\\")}:${notification.toPeerId.slice(\\n                            \\"-5\\"\\n                        )}`,\\n                        \\"color: #aaa;font-weight:bold;\\",\\n                        \\"color: #aaa;font-weight:normal\\"\\n                    );\\n                } else if (notification.notificationName === \\"ptp_request\\") {\\n                    console.log(\\n                        `%c${Date.now()} - REQUEST RECEIVE: %c${\\n                            notification.notificationPayload.requestName\\n                        }|${\\n                            notification.notificationPayload.requestId\\n                        }:${notification.fromPeerId.slice(\\"-5\\")}:${notification.toPeerId.slice(\\n                            \\"-5\\"\\n                        )}`,\\n                        \\"color: #aaa;font-weight:bold;\\",\\n                        \\"color: #aaa;font-weight:normal\\"\\n                    );\\n                } else {\\n                    console.log(\\n                        `%c${Date.now()} - NOTIFICATION RECEIVE: %c${\\n                            notification.notificationName\\n                        }:${notification.fromPeerId}:${notification.toPeerId}`,\\n                        \\"color: #aaa;font-weight:bold;\\",\\n                        \\"color: #aaa;font-weight:normal\\"\\n                    );\\n                }\\n            }\\n            try {\\n                const baseMethod = baseNotificationMethods[notification.notificationName];\\n                if (baseMethod) {\\n                    return baseMethod.call(this, notification);\\n                }\\n                if (this.options.onNotification) {\\n                    return this.options.onNotification(notification);\\n                }\\n            } catch (error) {\\n                console.groupCollapsed(\\"=== ERROR: On notification in collaboration ===\\");\\n                console.error(error);\\n                console.groupEnd();\\n            }\\n        }\\n    }\\n\\n    requestPeer(peerId, requestName, requestPayload, { transport = \\"server\\" } = {}) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        return new Promise((resolve, reject) => {\\n            const requestId = this._getRequestId();\\n\\n            const abort = (reason) => {\\n                clearTimeout(rejectTimeout);\\n                delete this._pendingRequestResolver[requestId];\\n                reject(new RequestError(reason || \\"Request was aborted.\\"));\\n            };\\n            const rejectTimeout = setTimeout(\\n                () => abort(\\"Request took too long (more than 10 seconds).\\"),\\n                10000\\n            );\\n\\n            this._pendingRequestResolver[requestId] = {\\n                resolve,\\n                rejectTimeout,\\n                abort,\\n            };\\n\\n            this.notifyPeer(\\n                peerId,\\n                \\"ptp_request\\",\\n                {\\n                    requestId,\\n                    requestName,\\n                    requestPayload,\\n                    requestTransport: transport,\\n                },\\n                { transport }\\n            );\\n        });\\n    }\\n    abortCurrentRequests() {\\n        for (const { abort } of Object.values(this._pendingRequestResolver)) {\\n            abort();\\n        }\\n    }\\n    _createPeer(peerId, { makeOffer = true } = {}) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        if (debugShowLog) {\\n            console.log(\\"CREATE CONNECTION with peer id:\\", peerId);\\n        }\\n        this.peersInfos[peerId] = {\\n            makingOffer: false,\\n            iceCandidateBuffer: [],\\n            backoffFactor: 0,\\n        };\\n\\n        if (!navigator.onLine) {\\n            return this.peersInfos[peerId];\\n        }\\n        const pc = new RTCPeerConnection(this.options.peerConnectionConfig);\\n\\n        if (makeOffer) {\\n            pc.onnegotiationneeded = async () => {\\n                if (debugShowLog) {\\n                    console.log(\\n                        `%c NEGONATION NEEDED: ${pc.connectionState}`,\\n                        \\"background: deeppink;\\"\\n                    );\\n                }\\n                try {\\n                    this.peersInfos[peerId].makingOffer = true;\\n                    if (debugShowLog) {\\n                        console.log(\\n                            `%ccreating and sending an offer`,\\n                            \\"background: darkmagenta; color: white;\\"\\n                        );\\n                    }\\n                    const offer = await pc.createOffer();\\n                    // Avoid race condition.\\n                    if (pc.signalingState !== \\"stable\\") {\\n                        return;\\n                    }\\n                    await pc.setLocalDescription(offer);\\n                    this.notifyPeer(peerId, \\"rtc_signal_description\\", pc.localDescription);\\n                } catch (err) {\\n                    console.error(err);\\n                } finally {\\n                    this.peersInfos[peerId].makingOffer = false;\\n                }\\n            };\\n        }\\n        pc.onicecandidate = async (event) => {\\n            if (event.candidate) {\\n                this.notifyPeer(peerId, \\"rtc_signal_icecandidate\\", event.candidate);\\n            }\\n        };\\n        pc.oniceconnectionstatechange = async () => {\\n            if (debugShowLog) {\\n                console.log(\\"ICE STATE UPDATE: \\" + pc.iceConnectionState);\\n            }\\n\\n            switch (pc.iceConnectionState) {\\n                case \\"failed\\":\\n                case \\"closed\\":\\n                    this.removePeer(peerId);\\n                    break;\\n                case \\"disconnected\\":\\n                    if (navigator.onLine) {\\n                        await this._recoverConnection(peerId, {\\n                            delay: 3000,\\n                            reason: \\"ice connection disconnected\\",\\n                        });\\n                    }\\n                    break;\\n                case \\"connected\\":\\n                    this.peersInfos[peerId].backoffFactor = 0;\\n                    break;\\n            }\\n        };\\n        // This event does not work in FF. Let's try with oniceconnectionstatechange if it is sufficient.\\n        pc.onconnectionstatechange = async () => {\\n            if (debugShowLog) {\\n                console.log(\\"CONNECTION STATE UPDATE:\\" + pc.connectionState);\\n            }\\n\\n            switch (pc.connectionState) {\\n                case \\"failed\\":\\n                case \\"closed\\":\\n                    this.removePeer(peerId);\\n                    break;\\n                case \\"disconnected\\":\\n                    if (navigator.onLine) {\\n                        await this._recoverConnection(peerId, {\\n                            delay: 3000,\\n                            reason: \\"connection disconnected\\",\\n                        });\\n                    }\\n                    break;\\n                case \\"connected\\":\\n                case \\"completed\\":\\n                    this.peersInfos[peerId].backoffFactor = 0;\\n                    break;\\n            }\\n        };\\n        pc.onicecandidateerror = async (error) => {\\n            if (debugShowLog) {\\n                console.groupCollapsed(\\"=== ERROR: onIceCandidate ===\\");\\n                console.log(\\n                    \\"connectionState: \\" +\\n                        pc.connectionState +\\n                        \\" - iceState: \\" +\\n                        pc.iceConnectionState\\n                );\\n                console.trace(error);\\n                console.groupEnd();\\n            }\\n            this._recoverConnection(peerId, { delay: 3000, reason: \\"ice candidate error\\" });\\n        };\\n        const dataChannel = pc.createDataChannel(\\"notifications\\", { negotiated: true, id: 1 });\\n        let message = [];\\n        dataChannel.onmessage = (event) => {\\n            if (event.data !== \\"-\\") {\\n                message.push(event.data);\\n            } else {\\n                this.handleNotification(JSON.parse(message.join(\\"\\")));\\n                message = [];\\n            }\\n        };\\n        dataChannel.onopen = (event) => {\\n            this.notifySelf(\\"rtc_data_channel_open\\", {\\n                connectionPeerId: peerId,\\n            });\\n        };\\n\\n        this.peersInfos[peerId].peerConnection = pc;\\n        this.peersInfos[peerId].dataChannel = dataChannel;\\n\\n        return this.peersInfos[peerId];\\n    }\\n    async _addIceCandidate(peerInfos, candidate) {\\n        const rtcIceCandidate = new RTCIceCandidate(candidate);\\n        try {\\n            await peerInfos.peerConnection.addIceCandidate(rtcIceCandidate);\\n        } catch (error) {\\n            // Ignored.\\n            console.groupCollapsed(\\"=== ERROR: ADD ICE CANDIDATE ===\\");\\n            console.trace(error);\\n            console.groupEnd();\\n        }\\n    }\\n\\n    _channelNotify(peerId, transportPayload) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        const peerInfo = this.peersInfos[peerId];\\n        const dataChannel = peerInfo && peerInfo.dataChannel;\\n\\n        if (!dataChannel || dataChannel.readyState !== \\"open\\") {\\n            if (peerInfo && !peerInfo.zombieTimeout) {\\n                if (debugShowLog) {\\n                    console.warn(\\n                        `Impossible to communicate with peer ${peerId}. The connection will be killed in 10 seconds if the datachannel state has not changed.`\\n                    );\\n                }\\n                this._killPotentialZombie(peerId);\\n            }\\n        } else {\\n            const str = JSON.stringify(transportPayload);\\n            const size = str.length;\\n            const maxStringLength = 5000;\\n            let from = 0;\\n            let to = maxStringLength;\\n            while (from < size) {\\n                dataChannel.send(str.slice(from, to));\\n                from = to;\\n                to = to += maxStringLength;\\n            }\\n            dataChannel.send(\\"-\\");\\n        }\\n    }\\n\\n    _getRequestId() {\\n        this._lastRequestId++;\\n        return this._lastRequestId;\\n    }\\n\\n    async _onRequest(fromPeerId, requestId, requestName, requestPayload, requestTransport) {\\n        if (this._stopped) {\\n            return;\\n        }\\n        const requestFunction = this.options.onRequest && this.options.onRequest[requestName];\\n        const result = await requestFunction({\\n            fromPeerId,\\n            requestId,\\n            requestName,\\n            requestPayload,\\n        });\\n        this.notifyPeer(\\n            fromPeerId,\\n            \\"ptp_request_result\\",\\n            { requestId, result },\\n            { transport: requestTransport }\\n        );\\n    }\\n    /**\\n     * Attempts a connection recovery by updating the tracks, which will start\\n     * a new transaction: negotiationneeded -> offer -> answer -> ...\\n     *\\n     * @private\\n     * @param {Object} [param1]\\n     * @param {number} [param1.delay] in ms\\n     * @param {string} [param1.reason]\\n     */\\n    _recoverConnection(peerId, { delay = 0, reason = \\"\\" } = {}) {\\n        if (this._stopped) {\\n            this.removePeer(peerId);\\n            return;\\n        }\\n        const peerInfos = this.peersInfos[peerId];\\n        if (!peerInfos || peerInfos.fallbackTimeout) {\\n            return;\\n        }\\n        const backoffFactor = this.peersInfos[peerId].backoffFactor;\\n        const backoffDelay = delay * Math.pow(2, backoffFactor);\\n        // Stop trying to recover the connection after 10 attempts.\\n        if (backoffFactor > 10) {\\n            if (debugShowLog) {\\n                console.log(\\n                    `%c STOP RTC RECOVERY: impossible to connect to peer ${peerId}: ${reason}`,\\n                    \\"background: darkred; color: white;\\"\\n                );\\n            }\\n            return;\\n        }\\n\\n        peerInfos.fallbackTimeout = setTimeout(async () => {\\n            peerInfos.fallbackTimeout = undefined;\\n            const pc = peerInfos.peerConnection;\\n            if (!pc || pc.iceConnectionState === \\"connected\\") {\\n                return;\\n            }\\n            if ([\\"connected\\", \\"closed\\"].includes(pc.connectionState)) {\\n                return;\\n            }\\n            // hard reset: recreating a RTCPeerConnection\\n            if (debugShowLog) {\\n                console.log(\\n                    `%c RTC RECOVERY: calling back peer ${peerId} to salvage the connection ${pc.iceConnectionState} after ${backoffDelay}ms, reason: ${reason}`,\\n                    \\"background: darkorange; color: white;\\"\\n                );\\n            }\\n            this.removePeer(peerId);\\n            const newPeerInfos = this._createPeer(peerId);\\n            newPeerInfos.backoffFactor = backoffFactor + 1;\\n        }, backoffDelay);\\n    }\\n    // todo: do we try to salvage the connection after killing the zombie ?\\n    // Maybe the salvage should be done when the connection is dropped.\\n    _killPotentialZombie(peerId) {\\n        if (this._stopped) {\\n            this.removePeer(peerId);\\n            return;\\n        }\\n        const peerInfos = this.peersInfos[peerId];\\n        if (!peerInfos || peerInfos.zombieTimeout) {\\n            return;\\n        }\\n\\n        // If there is no connection after 10 seconds, terminate.\\n        peerInfos.zombieTimeout = setTimeout(() => {\\n            if (peerInfos && peerInfos.dataChannel && peerInfos.dataChannel.readyState !== \\"open\\") {\\n                if (debugShowLog) {\\n                    console.log(`%c KILL ZOMBIE ${peerId}`, \\"background: red;\\");\\n                }\\n                this.removePeer(peerId);\\n            } else {\\n                if (debugShowLog) {\\n                    console.log(`%c NOT A ZOMBIE ${peerId}`, \\"background: green;\\");\\n                }\\n            }\\n        }, 10000);\\n    }\\n}\\n\\nexport class RequestError extends Error {\\n    constructor(message) {\\n        super(message);\\n        this.name = \\"RequestError\\";\\n    }\\n}\\n", "import { Plugin } from \\"@html_editor/plugin\\";\\nimport { rpc } from \\"@web/core/network/rpc\\";\\nimport { user } from \\"@web/core/user\\";\\nimport { Mutex } from \\"@web/core/utils/concurrency\\";\\nimport { debounce } from \\"@web/core/utils/timing\\";\\nimport { PeerToPeer, RequestError } from \\"./PeerToPeer\\";\\nimport { ancestors } from \\"@html_editor/utils/dom_traversal\\";\\nimport { childNodeIndex } from \\"@html_editor/utils/position\\";\\n\\n/**\\n * @typedef {Object} CollaborationSelection\\n * @property {import(\\"@html_editor/core/history_plugin\\").SerializedSelection} selection\\n * @property {string} color\\n * @property {string} peerId\\n */\\n\\n// Time to consider a user offline in ms. This fixes the problem of the\\n// navigator closing rtc connection when the mac laptop screen is closed.\\n// const CONSIDER_OFFLINE_TIME = 1000;\\n// Check wether the computer could be offline. This fixes the problem of the\\n// navigator closing rtc connection when the mac laptop screen is closed.\\n// This case happens on Mac OS on every browser when the user close it's laptop\\n// screen. At first, the os/navigator closes all rtc connection, and after some\\n// times, the os/navigator internet goes offline without triggering an\\n// offline/online event.\\n// However, if the laptop screen is open and the connection is properly remove\\n// (e.g. disconnect wifi), the event is properly triggered.\\n// const CHECK_OFFLINE_TIME = 1000;\\n// const PTP_PEER_DISCONNECTED_STATES = [\\"failed\\", \\"closed\\", \\"disconnected\\"];\\n\\n// Time in ms to wait when trying to aggregate snapshots from other peers and\\n// potentially recover from a missing step before trying to apply those\\n// snapshots or recover from the server.\\nconst PTP_MAX_RECOVERY_TIME = 500;\\n\\nconst REQUEST_ERROR = Symbol(\\"REQUEST_ERROR\\");\\n\\n// this is a local cache for ice server descriptions\\nlet ICE_SERVERS = null;\\n\\n/**\\n * @typedef { Object } CollaborationOdooShared\\n * @property { CollaborationOdooPlugin['getPeerMetadata'] } getPeerMetadata\\n */\\n\\nexport class CollaborationOdooPlugin extends Plugin {\\n    static id = \\"collaborationOdoo\\";\\n    static dependencies = [\\"baseContainer\\", \\"history\\", \\"collaboration\\", \\"selection\\"];\\n    static shared = [\\"getPeerMetadata\\"];\\n    resources = {\\n        selectionchange_handlers: debounce(() => {\\n            this.ptp?.notifyAllPeers(\\n                \\"oe_history_set_selection\\",\\n                this.getCurrentCollaborativeSelection(),\\n                {\\n                    transport: \\"rtc\\",\\n                }\\n            );\\n        }, 50),\\n        clean_for_save_handlers: ({ root }) => this.attachHistoryIds(root),\\n        history_missing_parent_step_handlers: this.onHistoryMissingParentStep.bind(this),\\n        history_reset_handlers: this.onReset.bind(this),\\n        step_added_handlers: ({ step }) =>\\n            this.ptp?.notifyAllPeers(\\"oe_history_step\\", step, { transport: \\"rtc\\" }),\\n    };\\n\\n    setup() {\\n        this.isDocumentStale = false;\\n\\n        this.ptpJoined = false;\\n\\n        // Each time a reset of the document is triggered, it is assigned a\\n        // unique identifier. Since resetting the editor involves asynchronous\\n        // requests, it is possible that subsequent resets are triggered before\\n        // the previous one is complete. This property identifies the latest\\n        // reset and can be compared against to cancel the processing of late\\n        // responses from previous resets.\\n        this.lastCollaborationResetId = 0;\\n\\n        // The ID is the latest step ID that the server knows through\\n        // `data-last-history-steps`. We cannot save to the server if we do not\\n        // have that ID in our history ids as it means that our version is\\n        // stale.\\n        this.serverLastStepId =\\n            this.config.content && this.getLastHistoryStepId(this.config.content);\\n\\n        this.setupCollaboration(this.config.collaboration.collaborationChannel);\\n\\n        const collaborativeTrigger = this.config.collaboration.collaborativeTrigger;\\n        this.joinPeerToPeer = this.joinPeerToPeer.bind(this);\\n        if (collaborativeTrigger === \\"start\\") {\\n            this.joinPeerToPeer();\\n        } else if (\\n            collaborativeTrigger === \\"focus\\" ||\\n            typeof collaborativeTrigger === \\"undefined\\"\\n        ) {\\n            // Wait until editor is focused to join the peer to peer network.\\n            this.editable.addEventListener(\\"focus\\", this.joinPeerToPeer);\\n        }\\n\\n        stripHistoryIds(this.editable);\\n    }\\n    destroy() {\\n        this.collaborationStopBus && this.collaborationStopBus();\\n        // If peer to peer is initializing, wait for properly closing it.\\n        if (this.peerToPeerLoading) {\\n            this.peerToPeerLoading.then(() => {\\n                this.stopPeerToPeer();\\n            });\\n        }\\n        // todo: to implement\\n        // clearInterval(this.collaborationInterval);\\n        super.destroy();\\n    }\\n\\n    stopPeerToPeer() {\\n        this.joiningPtp = false;\\n        this.ptpJoined = false;\\n        this.resetCollabRequests();\\n        this.ptp && this.ptp.stop();\\n    }\\n\\n    getCurrentCollaborativeSelection() {\\n        const selection = this.dependencies.selection.getEditableSelection();\\n        return {\\n            selection: this.dependencies.history.serializeSelection(selection),\\n            peerId: this.config.collaboration.peerId,\\n        };\\n    }\\n    setupCollaboration(collaborationChannel) {\\n        const modelName = collaborationChannel.collaborationModelName;\\n        const fieldName = collaborationChannel.collaborationFieldName;\\n        const resId = collaborationChannel.collaborationResId;\\n        const channelName = `editor_collaboration:${modelName}:${fieldName}:${resId}`;\\n\\n        if (\\n            !(modelName && fieldName && resId)\\n            // todo: handle this feature\\n            // || Wysiwyg.activeCollaborationChannelNames.has(channelName)\\n        ) {\\n            return;\\n        }\\n\\n        this.collaborationChannelName = channelName;\\n        this.historyStepsBuffer = [];\\n        // Wysiwyg.activeCollaborationChannelNames.add(channelName);\\n\\n        const collaborationBusListener = (payload) => {\\n            if (\\n                payload.model_name === modelName &&\\n                payload.field_name === fieldName &&\\n                payload.res_id === resId\\n            ) {\\n                if (payload.notificationName === \\"html_field_write\\") {\\n                    this.onServerLastIdUpdate(payload.notificationPayload.last_step_id);\\n                } else if (this.ptpJoined) {\\n                    this.peerToPeerLoading.then(() => this.ptp.handleNotification(payload));\\n                }\\n            }\\n        };\\n        const { busService } = this.config.collaboration;\\n        busService.subscribe(\\"editor_collaboration\\", collaborationBusListener);\\n        busService.addChannel(this.collaborationChannelName);\\n        this.collaborationStopBus = () => {\\n            // Wysiwyg.activeCollaborationChannelNames.delete(this.collaborationChannelName);\\n            busService.unsubscribe(\\"editor_collaboration\\", collaborationBusListener);\\n            busService.deleteChannel(this.collaborationChannelName);\\n        };\\n\\n        this.startCollaborationTime = new Date().getTime();\\n\\n        // this.checkConnectionChange = () => {\\n        //     if (!this.ptp) {\\n        //         return;\\n        //     }\\n        //     if (!navigator.onLine) {\\n        //         this.signalOffline();\\n        //     } else {\\n        //         this.signalOnline();\\n        //     }\\n        // };\\n\\n        // window.addEventListener(\\"online\\", this.checkConnectionChange);\\n        // window.addEventListener(\\"offline\\", this.checkConnectionChange);\\n\\n        // this.collaborationInterval = setInterval(async () => {\\n        //     if (this.offlineTimeout || this.preSavePromise || !this.ptp) {\\n        //         return;\\n        //     }\\n\\n        //     const peersInfos = Object.values(this.ptp.peersInfos);\\n        //     const couldBeDisconnected =\\n        //         Boolean(peersInfos.length) &&\\n        //         peersInfos.every((x) =>\\n        //             PTP_PEER_DISCONNECTED_STATES.includes(\\n        //                 x.peerConnection && x.peerConnection.connectionState\\n        //             )\\n        //         );\\n\\n        //     if (couldBeDisconnected) {\\n        //         this.offlineTimeout = setTimeout(() => {\\n        //             this.signalOffline();\\n        //         }, CONSIDER_OFFLINE_TIME);\\n        //     }\\n        // }, CHECK_OFFLINE_TIME);\\n\\n        const loadPeerToPeer = async () => {\\n            if (!ICE_SERVERS) {\\n                ICE_SERVERS = await rpc(\\"/html_editor/get_ice_servers\\");\\n            }\\n\\n            let iceServers = ICE_SERVERS;\\n            if (!iceServers.length) {\\n                iceServers = [\\n                    {\\n                        urls: [\\"stun:stun1.l.google.com:19302\\", \\"stun:stun2.l.google.com:19302\\"],\\n                    },\\n                ];\\n            }\\n            this.iceServers = iceServers;\\n\\n            this.ptp = this.getNewPtp();\\n        };\\n\\n        this.peerToPeerLoading = loadPeerToPeer();\\n    }\\n\\n    getNewPtp() {\\n        const rpcMutex = new Mutex();\\n        const { collaborationChannel } = this.config.collaboration;\\n        const modelName = collaborationChannel.collaborationModelName;\\n        const fieldName = collaborationChannel.collaborationFieldName;\\n        const resId = collaborationChannel.collaborationResId;\\n\\n        // Wether or not the history has been sent or received at least\\n        // once.\\n        this.historySyncAtLeastOnce = false;\\n\\n        return new PeerToPeer({\\n            peerConnectionConfig: { iceServers: this.iceServers },\\n            currentPeerId: this.config.collaboration.peerId,\\n            broadcastAll: (rpcData) =>\\n                rpcMutex.exec(async () =>\\n                    rpc(\\"/html_editor/bus_broadcast\\", {\\n                        model_name: modelName,\\n                        field_name: fieldName,\\n                        res_id: resId,\\n                        bus_data: rpcData,\\n                    })\\n                ),\\n            onRequest: {\\n                get_peer_metadata: this.getMetadata.bind(this),\\n                get_missing_steps: (params) =>\\n                    this.dependencies.collaboration.historyGetMissingSteps(params.requestPayload),\\n                get_history_from_snapshot: () => this.getHistorySnapshot(),\\n                get_collaborative_selection: () => this.getCurrentCollaborativeSelection(),\\n                recover_document: (params) => {\\n                    const { serverDocumentId, fromStepId } = params.requestPayload;\\n                    if (\\n                        !this.dependencies.collaboration.getBranchIds().includes(serverDocumentId)\\n                    ) {\\n                        return;\\n                    }\\n                    return {\\n                        missingSteps: this.dependencies.collaboration.historyGetMissingSteps({\\n                            fromStepId,\\n                        }),\\n                        snapshot: this.getHistorySnapshot(),\\n                    };\\n                },\\n            },\\n            onNotification: async (notification) => {\\n                this.dispatchTo(\\"collaboration_notification_handlers\\", notification);\\n                let { fromPeerId, notificationName, notificationPayload } = notification;\\n                switch (notificationName) {\\n                    case \\"ptp_remove\\":\\n                        // todo: to implement\\n                        // this.odooEditor.multiselectionRemove(notificationPayload);\\n                        break;\\n                    case \\"ptp_disconnect\\":\\n                        this.ptp.removePeer(fromPeerId);\\n                        // todo: to implement\\n                        // this.odooEditor.multiselectionRemove(fromPeerId);\\n                        break;\\n                    case \\"rtc_data_channel_open\\": {\\n                        fromPeerId = notificationPayload.connectionPeerId;\\n                        const metadata = await this.requestPeer(\\n                            fromPeerId,\\n                            \\"get_peer_metadata\\",\\n                            undefined,\\n                            { transport: \\"rtc\\" }\\n                        );\\n                        if (metadata === REQUEST_ERROR) {\\n                            return;\\n                        }\\n\\n                        this.ptp.peersInfos[fromPeerId].metadata = metadata;\\n\\n                        if (!this.historySyncAtLeastOnce) {\\n                            const localPeer = {\\n                                id: this.config.collaboration.peerId,\\n                                startTime: this.startCollaborationTime,\\n                            };\\n                            const remotePeer = {\\n                                id: fromPeerId,\\n                                startTime: metadata.startTime,\\n                            };\\n                            if (isPeerFirst(localPeer, remotePeer)) {\\n                                this.historySyncAtLeastOnce = true;\\n                                this.historySyncFinished = true;\\n                            } else {\\n                                this.resetCollabRequests();\\n                                const response = await this.resetFromPeer(\\n                                    fromPeerId,\\n                                    this.lastCollaborationResetId\\n                                );\\n                                if (response === REQUEST_ERROR) {\\n                                    return;\\n                                }\\n                            }\\n                        } else {\\n                            // Make both send their last step to each other to\\n                            // ensure they are in sync.\\n                            this.ptp.notifyAllPeers(\\n                                \\"oe_history_step\\",\\n                                this.dependencies.history.getHistorySteps().at(-1),\\n                                { transport: \\"rtc\\" }\\n                            );\\n                            this.resetCollaborativeSelection(fromPeerId);\\n                        }\\n                        break;\\n                    }\\n                    case \\"oe_history_step\\":\\n                        if (this.historySyncFinished) {\\n                            this.dependencies.collaboration.onExternalHistorySteps([\\n                                notificationPayload,\\n                            ]);\\n                        } else {\\n                            this.historyStepsBuffer.push(notificationPayload);\\n                        }\\n                        break;\\n                    case \\"oe_history_set_selection\\": {\\n                        const peer = this.ptp.peersInfos[fromPeerId];\\n                        if (!peer) {\\n                            return;\\n                        }\\n                        const selection = notificationPayload;\\n                        this.onExternalMultiselectionUpdate(selection);\\n                        break;\\n                    }\\n                }\\n            },\\n        });\\n    }\\n    /**\\n     * @param {string} peerId\\n     */\\n    getPeerMetadata(peerId) {\\n        return this.ptp.peersInfos[peerId]?.metadata;\\n    }\\n    /**\\n     * @param {CollaborationSelection} selection\\n     */\\n    onExternalMultiselectionUpdate(selection) {\\n        this.dispatchTo(\\"collaborative_selection_update_handlers\\", selection);\\n    }\\n\\n    async requestPeer(peerId, requestName, requestPayload, params) {\\n        return this.ptp.requestPeer(peerId, requestName, requestPayload, params).catch((e) => {\\n            if (e instanceof RequestError) {\\n                return REQUEST_ERROR;\\n            } else {\\n                throw e;\\n            }\\n        });\\n    }\\n    getMetadata() {\\n        const metadatas = {\\n            startTime: this.startCollaborationTime,\\n            peerName: user.name,\\n        };\\n        for (const cb of this.getResource(\\"collaboration_peer_metadata_providers\\")) {\\n            Object.assign(metadatas, cb());\\n        }\\n        return metadatas;\\n    }\\n    /**\\n     * Update the server document last step id and recover from a stale document\\n     * if this peer does not have that step in its history.\\n     */\\n    onServerLastIdUpdate(last_step_id) {\\n        this.serverLastStepId = last_step_id;\\n        // Check if the current document is stale.\\n        this.isDocumentStale = this.isLastDocumentStale();\\n        if (this.isDocumentStale && this.ptpJoined) {\\n            return this.recoverFromStaleDocument();\\n        } else if (this.isDocumentStale && this.joiningPtp) {\\n            // In case there is a stale document while a previous recovery is\\n            // ongoing.\\n            this.resetCollabRequests();\\n            this.joinPeerToPeer();\\n        }\\n    }\\n\\n    joinPeerToPeer() {\\n        this.editable.removeEventListener(\\"focus\\", this.joinPeerToPeer);\\n        if (this.peerToPeerLoading) {\\n            return this.peerToPeerLoading.then(async () => {\\n                this.joiningPtp = true;\\n                if (this.isDocumentStale) {\\n                    const success = await this.resetFromServerAndResyncWithPeers();\\n                    if (!success) {\\n                        return;\\n                    }\\n                }\\n                this.ptp.notifyAllPeers(\\"ptp_join\\");\\n                this.joiningPtp = false;\\n                this.ptpJoined = true;\\n            });\\n        }\\n    }\\n    isLastDocumentStale() {\\n        if (!this.serverLastStepId) {\\n            return false;\\n        }\\n        return !this.dependencies.collaboration.getBranchIds().includes(this.serverLastStepId);\\n    }\\n\\n    /**\\n     * Try to recover from a stale document.\\n     *\\n     * The strategy is:\\n     *\\n     * 1.  Try to get a converging document from the other peers.\\n     *\\n     * 1.1 By recovery from missing steps: it is the best possible case of\\n     *     retrieval.\\n     *\\n     * 1.2 By recovery from snapshot: it reset the whole editor (destroying\\n     *     changes and selection made by the user).\\n     *\\n     * 2. Reset from the server:\\n     *    If the recovery from the other peers fails, reset from the server.\\n     *\\n     *    As we know we have a stale document, we need to reset it at least from\\n     *    the server. We shouldn't wait too long for peers to respond because\\n     *    the longer we wait for an unresponding peer, the longer a user can\\n     *    edit a stale document.\\n     *\\n     *    The peers timeout is set to PTP_MAX_RECOVERY_TIME.\\n     */\\n    async recoverFromStaleDocument() {\\n        return new Promise((resolve) => {\\n            // 1. Try to recover a converging document from other peers.\\n            const resetCollabCount = this.lastCollaborationResetId;\\n\\n            const allPeers = this.getPtpPeers().map((peer) => peer.id);\\n\\n            if (allPeers.length === 0) {\\n                if (this.isDocumentStale) {\\n                    this.showConflictDialog();\\n                    resolve();\\n                    return this.resetFromServerAndResyncWithPeers();\\n                }\\n            }\\n\\n            let hasRetrievalBudgetTimeout = false;\\n            const snapshots = [];\\n            let nbPendingResponses = allPeers.length;\\n\\n            const success = () => {\\n                resolve();\\n                clearTimeout(timeout);\\n            };\\n\\n            for (const peerId of allPeers) {\\n                this.requestPeer(\\n                    peerId,\\n                    \\"recover_document\\",\\n                    {\\n                        serverDocumentId: this.serverLastStepId,\\n                        fromStepId: this.dependencies.collaboration.getBranchIds().at(-1),\\n                    },\\n                    { transport: \\"rtc\\" }\\n                ).then((response) => {\\n                    nbPendingResponses--;\\n                    if (\\n                        response === REQUEST_ERROR ||\\n                        resetCollabCount !== this.lastCollaborationResetId ||\\n                        hasRetrievalBudgetTimeout ||\\n                        !response ||\\n                        !this.isDocumentStale\\n                    ) {\\n                        if (nbPendingResponses <= 0) {\\n                            processSnapshots();\\n                        }\\n                        return;\\n                    }\\n                    this.processMissingSteps(response.missingSteps);\\n                    this.isDocumentStale = this.isLastDocumentStale();\\n                    snapshots.push(response.snapshot);\\n                    if (nbPendingResponses < 1) {\\n                        processSnapshots();\\n                    }\\n                });\\n            }\\n\\n            // Only process the snapshots after having received a response from all\\n            // the peers or after PTP_MAX_RECOVERY_TIME in order to try to recover\\n            // from missing steps.\\n            const processSnapshots = async () => {\\n                this.isDocumentStale = this.isLastDocumentStale();\\n                if (!this.isDocumentStale) {\\n                    return success();\\n                }\\n                if (snapshots[0]) {\\n                    this.showConflictDialog();\\n                }\\n                for (const snapshot of snapshots) {\\n                    this.applySnapshot(snapshot);\\n                    this.isDocumentStale = this.isLastDocumentStale();\\n                    // Prevent reseting from another snapshot if the document\\n                    // converge.\\n                    if (!this.isDocumentStale) {\\n                        return success();\\n                    }\\n                }\\n\\n                // 2. If the document is still stale, try to recover from the server.\\n                if (this.isDocumentStale) {\\n                    this.showConflictDialog();\\n                    await this.resetFromServerAndResyncWithPeers();\\n                }\\n\\n                success();\\n            };\\n\\n            // Wait PTP_MAX_RECOVERY_TIME to retrieve data from other peers to\\n            // avoid reseting from the server if possible.\\n            const timeout = setTimeout(() => {\\n                if (resetCollabCount !== this.lastCollaborationResetId) {\\n                    return;\\n                }\\n                hasRetrievalBudgetTimeout = true;\\n                this.onRecoveryPeerTimeout(processSnapshots);\\n            }, PTP_MAX_RECOVERY_TIME);\\n        });\\n    }\\n\\n    /**\\n     * Get peer to peer peers.\\n     */\\n    getPtpPeers() {\\n        const peers = Object.entries(this.ptp.peersInfos).map(([peerId, peerInfo]) => ({\\n            id: peerId,\\n            ...peerInfo,\\n        }));\\n        return peers.sort((a, b) => (isPeerFirst(a, b) ? -1 : 1));\\n    }\\n\\n    getLastHistoryStepId(value) {\\n        const matchId = value.match(/data-last-history-steps=\\"[0-9,]*?([0-9]+)\\"/);\\n        return matchId && matchId[1];\\n    }\\n\\n    resetCollabRequests() {\\n        this.lastCollaborationResetId++;\\n        // By aborting the current requests from ptp, we ensure that the ongoing\\n        // `Wysiwyg.requestPeer` will return REQUEST_ERROR. Most requests that\\n        // calls `Wysiwyg.requestPeer` might want to check if the response is\\n        // REQUEST_ERROR.\\n        this.ptp && this.ptp.abortCurrentRequests();\\n    }\\n    /**\\n     * Reset the document from the server and resync with the peers.\\n     */\\n    async resetFromServerAndResyncWithPeers() {\\n        let collaborationResetId = this.lastCollaborationResetId;\\n        const record = await this.getCurrentRecord();\\n        if (collaborationResetId !== this.lastCollaborationResetId) {\\n            return;\\n        }\\n\\n        const content =\\n            record[this.config.collaboration.collaborationChannel.collaborationFieldName];\\n        const lastHistoryId = content && this.getLastHistoryStepId(content);\\n        // If a change was made in the document while retrieving it, the\\n        // lastHistoryId will be different if the odoo bus did not have time to\\n        // notify the user.\\n        if (this.serverLastStepId !== lastHistoryId) {\\n            // todo: instrument it to ensure it never happens\\n            throw new Error(\\n                \\"Concurency detected while recovering from a stale document. The last history id of the server is different from the history id received by the html_field_write event.\\"\\n            );\\n        }\\n\\n        this.isDocumentStale = false;\\n        if (content) {\\n            // content here is trusted\\n            this.editable.innerHTML = content;\\n        } else {\\n            this.editable.replaceChildren(this.dependencies.baseContainer.createBaseContainer());\\n        }\\n        stripHistoryIds(this.editable);\\n        this.dispatchTo(\\"normalize_handlers\\", this.editable);\\n\\n        this.dependencies.history.reset(content);\\n\\n        // After resetting from the server, try to resynchronise with a peer as\\n        // if it was the first time connecting to a peer in order to retrieve a\\n        // proper snapshot (e.g. This case could arise if we tried to recover\\n        // from a peer but the timeout (PTP_MAX_RECOVERY_TIME) was reached\\n        // before receiving a response).\\n        this.historySyncAtLeastOnce = false;\\n        this.resetCollabRequests();\\n        collaborationResetId = this.lastCollaborationResetId;\\n        this.startCollaborationTime = new Date().getTime();\\n        await Promise.all(\\n            this.getPtpPeers().map((peer) =>\\n                // Reset from the fastest peer. The first peer to reset will set\\n                // this.historySyncAtLeastOnce to true canceling the other peers\\n                // resets.\\n                this.resetFromPeer(peer.id, collaborationResetId)\\n            )\\n        );\\n        return true;\\n    }\\n    onReset(content) {\\n        // This ID correspond to the peer that initiated the document and set\\n        // the initial oid for all nodes in the tree. It is not the same as\\n        // document that had a step id at some point. If a step comes from a\\n        // different history, we should not apply it.\\n        this.historyShareId = Math.floor(Math.random() * Math.pow(2, 52)).toString();\\n\\n        const lastStepId = content && content.match(/data-last-history-steps=\\"([\\\\d,]+)\\"/)?.[1];\\n        if (lastStepId) {\\n            this.dependencies.collaboration.setInitialBranchStepId(lastStepId);\\n        }\\n    }\\n\\n    /**\\n     * Process missing steps received from a peer.\\n     *\\n     * @private\\n     * @param {Array<Object>|-1} missingSteps\\n     * @return {Promise<boolean>} true if missing steps have been processed\\n     */\\n    async processMissingSteps(missingSteps) {\\n        // If missing steps === -1, it means that either:\\n        // - the step.peerId has a stale document\\n        // - the step.peerId has a snapshot and does not includes the step in\\n        //   its history\\n        // - if another share history id\\n        //   - because the step.peerId has reset from the server and\\n        //     step.peerId is not synced with this peer\\n        //   - because the step.peerId is in a network partition\\n        if (missingSteps === -1 || !missingSteps.length) {\\n            return false;\\n        }\\n        this.dependencies.collaboration.onExternalHistorySteps(missingSteps);\\n        return true;\\n    }\\n    applySnapshot(snapshot) {\\n        const { steps, historyIds, historyShareId } = snapshot;\\n        // If there is no serverLastStepId, it means that we use a document\\n        // that is not versionned yet.\\n        const isStaleDocument =\\n            this.serverLastStepId && !historyIds.includes(this.serverLastStepId);\\n        if (isStaleDocument) {\\n            return;\\n        }\\n        this.historyShareId = historyShareId;\\n        this.historySyncAtLeastOnce = true;\\n        this.dependencies.collaboration.resetFromSteps(steps, historyIds);\\n\\n        // todo: ensure that if the selection was not in the editable before the\\n        // reset, it remains where it was after applying the snapshot.\\n        return true;\\n    }\\n\\n    /**\\n     * Callback for when the timeout PTP_MAX_RECOVERY_TIME fires.\\n     *\\n     * Used to be hooked in tests.\\n     *\\n     * @param {Function} processSnapshots The snapshot processing function.\\n     */\\n    async onRecoveryPeerTimeout(processSnapshots) {\\n        processSnapshots();\\n    }\\n    showConflictDialog() {\\n        // todo: implement conflict dialog\\n        // if (this.conflictDialogOpened) {\\n        //     return;\\n        // }\\n        // const content = markup(this.odooEditor.editable.cloneNode(true).outerHTML);\\n        // this.conflictDialogOpened = true;\\n        // this.env.services.dialog.add(ConflictDialog, {\\n        //     content,\\n        //     close: () => (this.conflictDialogOpened = false),\\n        // });\\n    }\\n\\n    getHistorySnapshot() {\\n        return Object.assign({}, this.dependencies.collaboration.getSnapshotSteps(), {\\n            historyShareId: this.historyShareId,\\n        });\\n    }\\n\\n    async resetFromPeer(fromPeerId, resetCollabCount) {\\n        this.historySyncFinished = false;\\n        this.historyStepsBuffer = [];\\n        const snapshot = await this.requestPeer(\\n            fromPeerId,\\n            \\"get_history_from_snapshot\\",\\n            undefined,\\n            { transport: \\"rtc\\" }\\n        );\\n        if (snapshot === REQUEST_ERROR) {\\n            return REQUEST_ERROR;\\n        }\\n        if (resetCollabCount !== this.lastCollaborationResetId) {\\n            return;\\n        }\\n        // Ensure that the history hasn't been synced by another peer before\\n        // this `get_history_from_snapshot` finished.\\n        if (this.historySyncAtLeastOnce) {\\n            return;\\n        }\\n        const selection = this.dependencies.selection.getEditableSelection();\\n        let anchorNodeIndexPath = this._getNodeIndexPath(selection.anchorNode);\\n        let anchorOffset = selection.anchorOffset;\\n        if (selection.anchorNode === this.editable) {\\n            anchorNodeIndexPath = this._getNodeIndexPath(this.editable.firstChild);\\n            anchorOffset = 0;\\n        }\\n        const applied = this.applySnapshot(snapshot);\\n        if (!applied) {\\n            return;\\n        }\\n        const anchorNode = this._getNodeFromIndexPath(anchorNodeIndexPath);\\n        if (\\n            this.dependencies.selection.isSelectionInEditable({ anchorNode, focusNode: anchorNode })\\n        ) {\\n            this.dependencies.selection.setSelection({\\n                anchorNode,\\n                anchorOffset,\\n            });\\n        }\\n        this.historySyncFinished = true;\\n        // In case there are steps received in the meantime, process them.\\n        if (this.historyStepsBuffer.length) {\\n            this.dependencies.collaboration.onExternalHistorySteps(this.historyStepsBuffer);\\n            this.historyStepsBuffer = [];\\n        }\\n        this.editable.dispatchEvent(new CustomEvent(\\"onHistoryResetFromPeer\\"));\\n        this.resetCollaborativeSelection(fromPeerId);\\n    }\\n\\n    async resetCollaborativeSelection(fromPeerId) {\\n        const remoteSelection = await this.requestPeer(\\n            fromPeerId,\\n            \\"get_collaborative_selection\\",\\n            undefined,\\n            { transport: \\"rtc\\" }\\n        );\\n        if (remoteSelection === REQUEST_ERROR) {\\n            return;\\n        }\\n        if (remoteSelection) {\\n            this.onExternalMultiselectionUpdate(remoteSelection);\\n        }\\n    }\\n    async onHistoryMissingParentStep({ step, fromStepId }) {\\n        if (!this.ptp) {\\n            return;\\n        }\\n        const missingSteps = await this.requestPeer(\\n            step.peerId,\\n            \\"get_missing_steps\\",\\n            {\\n                fromStepId: fromStepId,\\n                toStepId: step.id,\\n            },\\n            { transport: \\"rtc\\" }\\n        );\\n        if (missingSteps === REQUEST_ERROR) {\\n            return;\\n        }\\n        this.processMissingSteps(\\n            Array.isArray(missingSteps) ? missingSteps.concat(step) : missingSteps\\n        );\\n    }\\n    async getCurrentRecord() {\\n        const [record] = await this.config.collaboration.ormService.read(\\n            this.config.collaboration.collaborationChannel.collaborationModelName,\\n            [this.config.collaboration.collaborationChannel.collaborationResId],\\n            [this.config.collaboration.collaborationChannel.collaborationFieldName]\\n        );\\n        return record;\\n    }\\n    attachHistoryIds(editable) {\\n        const historyIds = this.dependencies.collaboration.getBranchIds().join(\\",\\");\\n        const firstChild = editable.children[0];\\n        if (firstChild) {\\n            firstChild.setAttribute(\\"data-last-history-steps\\", historyIds);\\n        }\\n    }\\n\\n    /**\\n     * Generates the path to a node as an array of indices, relative to a given ancestor.\\n     *\\n     * @param {Node} node - The node to trace the path for.\\n     * @returns {number[]} The path as an array of child indices.\\n     */\\n    _getNodeIndexPath(node) {\\n        return [node, ...ancestors(node, this.editable)].map((ancestor) =>\\n            childNodeIndex(ancestor)\\n        );\\n    }\\n    /**\\n     * Finds a node in the DOM based on a path of child indices.\\n     *\\n     * @param {number[]} indexPath - The path as an array of child indices.\\n     * @returns {Node|undefined} The node at the specified path, or null if not found.\\n     */\\n    _getNodeFromIndexPath(indexPath) {\\n        return indexPath.reduceRight(\\n            (node, index) => node?.childNodes?.[index],\\n            this.editable.parentElement\\n        );\\n    }\\n}\\n\\n/**\\n * Check wether peerA is before peerB.\\n */\\nfunction isPeerFirst(peerA, peerB) {\\n    if (peerA.startTime === peerB.startTime) {\\n        return peerA.id.localeCompare(peerB.id) === -1;\\n    }\\n    if (peerA.startTime === undefined || peerB.startTime === undefined) {\\n        return Boolean(peerA.startTime);\\n    } else {\\n        return peerA.startTime < peerB.startTime;\\n    }\\n}\\n\\nexport function stripHistoryIds(element) {\\n    element\\n        .querySelectorAll(\\"[data-last-history-steps]\\")\\n        .forEach((el) => el.removeAttribute(\\"data-last-history-steps\\"));\\n}\\n", "import { Plugin } from \\"@html_editor/plugin\\";\\n\\n// 60 seconds\\nexport const HISTORY_SNAPSHOT_INTERVAL = 1000 * 60;\\n// 10 seconds\\nconst HISTORY_SNAPSHOT_BUFFER_TIME = 1000 * 10;\\n\\n/**\\n * @typedef { Object } CollaborationPluginConfig\\n * @property { string } peerId\\n *\\n * @typedef { import(\\"../../core/history_plugin\\").HistoryStep } HistoryStep\\n */\\n\\n/**\\n * @typedef { Object } CollaborationShared\\n * @property { CollaborationPlugin['getBranchIds'] } getBranchIds\\n * @property { CollaborationPlugin['getSnapshotSteps'] } getSnapshotSteps\\n * @property { CollaborationPlugin['historyGetMissingSteps'] } historyGetMissingSteps\\n * @property { CollaborationPlugin['onExternalHistorySteps'] } onExternalHistorySteps\\n * @property { CollaborationPlugin['resetFromSteps'] } resetFromSteps\\n * @property { CollaborationPlugin['setInitialBranchStepId'] } setInitialBranchStepId\\n */\\n\\nexport class CollaborationPlugin extends Plugin {\\n    static id = \\"collaboration\\";\\n    static dependencies = [\\"history\\", \\"selection\\", \\"sanitize\\"];\\n    resources = {\\n        /** Handlers */\\n        history_cleaned_handlers: this.onHistoryClean.bind(this),\\n        history_reset_handlers: this.onHistoryReset.bind(this),\\n        step_added_handlers: ({ step }) => this.onStepAdded(step),\\n\\n        /** Overrides */\\n        set_attribute_overrides: this.setAttribute.bind(this),\\n\\n        history_step_processors: this.processHistoryStep.bind(this),\\n        unreversible_step_predicates: this.isUnreversibleStep.bind(this),\\n    };\\n    static shared = [\\n        \\"getBranchIds\\",\\n        \\"getSnapshotSteps\\",\\n        \\"historyGetMissingSteps\\",\\n        \\"onExternalHistorySteps\\",\\n        \\"resetFromSteps\\",\\n        \\"setInitialBranchStepId\\",\\n    ];\\n\\n    /** @type { CollaborationPluginConfig['peerId'] } */\\n    peerId = null;\\n\\n    setup() {\\n        this.peerId = this.config.collaboration.peerId;\\n        if (!this.peerId) {\\n            throw new Error(\\"The collaboration plugin requires a peerId\\");\\n        }\\n        this._snapshotInterval = setInterval(() => {\\n            this.makeSnapshot();\\n        }, HISTORY_SNAPSHOT_INTERVAL);\\n    }\\n\\n    destroy() {\\n        super.destroy();\\n        clearInterval(this._snapshotInterval);\\n        this._snapshotInterval = false;\\n    }\\n\\n    onHistoryClean() {\\n        this.branchStepIds = [];\\n    }\\n    onHistoryReset() {\\n        const firstStep = this.dependencies.history.getHistorySteps()[0];\\n        this.snapshots = [{ step: firstStep }];\\n    }\\n    /**\\n     * @param {HistoryStep} step\\n     */\\n    isUnreversibleStep(step) {\\n        return step.peerId !== this.peerId;\\n    }\\n    /**\\n     * @param {Node} node\\n     * @param {string} attributeName\\n     * @param {string} attributeValue\\n     */\\n    setAttribute(node, attributeName, attributeValue) {\\n        if (attributeValue) {\\n            this.safeSetAttribute(node, attributeName, attributeValue);\\n            return true;\\n        }\\n    }\\n\\n    /**\\n     * Get all the history ids for the current history branch.\\n     */\\n    getBranchIds() {\\n        const steps = this.dependencies.history.getHistorySteps();\\n        return (this.initialBranchStepId || \\"\\")\\n            .split(\\",\\")\\n            .concat(this.branchStepIds)\\n            .concat(steps.map((s) => s.id));\\n    }\\n    /**\\n     * Safely set an attribute on a node.\\n     * @param {HTMLElement} node\\n     * @param {string} attributeName\\n     * @param {string} attributeValue\\n     */\\n    safeSetAttribute(node, attributeName, attributeValue) {\\n        const clone = this.document.createElement(node.tagName);\\n        clone.setAttribute(attributeName, attributeValue);\\n        this.dependencies.sanitize.sanitize(clone);\\n        if (clone.hasAttribute(attributeName)) {\\n            node.setAttribute(attributeName, clone.getAttribute(attributeName));\\n        } else {\\n            node.removeAttribute(attributeName);\\n        }\\n    }\\n\\n    /**\\n     * Apply external steps coming from the collaboration.\\n     *\\n     * @param {Object} newSteps External steps to be applied\\n     */\\n    onExternalHistorySteps(newSteps) {\\n        let stepIndex = 0;\\n        const selectionData = this.dependencies.selection.getSelectionData();\\n\\n        const steps = this.dependencies.history.getHistorySteps();\\n        for (const newStep of newSteps) {\\n            // todo: add a test that no 2 history_missing_parent_step_handlers\\n            // are called in same stack.\\n            const insertIndex = this.getInsertStepIndex(steps, newStep);\\n            if (typeof insertIndex === \\"undefined\\") {\\n                continue;\\n            }\\n            this.dependencies.history.addExternalStep(newStep, insertIndex);\\n            stepIndex++;\\n        }\\n        if (selectionData.documentSelectionIsInEditable) {\\n            this.dependencies.selection.rectifySelection(selectionData.editableSelection);\\n        }\\n\\n        this.dispatchTo(\\"external_history_step_handlers\\");\\n\\n        // todo: ensure that if the selection was not in the editable before the\\n        // reset, it remains where it was after applying the snapshot.\\n\\n        if (stepIndex) {\\n            this.config.onChange?.();\\n        }\\n    }\\n\\n    /**\\n     * @param {HistoryStep[]} steps\\n     * @param {HistoryStep} newStep\\n     */\\n    getInsertStepIndex(steps, newStep) {\\n        let index = steps.length - 1;\\n        while (index >= 0 && steps[index].id !== newStep.previousStepId) {\\n            // Skip steps that are already in the list.\\n            if (steps[index].id === newStep.id) {\\n                return;\\n            }\\n            index--;\\n        }\\n\\n        // When the previousStepId is not present in the steps it\\n        // could be either:\\n        // - the previousStepId is before a snapshot of the same history\\n        // - the previousStepId has not been received because peers were\\n        //   disconnected at that time\\n        // - the previousStepId is in another history (in case two totally\\n        //   differents `steps` (but it should not arise)).\\n        if (index < 0) {\\n            const historySteps = steps;\\n            let index = historySteps.length - 1;\\n            // Get the last known step that we are sure the missing step\\n            // peer has. It could either be a step that has the same\\n            // peerId or the first step.\\n            while (index !== 0) {\\n                if (historySteps[index].peerId === newStep.peerId) {\\n                    break;\\n                }\\n                index--;\\n            }\\n            const fromStepId = historySteps[index].id;\\n            this.dispatchTo(\\"history_missing_parent_step_handlers\\", {\\n                step: newStep,\\n                fromStepId: fromStepId,\\n            });\\n            return;\\n        }\\n\\n        let concurentSteps = [];\\n        index++;\\n        while (index < steps.length) {\\n            if (steps[index].previousStepId === newStep.previousStepId) {\\n                if (steps[index].id.localeCompare(newStep.id) === 1) {\\n                    break;\\n                } else {\\n                    concurentSteps = [steps[index].id];\\n                }\\n            } else {\\n                if (concurentSteps.includes(steps[index].previousStepId)) {\\n       