;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;ACjCA;;;;;;;;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;AClIA;;;;;;;;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;ACzGA;;;;;;;;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA", "sourcesContent": ["// @odoo-module ignore\\n\\n//-----------------------------------------------------------------------------\\n// Odoo Web Boostrap Code\\n//-----------------------------------------------------------------------------\\n\\n(function (odoo) {\\n    \\"use strict\\";\\n\\n    if (odoo.loader) {\\n        // Allows for duplicate calls to `module_loader`: only the first one is\\n        // executed.\\n        return;\\n    }\\n\\n    class ModuleLoader {\\n        /** @type {OdooModuleLoader[\\"bus\\"]} */\\n        bus = new EventTarget();\\n        /** @type {OdooModuleLoader[\\"checkErrorProm\\"]} */\\n        checkErrorProm = null;\\n        /** @type {OdooModuleLoader[\\"factories\\"]} */\\n        factories = new Map();\\n        /** @type {OdooModuleLoader[\\"failed\\"]} */\\n        failed = new Set();\\n        /** @type {OdooModuleLoader[\\"jobs\\"]} */\\n        jobs = new Set();\\n        /** @type {OdooModuleLoader[\\"modules\\"]} */\\n        modules = new Map();\\n\\n        /**\\n         * @param {HTMLElement} [root]\\n         */\\n        constructor(root) {\\n            this.root = root;\\n\\n            const strDebug = new URLSearchParams(location.search).get(\\"debug\\");\\n            this.debug = Boolean(strDebug && strDebug !== \\"0\\");\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"addJob\\"]} */\\n        addJob(name) {\\n            this.jobs.add(name);\\n            this.startModules();\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"define\\"]} */\\n        define(name, deps, factory, lazy = false) {\\n            if (typeof name !== \\"string\\") {\\n                throw new Error(`Module name should be a string, got: ${String(name)}`);\\n            }\\n            if (!Array.isArray(deps)) {\\n                throw new Error(\\n                    `Module dependencies should be a list of strings, got: ${String(deps)}`\\n                );\\n            }\\n            if (typeof factory !== \\"function\\") {\\n                throw new Error(`Module factory should be a function, got: ${String(factory)}`);\\n            }\\n            if (this.factories.has(name)) {\\n                return; // Ignore duplicate modules\\n            }\\n            this.factories.set(name, {\\n                deps,\\n                fn: factory,\\n                ignoreMissingDeps: globalThis.__odooIgnoreMissingDependencies,\\n            });\\n            if (!lazy) {\\n                this.addJob(name);\\n                this.checkErrorProm ||= Promise.resolve().then(() => {\\n                    this.checkErrorProm = null;\\n                    this.reportErrors(this.findErrors());\\n                });\\n            }\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"findErrors\\"]} */\\n        findErrors(moduleNames) {\\n            /**\\n             * @param {Iterable<string>} currentModuleNames\\n             * @param {Set<string>} visited\\n             * @returns {string | null}\\n             */\\n            const findCycle = (currentModuleNames, visited) => {\\n                for (const name of currentModuleNames || []) {\\n                    if (visited.has(name)) {\\n                        const cycleModuleNames = [...visited, name];\\n                        return cycleModuleNames\\n                            .slice(cycleModuleNames.indexOf(name))\\n                            .map((j) => `\\"${j}\\"`)\\n                            .join(\\" => \\");\\n                    }\\n                    const cycle = findCycle(dependencyGraph[name], new Set(visited).add(name));\\n                    if (cycle) {\\n                        return cycle;\\n                    }\\n                }\\n                return null;\\n            };\\n\\n            moduleNames ||= this.jobs;\\n\\n            /** @type {Record<string, Iterable<string>>} */\\n            const dependencyGraph = Object.create(null);\\n            /** @type {Set<string>} */\\n            const missing = new Set();\\n            /** @type {Set<string>} */\\n            const unloaded = new Set();\\n\\n            for (const moduleName of moduleNames) {\\n                const { deps, ignoreMissingDeps } = this.factories.get(moduleName);\\n\\n                dependencyGraph[moduleName] = deps;\\n\\n                if (ignoreMissingDeps) {\\n                    continue;\\n                }\\n\\n                unloaded.add(moduleName);\\n                for (const dep of deps) {\\n                    if (!this.factories.has(dep)) {\\n                        missing.add(dep);\\n                    }\\n                }\\n            }\\n\\n            const cycle = findCycle(moduleNames, new Set());\\n            const errors = {};\\n            if (cycle) {\\n                errors.cycle = cycle;\\n            }\\n            if (this.failed.size) {\\n                errors.failed = this.failed;\\n            }\\n            if (missing.size) {\\n                errors.missing = missing;\\n            }\\n            if (unloaded.size) {\\n                errors.unloaded = unloaded;\\n            }\\n            return errors;\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"findJob\\"]} */\\n        findJob() {\\n            for (const job of this.jobs) {\\n                if (this.factories.get(job).deps.every((dep) => this.modules.has(dep))) {\\n                    return job;\\n                }\\n            }\\n            return null;\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"reportErrors\\"]} */\\n        async reportErrors(errors) {\\n            if (!Object.keys(errors).length) {\\n                return;\\n            }\\n\\n            if (errors.failed) {\\n                console.error(\\"The following modules failed to load because of an error:\\", [\\n                    ...errors.failed,\\n                ]);\\n            }\\n            if (errors.missing) {\\n                console.error(\\n                    \\"The following modules are needed by other modules but have not been defined, they may not be present in the correct asset bundle:\\",\\n                    [...errors.missing]\\n                );\\n            }\\n            if (errors.cycle) {\\n                console.error(\\n                    \\"The following modules could not be loaded because they form a dependency cycle:\\",\\n                    errors.cycle\\n                );\\n            }\\n            if (errors.unloaded) {\\n                console.error(\\n                    \\"The following modules could not be loaded because they have unmet dependencies, this is a secondary error which is likely caused by one of the above problems:\\",\\n                    [...errors.unloaded]\\n                );\\n            }\\n\\n            const document = this.root?.ownerDocument || globalThis.document;\\n            if (document.readyState === \\"loading\\") {\\n                await new Promise((resolve) =>\\n                    document.addEventListener(\\"DOMContentLoaded\\", resolve)\\n                );\\n            }\\n\\n            if (this.debug) {\\n                const style = document.createElement(\\"style\\");\\n                style.className = \\"o_module_error_banner\\";\\n                style.textContent = `\\n                    body::before {\\n                        font-weight: bold;\\n                        content: \\"An error occurred while loading javascript modules, you may find more information in the devtools console\\";\\n                        position: fixed;\\n                        left: 0;\\n                        bottom: 0;\\n                        z-index: 100000000000;\\n                        background-color: #C00;\\n                        color: #DDD;\\n                    }\\n                `;\\n                document.head.appendChild(style);\\n            }\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"startModules\\"]} */\\n        startModules() {\\n            let job;\\n            while ((job = this.findJob())) {\\n                this.startModule(job);\\n            }\\n        }\\n\\n        /** @type {OdooModuleLoader[\\"startModule\\"]} */\\n        startModule(name) {\\n            /** @type {(dependency: string) => OdooModule} */\\n            const require = (dependency) => this.modules.get(dependency);\\n            this.jobs.delete(name);\\n            const factory = this.factories.get(name);\\n            /** @type {OdooModule | null} */\\n            let module = null;\\n            try {\\n                module = factory.fn(require);\\n            } catch (error) {\\n                this.failed.add(name);\\n                throw new Error(`Error while loading \\"${name}\\":\\\\n${error}`);\\n            }\\n            this.modules.set(name, module);\\n            this.bus.dispatchEvent(\\n                new CustomEvent(\\"module-started\\", {\\n                    detail: { moduleName: name, module },\\n                })\\n            );\\n            return module;\\n        }\\n    }\\n\\n    const loader = new ModuleLoader();\\n    odoo.define = loader.define.bind(loader);\\n    odoo.loader = loader;\\n\\n    if (odoo.debug && !loader.debug) {\\n        // remove debug mode if not explicitely set in url\\n        odoo.debug = \\"\\";\\n    }\\n})((globalThis.odoo ||= {}));\\n", "export class BaseWorker {\\n    constructor(name) {\\n        this.name = name;\\n        this.client = null; // only for testing purposes\\n    }\\n\\n    handleMessage(event) {\\n        const { action } = event.data;\\n        if (action === \\"BASE:INIT\\") {\\n            if (this.name.includes(\\"shared\\")) {\\n                event.target.postMessage({ type: \\"BASE:INITIALIZED\\" });\\n            } else {\\n                (this.client || globalThis).postMessage({ type: \\"BASE:INITIALIZED\\" });\\n            }\\n        }\\n    }\\n}\\n", "/* eslint-env worker */\\n/* eslint-disable no-restricted-globals */\\n\\nimport { BaseWorker } from \\"./base_worker\\";\\nimport { ElectionWorker } from \\"./election_worker\\";\\nimport { WebsocketWorker } from \\"./websocket_worker\\";\\n\\n(function () {\\n    const baseWorker = new BaseWorker(self.name);\\n    const websocketWorker = new WebsocketWorker(self.name);\\n    const electionWorker = new ElectionWorker();\\n\\n    if (self.name.includes(\\"shared\\")) {\\n        // The script is running in a shared worker.\\n        onconnect = (ev) => {\\n            const client = ev.ports[0];\\n            // Register the base worker to handle first init message.\\n            // Register the current client for main tab election.\\n            client.addEventListener(\\"message\\", (ev) => {\\n                baseWorker.handleMessage(ev);\\n                electionWorker.handleMessage(ev);\\n            });\\n            // let's register every tab connection to the worker in order to relay\\n            // notifications coming from the websocket.\\n            websocketWorker.registerClient(client);\\n            client.start();\\n        };\\n    } else {\\n        // The script is running in a simple web worker.\\n        self.addEventListener(\\"message\\", (ev) => baseWorker.handleMessage(ev));\\n        websocketWorker.registerClient(self);\\n    }\\n})();\\n", "/**\\n * Returns a function, that, as long as it continues to be invoked, will not\\n * be triggered. The function will be called after it stops being called for\\n * N milliseconds. If `immediate` is passed, trigger the function on the\\n * leading edge, instead of the trailing.\\n *\\n * Inspired by https://davidwalsh.name/javascript-debounce-function\\n */\\nexport function debounce(func, wait, immediate) {\\n    let timeout;\\n    return function () {\\n        const context = this;\\n        const args = arguments;\\n        function later() {\\n            timeout = null;\\n            if (!immediate) {\\n                func.apply(context, args);\\n            }\\n        }\\n        const callNow = immediate && !timeout;\\n        clearTimeout(timeout);\\n        timeout = setTimeout(later, wait);\\n        if (callNow) {\\n            func.apply(context, args);\\n        }\\n    };\\n}\\n\\n/**\\n * Deferred is basically a resolvable/rejectable extension of Promise.\\n */\\nexport class Deferred extends Promise {\\n    constructor() {\\n        let resolve;\\n        let reject;\\n        const prom = new Promise((res, rej) => {\\n            resolve = res;\\n            reject = rej;\\n        });\\n        return Object.assign(prom, { resolve, reject });\\n    }\\n}\\n\\nexport class Logger {\\n    static LOG_TTL = 24 * 60 * 60 * 1000; // 24 hours\\n    static gcInterval = null;\\n    static instances = [];\\n    _db;\\n\\n    static async gcOutdatedLogs() {\\n        const threshold = Date.now() - Logger.LOG_TTL;\\n        for (const logger of this.instances) {\\n            try {\\n                await logger._ensureDatabaseAvailable();\\n                await new Promise((res, rej) => {\\n                    const transaction = logger._db.transaction(\\"logs\\", \\"readwrite\\");\\n                    const store = transaction.objectStore(\\"logs\\");\\n                    const req = store\\n                        .index(\\"timestamp\\")\\n                        .openCursor(IDBKeyRange.upperBound(threshold));\\n                    req.onsuccess = (event) => {\\n                        const cursor = event.target.result;\\n                        if (cursor) {\\n                            cursor.delete();\\n                            cursor.continue();\\n                        }\\n                    };\\n                    req.onerror = (e) => rej(e.target.error);\\n                    transaction.oncomplete = res;\\n                    transaction.onerror = (e) => rej(e.target.error);\\n                });\\n            } catch (error) {\\n                console.error(`Failed to clear logs for logger \\"${logger._name}\\":`, error);\\n            }\\n        }\\n    }\\n\\n    constructor(name) {\\n        this._name = name;\\n        Logger.instances.push(this);\\n        Logger.gcOutdatedLogs();\\n        clearInterval(Logger.gcInterval);\\n        Logger.gcInterval = setInterval(() => Logger.gcOutdatedLogs(), Logger.LOG_TTL);\\n    }\\n\\n    async _ensureDatabaseAvailable() {\\n        if (this._db) {\\n            return;\\n        }\\n        return new Promise((res, rej) => {\\n            const request = indexedDB.open(this._name, 1);\\n            request.onsuccess = (event) => {\\n                this._db = event.target.result;\\n                res();\\n            };\\n            request.onupgradeneeded = (event) => {\\n                if (!event.target.result.objectStoreNames.contains(\\"logs\\")) {\\n                    const store = event.target.result.createObjectStore(\\"logs\\", {\\n                        autoIncrement: true,\\n                    });\\n                    store.createIndex(\\"timestamp\\", \\"timestamp\\", { unique: false });\\n                }\\n            };\\n            request.onerror = rej;\\n        });\\n    }\\n\\n    async log(message) {\\n        await this._ensureDatabaseAvailable();\\n        const transaction = this._db.transaction(\\"logs\\", \\"readwrite\\");\\n        const store = transaction.objectStore(\\"logs\\");\\n        const addRequest = store.add({ timestamp: Date.now(), message });\\n        return new Promise((res, rej) => {\\n            addRequest.onsuccess = res;\\n            addRequest.onerror = rej;\\n        });\\n    }\\n\\n    async getLogs() {\\n        await Logger.gcOutdatedLogs();\\n        awa