295	\N	\N	2026-01-29 19:43:05.937107	1	http://biblio.ohada.org/pmb/opac_css/doc_num.php?explnum_id=2063	{"en_US": ""}	l10n_syscohada	Odoo S.A.	/l10n_syscohada/static/description/icon.jpeg	uninstalled	\N	{"en_US": "OHADA - Accounting", "es_ES": "OHADA - Contabilidad"}	37	{"en_US": "\\nThis module implements the accounting chart for OHADA area.\\n===========================================================\\n\\nIt allows any company or association to manage its financial accounting.\\n\\nCountries that use OHADA are the following:\\n-------------------------------------------\\n    Benin, Burkina Faso, Cameroon, Central African Republic, Comoros, Congo,\\n\\n    Ivory Coast, Gabon, Guinea, Guinea Bissau, Equatorial Guinea, Mali, Niger,\\n\\n    Democratic Republic of the Congo, Senegal, Chad, Togo.\\n", "es_ES": "\\nEste módulo implementa el plan contable para el área de OHADA.\\n===========================================================\\n\\nPermite que cualquier empresa o asociación gestione su contabilidad financiera.\\n\\nEstos son los países que usan OHADA:\\n-------------------------------------------\\n    Benín, Burkina Faso, Camerún, República Centroafricana, Comoras, Congo,\\n\\n    Costa de Marfil, Gabón, Guinea, Guinea-Bisáu, Guinea Ecuatorial, Malí, Nigeria,\\n\\n    República Democrática del Congo, Senegal, Chad, Togo.\\n"}	f	f	f	LGPL-3	100	f	f	\N	\N	\N	\N				official	\N
