ids\\" widget=\\"many2many_tags\\" string=\\"Utilizado en\\" readonly=\\"True\\" groups=\\"base.group_multi_company\\" placeholder=\\"Visible para todos\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"bounce_alias\\" groups=\\"base.group_no_one\\" placeholder=\\"p. ej. &quot;rebote&quot;\\"/>\\n                            <field name=\\"catchall_alias\\" groups=\\"base.group_no_one\\" placeholder=\\"p. ej. &quot;catchall&quot;\\"/>\\n                            <field name=\\"default_from\\" groups=\\"base.group_no_one\\" placeholder=\\"p. ej. &quot;notificaciones&quot;\\"/>\\n                        </group>\\n                    </group>\\n                </sheet>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Alias Domain" duplicate="false">\n                <sheet>\n                    <group>\n                        <group>\n                            <label for="name"/>\n                            <div>\n                                <span class="me-1 oe_inline">@</span>\n                                <field name="name" string="Domain" class="oe_inline" placeholder="e.g. &quot;mycompany.com&quot;"/>\n                            </div>\n                            <field name="company_ids" widget="many2many_tags" string="Used In" readonly="True" groups="base.group_multi_company" placeholder="Visible to all"/>\n                        </group>\n                        <group>\n                            <field name="bounce_alias" groups="base.group_no_one" placeholder="e.g. &quot;bounce&quot;"/>\n                            <field name="catchall_alias" groups="base.group_no_one" placeholder="e.g. &quot;catchall&quot;"/>\n                            <field name="default_from" groups="base.group_no_one" placeholder="e.g. &quot;notifications&quot;"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>\n        	f	t	