:\n                                        <span t-esc="forced_vat">US12345671</span>\n                                    </li>\n                                </ul>\n                            </div>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <!-- BODY -->\n        <t t-set="layout_background_url" t-value="'data:image/png;base64,%s' % company.layout_background_image.decode('utf-8') if company.layout_background_image and company.layout_background == 'Custom' else                 '/base/static/img/demo_logo_report.png' if company.layout_background == 'Demo logo' else ''"/>\n        <div t-attf-class="article o_report_layout_bubble o_table_boxed-rounded o_company_#{company.id}_layout {{'o_report_layout_background' if company.layout_background != 'Blank' else ''}}" t-attf-style="{{ 'background-image: url(%s);' % layout_background_url if layout_background_url else '' }}" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get('lang')">\n            <table class="o_ignore_layout_styling table table-borderless mb-0">\n                <tbody>\n                    <tr>\n                        <td t-attf-class="p-0 {{'pt-3' if information_block else ''}}">\n                            <t t-call="web.address_layout" custom_layout_address="true"/>\n                        </td>\n                        <td t-if="not information_block" class="align-bottom p-0 ps-2">\n                            <h2 class="mb-4 text-nowrap text-end" t-out="layout_document_title"/>\n                        </td>\n                    </tr>\n                    <tr t-if="information_block">\n                        <td colspan="2" class="align-bottom p-0">\n                            <h2 class="text-nowrap text-end" t-out="layout_document_title"/>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\