', 'text', 'html']\\" readonly=\\"ttype not in ['char', 'text', 'html']\\"/>\\n                                                    <field name=\\"size\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['char', 'reference']\\" readonly=\\"ttype not in ['char', 'reference']\\"/>\\n                                                    <field name=\\"relation\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" required=\\"ttype in ['many2one', 'one2many', 'many2many']\\"/>\\n                                                    <field name=\\"on_delete\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2one'\\" readonly=\\"ttype != 'many2one'\\"/>\\n                                                    <field name=\\"relation_field\\" invisible=\\"ttype != 'one2many'\\" readonly=\\"ttype != 'one2many'\\" required=\\"ttype == 'one2many'\\"/>\\n                                                    <field name=\\"relation_table\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"column1\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"column2\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                                    <field name=\\"domain\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\"/>\\n                                                </group>\\n                                            </group>\\n                                            <group invisible=\\"ttype not in ['selection', 'reference']\\" readonly=\\"ttype not in ['selection', 'reference']\\">\\n                                                <field name=\\"selection_ids\\">\\n                                                    <list editable=\\"bottom\\">\\n                                                        <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                                        <field name=\\"value\\"/>\\n                                                        <field name=\\"name\\"/>\\n                                                    </list>\\n                                                </field>\\n                                            </group>\\n                                        </page>\\n                                        <page name=\\"compute\\" string=\\"Calcular\\" groups=\\"base.group_no_one\\">\\n                                            <group>\\n                                                <field name=\\"related\\"/>\\n                                                <field name=\\"depends\\" required=\\"compute not in [False, '']\\"/>\\n                                                <field name=\\"compute\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\"/>\\n                                            </group>\\n                                            <div>\\n                                                <h3>Cómo definir un campo calculado</h3>\\n                                                <p>Los campos calculados son definidos con los campos\\n                                                <strong>Dependencias</strong> y <strong>Calcular</strong>.</p>\\n                                                <p>El campo <strong>Dependencias</strong> enlista los campos de los que\\n                                                depende el campo actual. Es una lista de nombres de campos\\n                                                separados por comas, como <code>nombre, tamaño</code>. También se puede referir a \\n                                                campos accesibles a través de otros campos relacionales, por ejemplo\\n                                                <code>partner_id.company_id.name</code>.</p>\\n                                                <p>El campo <strong>Calcular</strong> es el código Python\\n                                                para calcular el valor del campo en un conjunto de registros. El valor del\\n                                                campo debe asignarse a cada registro con una asignación\\n                                                como de diccionario.</p>\\n                                                <pre>\\n    para registrar en self:\\n        record['size'] = len(record.name)\\n</pre>\\n                                                <p>Las únicas variables predefinidas</p>\\n                                                <ul>\\n                                                    <li><code>self</code> (el conjunto de registros para calcular)</li>\\n                                                    <li><code>datetime</code> (Módulo Python)</li>\\n                                                    <li><code>dateutil</code> (Módulo Python)</li>\\n                                                    <li><code>time</code> (Módulo Python)</li>\\n                                                </ul>\\n                                                <p>Se puede acceder a otras funciones a través de <code>self</code>, como\\n<code>self.env</code>, etc.</p>\\n                                            </div>\\n                                        </page>\\n                                        <page name=\\"groups\\" string=\\"Permisos de acceso\\">\\n                                            <field name=\\"groups\\"/>\\n                                        </page>\\n                