style="font-family:Verdana, Arial,sans-serif; color: #454748;">\n<t t-set="subtype_internal" t-value="subtype and subtype.internal"/>\n<t t-set="show_header" t-value="email_notification_force_header or (     email_notification_allow_header and has_button_access)"/>\n<t t-set="show_footer" t-value="email_notification_force_footer or (     email_notification_allow_footer and show_header and author_user and author_user._is_internal())"/>\n<!-- HEADER -->\n<t t-call="mail.notification_preview"/>\n<div style="max-width: 900px; width: 100%;">\n<div t-if="show_header and has_button_access" itemscope="itemscope" itemtype="http://schema.org/EmailMessage">\n    <div itemprop="potentialAction" itemscope="itemscope" itemtype="http://schema.org/ViewAction">\n        <link itemprop="target" t-att-href="button_access['url']"/>\n        <link itemprop="url" t-att-href="button_access['url']"/>\n        <meta itemprop="name" t-att-content="button_access['title']"/>\n    </div>\n</div>\n<div t-if="show_header and (subtitles or has_button_access or not is_discussion)" summary="o_mail_notification" style="padding: 0px;">\n    <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="width: 100%; margin-top: 5px;">\n        <tbody>\n            <tr>\n                <td valign="center" style="white-space:nowrap;">\n                    <table cellspacing="0" cellpadding="0" border="0">\n                        <tbody>\n                            <tr>\n                                <td t-if="has_button_access" t-att-style="'border-radius: 3px; text-align: center; background: ' + (company.email_secondary_color or '#875A7B') + ';'">\n                                    <a t-att-href="button_access['url']" t-att-style="'font-size: 12px; color: ' + (company.email_primary_color or '#FFFFFF') + '; display: block; padding: 8px 12px 11px; text-decoration: none !important; font-weight: bold;'">\n                                        <t t-out="button_access['title']"/>\n                                    </a>\n                                </td>\n                                <td t-if="has_button_access">&amp;nbsp;&amp;nbsp;</td>\n                                <td t-if="subtitles" style="font-size: 12px;">\n                                     <t t-foreach="subtitles" t-as="subtitle">\n                                        <span t-attf-style="{{ 'font-weight:bold;' if subtitle_first else '' }}" t-out="subtitle"/>\n                                        <br t-if="not subtitle_last"/>\n                                    </t>\n                                </td>\n                                <td t-else=""><span style="font-weight:bold;" t-out="record_name or (message.record_name and message.record_name.replace('/','-')) or ''"/><br/></td>\n\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n            <tr>\n                <td valign="center">\n                    <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0;margin: 10px 0px;"/>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n<!-- CONTENT -->\n<div t-out="message.body" style="font-size: 13px;"/>\n<ul t-if="tracking_values">\n    <t t-foreach="tracking_values" t-as="tracking">\n        <li><t t-out="tracking[0]"/>: <t t-if="tracking[1]" t-out="tracking[1]"/><em t-else="">None</em> → <t t-if="tracking[2]" t-out="tracking[2]"/><em t-else="">None</em></li>\n    </t>\n</ul>\n<t class="o_signature">\n    <div t-if="email_add_signature and not is_html_empty(signature)" t-out="signature" class="o_signature" style="font-size: 13px;"/>\n</t>\n<!-- FOOTER -->\n<div t-if="show_footer" style="margin-top:16px;">\n    <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 4px 0px;"/>\n    <b t-out="company.name" style="font-size:11px;"/><br/>\n    <p style="color: #999999; margin-top:2px; font-size:11px;">\n        <t t-out="company.phone"/>\n        <t t-if="company.email and company.phone"> |</t>\n        <a t-if="company.email" t-att-href="'mailto:%s' % company.email" style="text-decoration:none; color: #999999;" t-out="company.email"/>\n        <t t-if="company.website and (company.phone or company.email)"> |</t>\n        <a t-if="company.website" t-att-href="'%s' % company.website" style="text-decoration:none; color: #999999;" t-out="company.website"/>\n    </p>\n</div>\n<div t-if="show_footer" style="color: #555555; font-size:11px;">\n    Powered by <a target="_blank" href="https://www.odoo.com?utm_source=db&amp;utm_medium=email" t-att-style="'color: ' + (company.email_secondary_color or '#875A7B') + ';'">Odoo</a>\n    <span t-if="show_unfollow" id="mail_unfollow">\n        | <a href="/mail/unfollow" style="text-decoration:none; color:#555555;">Unfollow</a>\n    </span>\n</div>\n</div>\n</body></html>\n        </t>\n\n        	f	t	2026-01-23 09:22:43.628352	2026-01-23 09:22:43.628352
50	16	\N	1	1	ir.model.fields form	ir.model.fields	\N	form	base/views/ir_model_views.xml	primary	{"en_US": "<form string=\\"Fields\\" duplicate=\\"false\\">\\n                    <sheet>\\n                        <group>\\n                            <group>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"field_description\\"/>\\n                                <field name=\\"model_id\\" readonly=\\"state != 'manual'\\"/>\\n                            </group>\\n                            <group>\\n                                <field name=\\"ttype\\"/>\\n                                <field name=\\"help\\"/>\\n                            </group>\\n                        </group>\\n                        <notebook>\\n                            <page name=\\"base\\" string=\\"Properties\\">\\n                                <group>\\n                                    <group>\\n                                        <field name=\\"required\\"/>\\n                                        <field name=\\"readonly\\"/>\\n                                        <field name=\\"store\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"index\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"copied\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"state\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"modules\\" groups=\\"base.group_no_one\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"translate\\" invisible=\\"ttype not in ['char', 'text', 'html']\\" readonly=\\"ttype not in ['char', 'text', 'html']\\"/>\\n                                        <field name=\\"size\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['char', 'reference']\\" readonly=\\"ttype not in ['char', 'reference']\\"/>\\n                                        <field name=\\"relation\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" required=\\"ttype in ['many2one', 'one2many', 'many2many']\\"/>\\n                                        <field name=\\"group_expand\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'selection']\\" readonly=\\"ttype not in ['many2one', 'selection']\\"/>\\n                                        <field name=\\"on_delete\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2one'\\" readonly=\\"ttype != 'many2one'\\"/>\\n                                        <field name=\\"relation_field\\" invisible=\\"ttype != 'one2many'\\" readonly=\\"ttype != 'one2many'\\" required=\\"ttype == 'one2many'\\"/>\\n                                        <field name=\\"relation_table\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column1\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column2\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"domain\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\"/>\\n                                        <field name=\\"currency_field\\" invisible=\\"ttype != 'monetary'\\" readonly=\\"ttype != 'monetary'\\"/>\\n                                    </group>\\n                                </group>\\n                                <group string=\\"HTML/Sanitization Properties\\" invisible=\\"ttype != 'html'\\">\\n                                    <group>\\n                                        <field name=\\"sanitize\\" invisible=\\"ttype != 'html'\\" readonly=\\"ttype != 'html'\\"/>\\n                                        <field name=\\"sanitize_overridable\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_tags\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_attributes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"sanitize_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_form\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_classes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                </group>\\n                                <group invisible=\\"ttype not in ['selection', 'reference']\\" readonly=\\"ttype not in ['selection', 'reference']\\">\\n                                    <field name=\\"selection_ids\\">\\n                                        <list editable=\\"bottom\\">\\n                                            <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                            <field name=\\"value\\"/>\\n                                            <field name=\\"name\\"/>\\n                                        </list>\\n                                    </field>\\n                                </group>\\n                            </page>\\n                            <page name=\\"compute\\" string=\\"Compute\\" groups=\\"base.group_no_one\\">\\n                                <group>\\n                                    <field name=\\"related\\"/>\\n                                    <field name=\\"depends\\" required=\\"bool(compute) and store\\"/>\\n                                    <field name=\\"compute\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\"/>\\n                                </group>\\n                                <div>\\n                                    <h3>How to define a computed field</h3>\\n                                    <p>Computed fields are defined with the fields\\n                                    <strong>Dependencies</strong> and <strong>Compute</strong>.</p>\\n                                    <p>The field <strong>Dependencies</strong> lists the fields that\\n                                    the current field depends on. It is a comma-separated list of\\n                                    field names, like <code>name, size</code>. You can also refer to\\n                                    fields accessible through other relational fields, for instance\\n                                    <code>partner_id.company_id.name</code>.</p>\\n                                    <p>The field <strong>Compute</strong> is the Python code to\\n                                    compute the value of the field on a set of records. The value of\\n                                    the field must be assigned to each record with a dictionary-like\\n                                    assignment.</p>\\n                                    <pre>\\n    for record in self:\\n        record['size'] = len(record.name)\\n</pre>\\n                                    <p>The only predefined variables are</p>\\n                                    <ul>\\n                                        <li><code>self</code> (the set of records to compute)</li>\\n                                        <li><code>datetime</code> (Python module)</li>\\n                                        <li><code>dateutil</code> (Python module)</li>\\n                                        <li><code>time</code> (Python module)</li>\\n                                    </ul>\\n                                    <p>Other features are accessible through <code>self</code>, like\\n                                    <code>self.env</code>, etc.</p>\\n                                </div>\\n                            </page>\\n                            <page name=\\"groups\\" string=\\"Access Rights\\">\\n                                <field name=\\"groups\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                </form>", "es_ES": "<form string=\\"Campos\\" duplicate=\\"false\\">\\n                    <sheet>\\n                        <group>\\n                            <group>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"field_description\\"/>\\n                                <field name=\\"model_id\\" readonly=\\"state != 'manual'\\"/>\\n                            </group>\\n                            <group>\\n                                <field name=\\"ttype\\"/>\\n                                <field name=\\"help\\"/>\\n                            </group>\\n                        </group>\\n                        <notebook>\\n                            <page name=\\"base\\" string=\\"Propiedades\\">\\n                                <group>\\n                                    <group>\\n                                        <field name=\\"required\\"/>\\n                                        <field name=\\"readonly\\"/>\\n                                        <field name=\\"store\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"index\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"copied\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"state\\" groups=\\"base.group_no_one\\"/>\\n                                        <field name=\\"modules\\" groups=\\"base.group_no_one\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"translate\\" invisible=\\"ttype not in ['char', 'text', 'html']\\" readonly=\\"ttype not in ['char', 'text', 'html']\\"/>\\n                                        <field name=\\"size\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['char', 'reference']\\" readonly=\\"ttype not in ['char', 'reference']\\"/>\\n                                        <field name=\\"relation\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" required=\\"ttype in ['many2one', 'one2many', 'many2many']\\"/>\\n                                        <field name=\\"group_expand\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'selection']\\" readonly=\\"ttype not in ['many2one', 'selection']\\"/>\\n                                        <field name=\\"on_delete\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2one'\\" readonly=\\"ttype != 'many2one'\\"/>\\n                                        <field name=\\"relation_field\\" invisible=\\"ttype != 'one2many'\\" readonly=\\"ttype != 'one2many'\\" required=\\"ttype == 'one2many'\\"/>\\n                                        <field name=\\"relation_table\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column1\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column2\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"domain\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\"/>\\n                                        <field name=\\"currency_field\\" invisible=\\"ttype != 'monetary'\\" readonly=\\"ttype != 'monetary'\\"/>\\n                                    </group>\\n                                </group>\\n                                <group string=\\"HTML/Propiedades de depuración\\" invisible=\\"ttype != 'html'\\">\\n                                    <group>\\n                                        <field name=\\"sanitize\\" invisible=\\"ttype != 'html'\\" readonly=\\"ttype != 'html'\\"/>\\n                                        <field name=\\"sanitize_overridable\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_tags\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_attributes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"sanitize_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_form\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_style\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"strip_classes\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                    </group>\\n                                </group>\\n                                <group invisible=\\"ttype not in ['selection', 'reference']\\" readonly=\\"ttype not in ['selection', 'reference']\\">\\n                                    <field name=\\"selection_ids\\">\\n                                        <list editable=\\"bottom\\">\\n                                            <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                            <field name=\\"value\\"/>\\n                                            <field name=\\"name\\"/>\\n                                        </list>\\n                                    </field>\\n                                </group>\\n                            </page>\\n                            <page name=\\"compute\\" string=\\"Calcular\\" groups=\\"base.group_no_one\\">\\n                                <group>\\n                                    <field name=\\"related\\"/>\\n                                    <field name=\\"depends\\" required=\\"bool(compute) and store\\"/>\\n                                    <field name=\\"compute\\" widget=\\"code\\" options=\\"{'mode': 'python'}\\"/>\\n                                </group>\\n                                <div>\\n                                    <h3>Cómo definir un campo calculado</h3>\\n                                    <p>Los campos calculados son definidos con los campos <strong>Dependencias</strong> y <strong>Calcular</strong>.</p>\\n                                    <p>El campo <strong>Dependencias</strong> enlista los campos de los que\\n                                                depende el campo actual. Es una lista de nombres de campos\\n                                                separados por compas, como <code>nombre, tamaño</code>. También se puede referir a \\n                                                campos accesibles a través de otros campos relacionales, por ejemplo\\n                                                <code>partner_id.company_id.name</code>.</p>\\n                                    <p>El campo <strong>Calcular</strong> es el código Python\\n                                       para calcular el valor del campo en un conjunto de registros. El valor del\\n                                       campo debe asignarse a cada registro con una asignación\\n                                        como de diccionario.</p>\\n                                    <pre>\\n    para registrar en self:\\n        record['size'] = len(record.name)\\n</pre>\\n                                    <p>Las únicas variables predefinidas</p>\\n                                    <ul>\\n                                        <li><code>self</code> (el conjunto de registros para calcular)</li>\\n                                        <li><code>datetime</code> (Módulo Python)</li>\\n                                        <li><code>dateutil</code> (Módulo Python)</li>\\n                                        <li><code>time</code> (Módulo Python)</li>\\n                                    </ul>\\n                                    <p>Se puede acceder a otras funciones a través de <code>self</code>, como\\n<code>self.env</code>, etc.</p>\\n                                </div>\\n                            </page>\\n                            <page name=\\"groups\\" string=\\"Permisos de acceso\\">\\n                                <field name=\\"groups\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Fields" duplicate="false">\n                    <sheet>\n                        <group>\n                            <group>\n                                <field name="name"/>\n                                <field name="field_description"/>\n                                <field name="model_id" readonly="state != 'manual'"/>\n                            </group>\n                            <group>\n                                <field name="ttype"/>\n                                <field name="help"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page name="base" string="Properties">\n                                <group>\n                                    <group>\n                                        <field name="required"/>\n                                        <field name="readonly"/>\n                                        <field name="store" groups="base.group_no_one"/>\n                                        <field name="index" groups="base.group_no_one"/>\n                                        <field name="copied" groups="base.group_no_one"/>\n                                        <field name="state" groups="base.group_no_one"/>\n                                        <field name="modules" groups="base.group_no_one"/>