elacionados\\"/>\\n                        </t>\\n                    </header>\\n                    <sheet>\\n                        <div class=\\"oe_title\\">\\n                            <label for=\\"name\\"/>\\n                            <h1><field name=\\"name\\" class=\\"w-100\\" string=\\"Nombre de la plantilla\\" required=\\"1\\" placeholder=\\"p. ej. &quot;Correo de bienvenida&quot;\\"/></h1>\\n                            <group>\\n                                <field name=\\"model_id\\" groups=\\"!base.group_no_one\\" invisible=\\"context.get('default_model')\\" placeholder=\\"p. ej. contacto\\" required=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"model_id\\" groups=\\"base.group_no_one\\" placeholder=\\"p. ej. contacto\\" required=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                                <field name=\\"subject\\" options=\\"{'dynamic_placeholder': true}\\" placeholder=\\"por ejemplo:  &quot;Le damos la bienvenida a MiCompañía&quot; o &quot;Gusto en conocerlo, {{ object.name }}&quot;\\"/>\\n                                <field name=\\"model\\" invisible=\\"1\\"/>\\n                            </group>\\n                        </div>\\n                        <notebook>\\n                            <page string=\\"Cuerpo\\" name=\\"content\\">\\n                                <field name=\\"can_write\\" invisible=\\"1\\"/>\\n                                <field name=\\"body_html\\" widget=\\"html_mail\\" class=\\"oe-bordered-editor\\" placeholder=\\"Escriba su mensaje aquí...\\" options=\\"{'codeview': true, 'dynamic_placeholder': true, 'allowCommandVideo': false}\\" readonly=\\"not can_write and id\\"/>\\n                                <div invisible=\\"not can_write\\" class=\\"fst-italic text-muted\\">Tip: Write /field to insert dynamic content!</div>\\n                            </page>\\n                            <page string=\\"Ajustes\\" name=\\"email_configuration