196	16	\N	1	1	webclient_offline	\N	web.webclient_offline	qweb	web/views/webclient_templates.xml	primary	{"en_US": "<t t-name=\\"web.webclient_offline\\">\\n        <t t-call=\\"web.layout\\">\\n            <t t-set=\\"html_data\\" t-value=\\"{'style': 'height: 100%;'}\\"/>\\n            <t t-set=\\"title\\">Offline</t>\\n            <t t-set=\\"head\\">\\n                <script type=\\"text/javascript\\">\\n                    document.addEventListener(\\"DOMContentLoaded\\", () =&gt; {\\n                        const cookies = document.cookie.split(';').map(c =&gt; c.trim());\\n                        if (cookies.includes('color_scheme=dark')) {\\n                            document.body.style.backgroundColor = \\"#262A36\\";\\n                            document.body.style.color = \\"#FFFFFF\\";\\n                        }\\n                    });\\n                    window.addEventListener('online', () =&gt; location.reload());\\n                </script>\\n                <style>\\n                    body {\\n                    font-family: -apple-system, BlinkMacSystemFont, \\"Segoe UI\\", Roboto, \\"Helvetica Neue\\", Ubuntu, \\"Noto Sans\\", Arial, sans-serif, \\"Apple Color Emoji\\", \\"Segoe UI Emoji\\", \\"Segoe UI Symbol\\", \\"Noto Color Emoji\\";\\n                    padding:0;\\n                    margin:0;\\n                    background-color: #fff;\\n                    color: rgb(17, 24, 39);\\n                    display: flex;\\n                    align-items: center;\\n                    justify-content: center;\\n                    text-align: center;\\n                    height: 100vh;\\n                    width: 100vw;\\n                    user-select: none;\\n                    }\\n                    .card {\\n                    width: 80%;\\n                    }\\n                    .card img {\\n                    width: 96px;\\n                    height: auto;\\n                    filter: grayscale(.6);\\n        